package com.bestiary.service;

import com.bestiary.model.Achievement;
import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;
import com.bestiary.model.MonsterRoster;
import com.bestiary.util.XpTable;
import net.runelite.api.NPC;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.util.List;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ProgressionServiceTest {

    @Mock private NPC npc;

    private ProgressionService service;
    private BestiaryCollection collection;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        when(npc.getName()).thenReturn("Goblin");
        when(npc.getId()).thenReturn(100);
        when(npc.getCombatLevel()).thenReturn(2);

        service    = new ProgressionService();
        collection = new BestiaryCollection();
        service.init(new ProgressionService.ProgressionState(), collection);
    }

    // --- XP table ---

    @Test
    public void level1RequiresZeroXp() {
        assertEquals(0, XpTable.xpForLevel(1));
    }

    @Test
    public void level2XpIsPositive() {
        assertTrue(XpTable.xpForLevel(2) > 0);
    }

    @Test
    public void xpTableIsStrictlyIncreasing() {
        for (int lvl = 2; lvl <= 126; lvl++) {
            assertTrue("XP for " + lvl + " should exceed XP for " + (lvl - 1),
                    XpTable.xpForLevel(lvl) > XpTable.xpForLevel(lvl - 1));
        }
    }

    @Test
    public void levelForZeroXpIsOne() {
        assertEquals(1, XpTable.levelForXp(0));
    }

    @Test
    public void levelForMaxXpIs126() {
        assertEquals(126, XpTable.levelForXp(XpTable.maxXp()));
    }

    // --- Kill XP ---

    @Test
    public void killXpMatchesDifficultyTier() {
        assertEquals(5L,  ProgressionService.killXp(DifficultyTier.BEGINNER));
        assertEquals(10L, ProgressionService.killXp(DifficultyTier.EASY));
        assertEquals(15L, ProgressionService.killXp(DifficultyTier.MEDIUM));
        assertEquals(20L, ProgressionService.killXp(DifficultyTier.HARD));
        assertEquals(25L, ProgressionService.killXp(DifficultyTier.ELITE));
        assertEquals(30L, ProgressionService.killXp(DifficultyTier.BOSS));
    }

    @Test
    public void recordKillAwardsTierXp() {
        long before = service.getTotalXp();
        service.recordKill(npc); // "Goblin", combat level 2
        long gained = service.getTotalXp() - before;
        DifficultyTier tier = MonsterRoster.getDifficulty("Goblin", 2);
        assertEquals(ProgressionService.killXp(tier), gained);
    }

    // --- Capture XP ---

    @Test
    public void commonCaptureAwardsBaseXp() {
        CapturedCreature c = CapturedCreature.builder()
                .npcId(1).npcName("Rat").npcCombatLevel(1)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(c);
        service.recordCapture(c, true);
        // Kill XP for combat level 1 = max(10, 1*10) = 10; * 1.0 = 10
        assertEquals(10L, service.getTotalXp());
    }

    @Test
    public void rareCaptureAwardsHigherXpThanCommon() {
        CapturedCreature rare = CapturedCreature.builder()
                .npcId(1).npcName("Dragon").npcCombatLevel(100)
                .rarity(CreatureRarity.RARE).build();
        collection.addCapture(rare);
        service.recordCapture(rare, true);

        long rareXp = service.getTotalXp();

        service.init(new ProgressionService.ProgressionState(), collection);

        CapturedCreature common = CapturedCreature.builder()
                .npcId(1).npcName("Dragon").npcCombatLevel(100)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(common);
        service.recordCapture(common, true);

        long commonXp = service.getTotalXp();

        assertTrue("Rare should award more XP than Common", rareXp > commonXp);
    }

    // --- Achievements ---

    @Test
    public void firstCatchUnlocksOnFirstCapture() {
        CapturedCreature c = CapturedCreature.builder()
                .npcId(1).npcName("Rat").npcCombatLevel(1)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(c);
        collection.recordLifetimeCapture(c.npcName);   // a genuine capture bumps the lifetime counter

        List<Achievement> newAchievements = service.recordCapture(c, true);
        assertTrue(newAchievements.contains(Achievement.FIRST_CATCH));
    }

    @Test
    public void rareCatchAchievementUnlocksOnRareCapture() {
        CapturedCreature c = CapturedCreature.builder()
                .npcId(1).npcName("Dragon").npcCombatLevel(100)
                .rarity(CreatureRarity.RARE).build();
        collection.addCapture(c);

        List<Achievement> newAchievements = service.recordCapture(c, true);
        assertTrue(newAchievements.contains(Achievement.RARE_CATCH));
    }

    @Test
    public void firstCatchNotAwardedTwice() {
        CapturedCreature c1 = CapturedCreature.builder().npcId(1).npcName("A").npcCombatLevel(1)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(c1);
        collection.recordLifetimeCapture(c1.npcName);
        service.recordCapture(c1, true);

        CapturedCreature c2 = CapturedCreature.builder().npcId(2).npcName("B").npcCombatLevel(1)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(c2);
        collection.recordLifetimeCapture(c2.npcName);
        List<Achievement> second = service.recordCapture(c2, true);
        assertFalse(second.contains(Achievement.FIRST_CATCH));
    }

    // --- Level tracking ---

    @Test
    public void startAtLevel1() {
        assertEquals(1, service.getLevel());
    }

    @Test
    public void levelIncreaseWhenXpThresholdCrossed() {
        long xpNeeded = XpTable.xpForLevel(2);
        long perKill  = ProgressionService.killXp(MonsterRoster.getDifficulty("Goblin", 2));
        long kills    = xpNeeded / perKill + 1;
        for (long i = 0; i < kills; i++) service.recordKill(npc);
        assertTrue(service.getLevel() >= 2);
    }

    // --- Progression credits (#58) ---

    @Test
    public void achievementUnlockAwardsItsCreditReward() {
        long[] awarded = {0};
        service.setCreditAwarder(amount -> awarded[0] += amount);

        CapturedCreature c = CapturedCreature.builder()
                .npcId(1).npcName("Rat").npcCombatLevel(1)
                .rarity(CreatureRarity.COMMON).build();
        collection.addCapture(c);
        collection.recordLifetimeCapture(c.npcName);
        service.recordCapture(c, false); // no XP -> only the FIRST_CATCH achievement bounty

        assertEquals(Achievement.FIRST_CATCH.creditReward, awarded[0]);
    }

    @Test
    public void levelUpAwardsPerLevelCredits() {
        long[] awarded = {0};
        service.setCreditAwarder(amount -> awarded[0] += amount);

        long xpNeeded = XpTable.xpForLevel(2);
        long perKill  = ProgressionService.killXp(MonsterRoster.getDifficulty("Goblin", 2));
        long kills    = xpNeeded / perKill + 1;
        for (long i = 0; i < kills; i++) service.recordKill(npc);

        assertTrue(service.getLevel() >= 2);
        assertTrue("level-up should grant level x 10 credits",
                awarded[0] >= ProgressionService.levelUpCredits(2));
    }
}

package com.bestiary.service;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureQuality;
import com.bestiary.model.CreatureRarity;
import org.junit.Test;

import java.lang.reflect.Type;
import java.time.Instant;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Guards the JSON persistence: a capture (with Instant, enums, shiny and reroll history)
 * must round-trip losslessly through the same Gson shape the store uses.
 */
public class StoreSerializationTest {

    /** Mirrors BestiaryStore's Instant<->epoch-second adapter. */
    private static final class InstantAdapter
            implements JsonSerializer<Instant>, JsonDeserializer<Instant> {
        public JsonElement serialize(Instant s, Type t, JsonSerializationContext c) {
            return new JsonPrimitive(s.getEpochSecond());
        }
        public Instant deserialize(JsonElement j, Type t, JsonDeserializationContext c) {
            return Instant.ofEpochSecond(j.getAsLong());
        }
    }

    private Gson gson() {
        return new GsonBuilder()
                .registerTypeAdapter(Instant.class, new InstantAdapter())
                .create();
    }

    @Test
    public void capturedCreatureRoundTrips() {
        CapturedCreature c = CapturedCreature.builder()
                .npcId(5).npcName("Goblin").npcCombatLevel(2)
                .rarity(CreatureRarity.MYTHIC)
                .quality(new CreatureQuality(90, 80, 70, 60, 50, 40, 33))
                .captureTime(Instant.ofEpochSecond(1_700_000_000L))
                .regionName("Lumbridge").captureLevel(50).killsBeforeCapture(7)
                .playerName("Zezima").shiny(true).observedHp(120)
                .rerolledBy("Zezima")
                .rerollHistory(Collections.singletonList(
                        new CapturedCreature.RerollState(CreatureRarity.EPIC,
                                new CreatureQuality(40, 41, 42, 43, 44, 45, 10), 42, false, "Zezima", 1_699_000_000L)))
                .build();

        Gson g = gson();
        CapturedCreature back = g.fromJson(g.toJson(c), CapturedCreature.class);

        assertEquals(c.id, back.id);
        assertEquals(c.npcName, back.npcName);
        assertEquals(c.rarity, back.rarity);
        assertEquals(c.captureTime, back.captureTime);
        assertEquals(c.quality.attack, back.quality.attack);
        assertEquals(c.quality.agility, back.quality.agility);
        assertTrue(back.isShiny());
        assertEquals(c.quality.prayer, back.quality.prayer);
        assertEquals(c.observedHp, back.observedHp);
        assertEquals(1, back.rerollCount());
        assertEquals("Zezima", back.rerollHistory.get(0).rerolledBy);
        assertEquals(CreatureRarity.EPIC, back.rerollHistory.get(0).rarity);
        assertEquals(c.powerLevel(), back.powerLevel());
        // Owners default to the capturer and survive the round-trip.
        assertEquals("Zezima", back.originalOwner);
        assertEquals("Zezima", back.currentOwner);
    }

    @Test
    public void transferUpdatesCurrentOwnerNotOriginal() {
        CapturedCreature c = CapturedCreature.builder()
                .npcName("Goblin").playerName("MainRSN").build();
        assertEquals("MainRSN", c.originalOwner);
        assertEquals("MainRSN", c.currentOwner);

        c.transferTo("AltRSN");
        assertEquals("original owner is immutable across a transfer", "MainRSN", c.originalOwner);
        assertEquals("current owner follows the transfer", "AltRSN", c.currentOwner);
    }

    @Test
    public void storeDataRoundTrips() {
        BestiaryStore.StoreData d = new BestiaryStore.StoreData();
        d.credits = 12_345L;
        d.totalXp = 99_999L;
        d.killCounts.put("Goblin", 42);
        d.achievements.add("SHINY_CATCH");

        Gson g = gson();
        BestiaryStore.StoreData back = g.fromJson(g.toJson(d), BestiaryStore.StoreData.class);

        assertEquals(BestiaryStore.VERSION, back.version);
        assertEquals(12_345L, back.credits);
        assertEquals(99_999L, back.totalXp);
        assertEquals(Integer.valueOf(42), back.killCounts.get("Goblin"));
        assertEquals("SHINY_CATCH", back.achievements.get(0));
    }
}

package com.bestiary.service;

import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.game.NpcUtil;
import org.junit.Before;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class KillTrackerTest {

    private NpcUtil npcUtil;
    private KillTracker tracker;
    private NPC npc;

    @Before
    public void setUp() {
        npcUtil = mock(NpcUtil.class);
        tracker = new KillTracker(mock(Client.class), npcUtil);
        npc = mock(NPC.class);
        when(npc.getIndex()).thenReturn(42);
        when(npc.getName()).thenReturn("Kurask");
    }

    private void hit(int amount) {
        Hitsplat hs = mock(Hitsplat.class);
        when(hs.isMine()).thenReturn(true);
        when(hs.getAmount()).thenReturn(amount);
        HitsplatApplied e = new HitsplatApplied();
        e.setActor(npc);
        e.setHitsplat(hs);
        tracker.onHitsplatApplied(e);
    }

    private void die() {
        when(npc.isDead()).thenReturn(true); // RuneLite sets isDead() as the health bar hits 0
        tracker.onActorDeath(new ActorDeath(npc));
    }

    private void despawn() {
        tracker.onNpcDespawned(new NpcDespawned(npc)).ifPresent(k -> {
            throw new AssertionError("despawn credited an already-settled kill");
        });
    }

    @Test
    public void hitThenDeathOrder_creditsOnceWithFullDamage() {
        // RuneLite <= 1.12.39: killing hitsplat, then ActorDeath.
        hit(60);
        hit(37);
        die();
        List<KillTracker.Kill> kills = tracker.onGameTick();
        assertEquals(1, kills.size());
        assertEquals(97, kills.get(0).damage);
    }

    @Test
    public void deathThenHitOrder_includesKillingBlow() {
        // RuneLite 1.13.0: ActorDeath arrives before the killing hitsplat in the same tick.
        hit(87);
        die();
        hit(10);
        List<KillTracker.Kill> kills = tracker.onGameTick();
        assertEquals(1, kills.size());
        assertEquals(97, kills.get(0).damage);

        when(npcUtil.isDying(npc)).thenReturn(true);
        despawn();
    }

    @Test
    public void oneHitKillWithDeathFirst_stillCredited() {
        die();
        hit(40);
        assertEquals(40, tracker.onGameTick().get(0).damage);
    }

    @Test
    public void hitDuringDeathAnimation_doesNotCreditTwice() {
        hit(97);
        die();
        assertEquals(1, tracker.onGameTick().size());

        // Next attack / cannon ball lands on the corpse a tick later, then it despawns "dying".
        hit(12);
        when(npcUtil.isDying(npc)).thenReturn(true);
        despawn();
        assertTrue(tracker.onGameTick().isEmpty());
    }

    @Test
    public void transformInPlace_secondFormCreditedAgain() {
        // Kalphite Queen style: phase 1 dies, then the same NPC refills and fights on (no despawn).
        hit(255);
        die();
        assertEquals(255, tracker.onGameTick().get(0).damage);

        when(npc.isDead()).thenReturn(false); // health bar refilled -> RuneLite clears isDead()
        hit(100);
        hit(155);
        die();
        List<KillTracker.Kill> kills = tracker.onGameTick();
        assertEquals(1, kills.size());
        assertEquals(255, kills.get(0).damage);
    }

    @Test
    public void deathWithoutPlayerDamage_isNotCredited() {
        die();
        assertTrue(tracker.onGameTick().isEmpty());
    }

    @Test
    public void finisherKill_stillCreditedOnDespawn() {
        hit(40);
        when(npcUtil.isDying(npc)).thenReturn(true);
        KillTracker.Kill kill = tracker.onNpcDespawned(new NpcDespawned(npc)).orElse(null);
        assertTrue(kill != null);
        assertEquals(40, kill.damage);
    }

    @Test
    public void deathAndDespawnInSameTick_creditedOnce() {
        hit(40);
        die();
        KillTracker.Kill kill = tracker.onNpcDespawned(new NpcDespawned(npc)).orElse(null);
        assertTrue(kill != null);
        assertEquals(40, kill.damage);
        assertTrue(tracker.onGameTick().isEmpty());
    }

    @Test
    public void reusedIndex_isTrackedAfterDespawn() {
        hit(97);
        die();
        tracker.onGameTick();
        tracker.onNpcDespawned(new NpcDespawned(npc));

        // A fresh NPC spawns into the same index and is killed normally.
        when(npc.isDead()).thenReturn(false);
        hit(50);
        die();
        List<KillTracker.Kill> kills = tracker.onGameTick();
        assertFalse(kills.isEmpty());
        assertEquals(50, kills.get(0).damage);
    }
}

package com.bestiary.service;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;
import com.bestiary.util.RarityRoller;
import net.runelite.api.NPC;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import java.util.Random;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CaptureServiceTest {

    @Mock private NPC npc;

    private static final long SEED = 42L;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        when(npc.getId()).thenReturn(1);
        when(npc.getName()).thenReturn("Cow");   // BEGINNER tier
        when(npc.getCombatLevel()).thenReturn(2);
    }

    // --- Catch rate formula ---

    @Test
    public void beginnerBaseRateAtLevel1Is25Percent() {
        CaptureService service = new CaptureService(new Random(SEED));
        assertEquals(0.25, service.calculateCatchRate(1, DifficultyTier.BEGINNER), 0.0001);
    }

    @Test
    public void bossBaseRateAtLevel1Is3Percent() {
        CaptureService service = new CaptureService(new Random(SEED));
        assertEquals(0.03, service.calculateCatchRate(1, DifficultyTier.BOSS), 0.0001);
    }

    @Test
    public void catchRateIncreasesWithLevel() {
        CaptureService service = new CaptureService(new Random(SEED));
        double level1  = service.calculateCatchRate(1, DifficultyTier.BEGINNER);
        double level50 = service.calculateCatchRate(50, DifficultyTier.BEGINNER);
        assertTrue("Rate at 50 should exceed rate at 1", level50 > level1);
    }

    @Test
    public void harderTiersHaveLowerRateAtSameLevel() {
        CaptureService service = new CaptureService(new Random(SEED));
        double beginner = service.calculateCatchRate(50, DifficultyTier.BEGINNER);
        double boss     = service.calculateCatchRate(50, DifficultyTier.BOSS);
        assertTrue("BEGINNER rate should exceed BOSS at same level", beginner > boss);
    }

    @Test
    public void beginnerCapsAt70PercentAtHighLevel() {
        CaptureService service = new CaptureService(new Random(SEED));
        assertEquals(0.70, service.calculateCatchRate(99, DifficultyTier.BEGINNER), 0.0001);
    }

    @Test
    public void bossCapsAt25PercentAtHighLevel() {
        CaptureService service = new CaptureService(new Random(SEED));
        assertEquals(0.25, service.calculateCatchRate(99, DifficultyTier.BOSS), 0.0001);
    }

    // --- A successful capture yields a fully-populated card ---

    @Test
    public void captureReturnsPopulatedCard() {
        CaptureService service = new CaptureService(new Random(SEED));

        // At a high Capture Level the catch rate is high; loop (deterministic RNG) until one lands.
        Optional<CapturedCreature> result = Optional.empty();
        for (int i = 0; i < 1000 && !result.isPresent(); i++) {
            result = service.attemptCapture(npc, null, 99, 5, "Lumbridge", "Player", 0, 0.0, 0.0, 0.0, null);
        }
        assertTrue(result.isPresent());

        CapturedCreature c = result.get();
        assertEquals(1, c.npcId);
        assertEquals("Cow", c.npcName);
        assertEquals(5, c.killsBeforeCapture);
        assertEquals("Lumbridge", c.regionName);
        assertNotNull(c.captureTime);
        assertNotNull(c.quality);
    }

    // --- Rarity distribution (base, level 1) ---

    @Test
    public void rarityDistributionAtLevel1MatchesBaseWeights() {
        Random rng = new Random(12345L);
        Map<CreatureRarity, Integer> counts = new EnumMap<>(CreatureRarity.class);
        for (CreatureRarity r : CreatureRarity.values()) counts.put(r, 0);

        int trials = 100_000;
        for (int i = 0; i < trials; i++) {
            counts.merge(RarityRoller.roll(rng, 1), 1, Integer::sum);
        }

        double commonPct   = counts.get(CreatureRarity.COMMON)   / (double) trials;
        double uncommonPct = counts.get(CreatureRarity.UNCOMMON) / (double) trials;
        double rarePct     = counts.get(CreatureRarity.RARE)     / (double) trials;
        double mythicPct   = counts.get(CreatureRarity.MYTHIC)   / (double) trials;

        assertEquals(0.750, commonPct,   0.015);
        assertEquals(0.170, uncommonPct, 0.010);
        assertEquals(0.060, rarePct,     0.005);
        assertTrue("Mythic should be very rare at level 1", mythicPct < 0.005);
    }

    @Test
    public void rarityDistributionAtLevel99HasMoreHighRarities() {
        Random rng = new Random(99999L);
        Map<CreatureRarity, Integer> lvl1  = rollCounts(rng, 1,  100_000);
        rng = new Random(99999L);
        Map<CreatureRarity, Integer> lvl99 = rollCounts(rng, 99, 100_000);
        int trials = 100_000;

        double mythicLvl1  = lvl1 .get(CreatureRarity.MYTHIC)   / (double) trials;
        double mythicLvl99 = lvl99.get(CreatureRarity.MYTHIC)   / (double) trials;
        double commonLvl1  = lvl1 .get(CreatureRarity.COMMON)   / (double) trials;
        double commonLvl99 = lvl99.get(CreatureRarity.COMMON)   / (double) trials;

        assertTrue("MYTHIC should be more likely at level 99 vs level 1", mythicLvl99 > mythicLvl1);
        assertTrue("COMMON should be less likely at level 99 vs level 1", commonLvl99 < commonLvl1);
    }

    private static Map<CreatureRarity, Integer> rollCounts(Random rng, int level, int trials) {
        Map<CreatureRarity, Integer> counts = new EnumMap<>(CreatureRarity.class);
        for (CreatureRarity r : CreatureRarity.values()) counts.put(r, 0);
        for (int i = 0; i < trials; i++) counts.merge(RarityRoller.roll(rng, level), 1, Integer::sum);
        return counts;
    }
}

package com.bestiary.service;

import com.google.gson.Gson;
import org.junit.Test;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Guards the per-account storage (#47): each accountHash gets its own isolated file, nothing is
 * written while logged out, and the pre-#47 global file is archived (never loaded) on first run.
 */
public class BestiaryStorePerAccountTest {

    @Test
    public void perAccountIsolationAndLegacyArchive() throws Exception {
        Path tmpHome = Files.createTempDirectory("bestiary-test-home");
        File runeliteDir = tmpHome.resolve(".runelite").toFile();
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        try {
            Path bestiaryDir = tmpHome.resolve(".runelite").resolve("bestiary");
            Files.createDirectories(bestiaryDir);
            // A legacy global collection that must be archived (not loaded) when the store starts.
            Files.write(bestiaryDir.resolve("bestiary.json"), "{\"version\":1,\"credits\":9999}".getBytes());

            BestiaryStore store = new BestiaryStore(new Gson(), executor, runeliteDir);

            // Legacy file moved aside to a dated archive; original gone.
            assertFalse("legacy global file must be archived",
                    Files.exists(bestiaryDir.resolve("bestiary.json")));
            try (Stream<Path> s = Files.list(bestiaryDir)) {
                assertTrue("a bestiary.legacy-* archive must exist",
                        s.anyMatch(p -> p.getFileName().toString().startsWith("bestiary.legacy-")));
            }

            // Logged out: load is empty and saves are dropped.
            assertFalse(store.hasActiveAccount());
            assertTrue(store.load().captures.isEmpty());
            BestiaryStore.StoreData dropped = new BestiaryStore.StoreData();
            dropped.credits = 500;
            store.saveNow(dropped);
            assertTrue("save while logged out must not create any account file",
                    !Files.exists(bestiaryDir.resolve("accounts")) ||
                    isEmptyDir(bestiaryDir.resolve("accounts")));

            // Account A saves and reloads its own data.
            store.setActiveAccount(111L, "AccountA");
            assertTrue(store.hasActiveAccount());
            BestiaryStore.StoreData a = new BestiaryStore.StoreData();
            a.credits = 111;
            store.saveNow(a);
            assertEquals(111L, store.load().credits);

            // Account B is a fresh, independent collection.
            store.setActiveAccount(222L, "AccountB");
            assertEquals("switching to a new account loads an empty collection", 0L, store.load().credits);
            BestiaryStore.StoreData b = new BestiaryStore.StoreData();
            b.credits = 222;
            store.saveNow(b);
            assertEquals(222L, store.load().credits);

            // Switching back to A still has A's data (never crossed into B).
            store.setActiveAccount(111L, "AccountA");
            assertEquals(111L, store.load().credits);

            // Registry recorded both accounts for the future switcher (#48).
            assertTrue(Files.exists(bestiaryDir.resolve("accounts").resolve("index.json")));

            store.close();
        } finally {
            executor.shutdownNow();
        }
    }

    private static boolean isEmptyDir(Path dir) throws Exception {
        try (Stream<Path> s = Files.list(dir)) {
            // Only the registry index (written on setActiveAccount) may exist — no <hash>.json yet.
            return s.noneMatch(p -> p.getFileName().toString().endsWith(".json")
                    && !p.getFileName().toString().equals("index.json"));
        }
    }
}

package com.bestiary.service;

import com.bestiary.model.CapturedCreature;
import com.google.gson.Gson;
import org.junit.Test;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * End-to-end guard for intra-profile card transfer (#50): a card moves out of the active account's
 * file into the target account's file, currentOwner follows while originalOwner is preserved, and
 * you can't send to yourself.
 */
public class CardTransferTest {

    @Test
    public void transferMovesCardBetweenAccountFiles() throws Exception {
        Path tmpHome = Files.createTempDirectory("bestiary-transfer-home");
        File runeliteDir = tmpHome.resolve(".runelite").toFile();
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        try {
            BestiaryStore store = new BestiaryStore(new Gson(), executor, runeliteDir);
            BestiaryDataService ds = new BestiaryDataService(new ProgressionService(), store);

            // Register the Alt account, then play as Main and catch two cards.
            ds.switchAccount(222L, "AltRSN");
            ds.switchAccount(111L, "MainRSN");
            CapturedCreature keep = CapturedCreature.builder().npcName("Goblin").playerName("MainRSN").build();
            CapturedCreature send = CapturedCreature.builder().npcName("Cow").playerName("MainRSN").build();
            ds.addCapture(keep);
            ds.addCapture(send);
            assertEquals(2, ds.getCollection().totalCaptures());
            assertEquals("both catches count toward lifetime", 2L, ds.getCollection().lifetimeCaptures);

            // Alt is the only other known account.
            List<BestiaryStore.AccountRef> others = ds.listOtherAccounts();
            assertEquals(1, others.size());
            assertEquals(222L, others.get(0).hash);

            // Send one card to Alt.
            int moved = ds.transferCards(Collections.singletonList(send), 222L, "AltRSN");
            assertEquals(1, moved);

            // Left Main's collection…
            assertEquals(1, ds.getCollection().totalCaptures());
            assertTrue(ds.getCollection().creatures.contains(keep));
            assertFalse(ds.getCollection().creatures.contains(send));
            // …but "Caught" (lifetime) is unchanged — sending a card away isn't un-catching it.
            assertEquals(2L, ds.getCollection().lifetimeCaptures);
            assertEquals(1L, ds.getCollection().lifetimeCardsSent);

            // …ownership moved but provenance kept…
            assertEquals("AltRSN",  send.currentOwner);
            assertEquals("MainRSN", send.originalOwner);

            // …and landed in Alt's file.
            BestiaryStore.StoreData alt = store.readAccount(222L);
            assertEquals(1, alt.captures.size());
            assertEquals("Cow",     alt.captures.get(0).npcName);
            assertEquals("AltRSN",  alt.captures.get(0).currentOwner);
            assertEquals("MainRSN", alt.captures.get(0).originalOwner);

            // Switching to Alt loads the received card — held, tagged traded-in, but NOT "caught".
            ds.switchAccount(222L, "AltRSN");
            assertEquals(1, ds.getCollection().totalCaptures());
            assertEquals("received cards don't count as caught", 0L, ds.getCollection().lifetimeCaptures);
            assertEquals(1L, ds.getCollection().tradedInCount());

            // Can't send to the account you're on.
            assertEquals(0, ds.transferCards(
                    ds.getCollection().creatures, 222L, "AltRSN"));

            store.close();
        } finally {
            executor.shutdownNow();
        }
    }
}

package com.bestiary.service;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DiscordWebhookServiceTest {

    @Test
    public void acceptsOfficialDiscordWebhookUrls() {
        assertTrue(DiscordWebhookService.looksLikeWebhook(
                "https://discord.com/api/webhooks/123/abc"));
        assertTrue(DiscordWebhookService.looksLikeWebhook(
                "https://discordapp.com/api/webhooks/123/abc"));
        assertTrue(DiscordWebhookService.looksLikeWebhook(
                "https://ptb.discord.com/api/webhooks/123/abc"));
        assertTrue("surrounding whitespace is trimmed",
                DiscordWebhookService.looksLikeWebhook("  https://discord.com/api/webhooks/1/x  "));
    }

    @Test
    public void rejectsNonDiscordOrMalformedUrls() {
        assertFalse("blank = disabled", DiscordWebhookService.looksLikeWebhook(""));
        assertFalse(DiscordWebhookService.looksLikeWebhook(null));
        assertFalse("http, not https", DiscordWebhookService.looksLikeWebhook(
                "http://discord.com/api/webhooks/1/x"));
        assertFalse("arbitrary host must not be a POST target",
                DiscordWebhookService.looksLikeWebhook("https://evil.com/api/webhooks/1/x"));
        assertFalse("lookalike host is not a Discord domain",
                DiscordWebhookService.looksLikeWebhook("https://discord.com.evil.com/api/webhooks/1/x"));
        assertFalse("right host, wrong path", DiscordWebhookService.looksLikeWebhook(
                "https://discord.com/api/oauth2/authorize"));
    }
}

