package com.bestiary.util;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests for the nickname profanity gate. Blocked cases use masked/leet inputs so the
 * test file stays clean; the pass cases make sure ordinary names aren't caught.
 */
public class ProfanityFilterTest {

    @Test
    public void blocksMaskedProfanity() {
        assertTrue(ProfanityFilter.isProfane("sh1t"));
        assertTrue(ProfanityFilter.isProfane("b!tch"));
        assertTrue(ProfanityFilter.isProfane("b0llocks"));
        assertTrue(ProfanityFilter.isProfane("xX b!tch Xx"));
    }

    @Test
    public void catchesLeetAndSymbols() {
        assertTrue(ProfanityFilter.isProfane("a$$"));
        assertTrue(ProfanityFilter.isProfane("@ss"));
    }

    @Test
    public void blocksStandaloneTokenButNotEmbedded() {
        assertTrue(ProfanityFilter.isProfane("my @ss hurts"));
        assertFalse(ProfanityFilter.isProfane("assassin"));
        assertFalse(ProfanityFilter.isProfane("raccoon"));
    }

    @Test
    public void allowsCleanNames() {
        assertFalse(ProfanityFilter.isProfane(null));
        assertFalse(ProfanityFilter.isProfane(""));
        assertFalse(ProfanityFilter.isProfane("  "));
        assertFalse(ProfanityFilter.isProfane("Fluffy"));
        assertFalse(ProfanityFilter.isProfane("Sir Reginald"));
        assertFalse(ProfanityFilter.isProfane("Nigeria"));
        assertFalse(ProfanityFilter.isProfane("Dickens"));
        assertFalse(ProfanityFilter.isProfane("grape"));
    }
}

package com.bestiary.util;

import com.bestiary.model.CreatureQuality;
import com.bestiary.model.CreatureRarity;
import org.junit.Test;

import java.util.Random;

import static org.junit.Assert.assertTrue;

/**
 * Locks in the core-identity rule: Agility (stat index 5), like Prayer, is a utility stat
 * rolled at HALF scale — not on the full combat-stat scale.
 */
public class RarityRollerTest {

    @Test
    public void utilityBandIsTighterThanCombatBand() {
        int[] combat  = RarityRoller.statBand(50, CreatureRarity.MYTHIC);
        int[] utility = RarityRoller.utilityBand(50, CreatureRarity.MYTHIC);
        assertTrue("utility hi should sit below combat hi", utility[1] < combat[1]);
        assertTrue("utility centre should sit below combat centre",
                RarityRoller.utilityCentre(50, CreatureRarity.MYTHIC)
                        < RarityRoller.statCentre(50, CreatureRarity.MYTHIC));
    }

    @Test
    public void agilityRollsOnUtilityScale() {
        int[] bases = {50, 50, 50, 50, 50, 50};
        int[] utility = RarityRoller.utilityBand(50, CreatureRarity.MYTHIC);
        int[] combat  = RarityRoller.statBand(50, CreatureRarity.MYTHIC);
        Random rng = new Random(42);
        for (int t = 0; t < 300; t++) {
            CreatureQuality q = RarityRoller.generateQuality(null, CreatureRarity.MYTHIC, bases, 50, rng, false);
            // Agility must land in the (lower) utility band...
            assertTrue("agility " + q.agility + " within utility band",
                    q.agility >= utility[0] && q.agility <= utility[1]);
            // ...while a full combat stat (attack) uses the higher combat band.
            assertTrue("attack " + q.attack + " within combat band",
                    q.attack >= combat[0] && q.attack <= combat[1]);
        }
    }
}

package com.bestiary.util;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Guards the Misthalin / Morytania / Desert boundary in the {@code approximateZone}
 * fallback. Region id = (rx &lt;&lt; 8) | ry, where rx = worldX/64 and ry = worldY/64.
 * The ids chosen here are deliberately NOT in the explicit name map, so they exercise
 * the zone heuristic (a real "Brutus" kill in eastern Misthalin used to read Morytania).
 */
public class RegionNamesTest {

    private static int regionId(int rx, int ry) {
        return (rx << 8) | ry;
    }

    @Test
    public void easternMisthalinIsNotMorytania() {
        // rx == 53 is eastern Misthalin, not Morytania (which starts at rx >= 54).
        assertEquals("Misthalin", RegionNames.get(regionId(53, 49)));
        assertEquals("Misthalin", RegionNames.get(regionId(53, 50)));
    }

    @Test
    public void realMorytaniaStillResolves() {
        // rx >= 54 east of the Salve is genuine Morytania.
        assertEquals("Morytania", RegionNames.get(regionId(56, 52)));
    }

    @Test
    public void gatewayLatitudeIsNotDesert() {
        // ry 48 at this longitude is the Al Kharid / eastern-Misthalin gateway, not desert
        // (13360 is unnamed, so it exercises the heuristic; the old rule read "Desert").
        assertEquals("Misthalin", RegionNames.get(regionId(52, 48)));
    }

    @Test
    public void desertProperStillResolves() {
        // The desert proper sits at ry <= 47.
        assertEquals("Desert", RegionNames.get(regionId(51, 45)));
    }
}

