package com.bestiary.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

/**
 * Immutable record of a single successful creature capture.
 * Stored permanently in the player's bestiary collection.
 */
public class CapturedCreature {

    /** Stable unique identifier for this capture record. */
    public final String id;

    /** RuneLite NPC definition ID. */
    public final int npcId;

    /** NPC display name at the time of capture. */
    public final String npcName;

    /** NPC combat level at capture (\u00e2\u02c6\u20191 for non-combat NPCs). */
    public final int npcCombatLevel;

    public final CreatureRarity rarity;
    public final CreatureQuality quality;

    /** UTC epoch second when the capture occurred. */
    public final Instant captureTime;

    /** Human-readable area name derived from the player's WorldPoint. Mutable so migrations can fix old "Region N" values. */
    public String regionName;

    /** The player's Capture Level at the moment this creature was caught. */
    public final int captureLevel;

    /** RuneScape username of the player who captured this creature (the "Captured by" label on cards). */
    public String playerName;

    /**
     * Account (RSN) that originally captured this card. Set once at capture and never changed — even
     * after the card is traded (#50), so provenance ("Originally caught by …") survives. Mutable only
     * so legacy saves can be back-filled from {@link #playerName} on load.
     */
    public String originalOwner;

    /**
     * Account (RSN) that currently owns this card. Equal to {@link #originalOwner} until the card is
     * transferred to another of the player's accounts (#50), which updates this to the new holder.
     */
    public String currentOwner;

    /** Optional user-assigned nickname for this individual capture. Null = not set. */
    public String nickname;

    /** Player has starred this capture as a favourite. Persisted to disk. */
    public boolean favourite;

    /** True when this capture won the independent shiny roll at capture time. Persisted. */
    public final boolean shiny;

    /** Damage the player dealt to this kill ("observed HP"). 0 = unknown → use placeholder. Persisted. */
    public final int observedHp;

    /**
     * The passive shiny-chance bonus (from the Shiny Charm shop upgrade) that was in effect when
     * this card's shiny was rolled — at capture, or at the most recent reroll. 0 for legacy/seed
     * cards and captures made with no charm. Persisted so the Odds view can show the shiny odds
     * that actually applied at the time, not the current bonus.
     */
    public final double shinyBonus;

    /** Player who last rerolled this card (empty = never rerolled — a raw pull). Persisted. */
    public final String rerolledBy;

    /**
     * Chronological log of this card's prior states — one entry per reroll, each capturing what
     * the card looked like BEFORE that reroll and who performed it. Empty = a raw pull. Persisted.
     * Drives "Rerolled N times", the unique-reroller count, and (future #77) a per-card Data panel.
     */
    public final List<RerollState> rerollHistory;

    /** An immutable snapshot of the card's state just before one reroll replaced it. */
    public static final class RerollState {
        public final CreatureRarity rarity;
        /** The 7 rolled stats (incl. Prayer) at this point. May be null for pre-tracking entries. */
        public final CreatureQuality quality;
        public final int powerLevel;
        public final boolean shiny;
        /** Player who performed the reroll that superseded this state. */
        public final String rerolledBy;
        /** UTC epoch second the reroll happened. */
        public final long epoch;

        public RerollState(CreatureRarity rarity, CreatureQuality quality, int powerLevel, boolean shiny,
                           String rerolledBy, long epoch) {
            this.rarity     = rarity;
            this.quality    = quality;
            this.powerLevel = powerLevel;
            this.shiny      = shiny;
            this.rerolledBy = rerolledBy != null ? rerolledBy : "";
            this.epoch      = epoch;
        }
    }

    /** Player has chosen this capture as the album catalog cover for its monster. Persisted; one per npcName. */
    public boolean albumCover;

    /**
     * Credits actually awarded for this capture at the moment it was caught (base reward + the
     * Hunter's Bounty tier owned then). Persisted so the Card Info shows the true historical value,
     * unaffected by later rerolls or shop purchases. 0 for legacy captures made before this was tracked.
     * Carried forward across rerolls (a reroll doesn't re-award capture credits).
     */
    public long creditsEarned;

    /**
     * Capture XP actually awarded at capture (base capture XP + the Scholar's Insight % boost owned
     * then). Persisted for accurate as-at-capture Card Info; 0 for legacy captures or if capture XP
     * was disabled. Carried across rerolls (a reroll doesn't re-award capture XP).
     */
    public long xpEarned;

    /**
     * How many kills of this species the player had accumulated before this
     * capture succeeded (useful for showing "lucky" catches).
     */
    public final int killsBeforeCapture;

    /**
     * Transient (NEVER persisted): true when Fortune's Favour bumped this capture up one rarity.
     * Set at capture only, to drive the one-off "Fortune's Favour shines" chat proc — it carries no
     * lasting meaning, so it is intentionally excluded from the builder and the on-disk codec.
     */
    public transient boolean fortuneBumped;

    /**
     * Transient (NEVER persisted): the rarity this capture rolled BEFORE Fortune's Favour bumped it,
     * so the proc line can show the before→after climb ("from Epic to Legendary"). Null unless
     * {@link #fortuneBumped} is true.
     */
    public transient CreatureRarity fortuneFrom;

    /**
     * Transient (NEVER persisted): when Keen Instinct rolled the rarity twice and kept the better,
     * these hold the kept (winning) and rejected (losing) rarities. Both null unless the double-roll
     * actually improved the result. Drives the one-off "keen instinct" chat proc only.
     */
    public transient CreatureRarity keenInstinctKept;
    public transient CreatureRarity keenInstinctFrom;

    private CapturedCreature(Builder b) {
        this.id                = b.id;
        this.npcId             = b.npcId;
        this.npcName           = b.npcName;
        this.npcCombatLevel    = b.npcCombatLevel;
        this.rarity            = b.rarity;
        this.quality           = b.quality;
        this.captureTime       = b.captureTime;
        this.regionName        = b.regionName;
        this.captureLevel      = b.captureLevel;
        this.killsBeforeCapture = b.killsBeforeCapture;
        this.playerName        = b.playerName != null ? b.playerName : "";
        // Owners default to the capturer unless explicitly set (e.g. carried across a reroll).
        this.originalOwner     = firstNonEmpty(b.originalOwner, this.playerName);
        this.currentOwner      = firstNonEmpty(b.currentOwner, this.playerName);
        this.shiny             = b.shiny;
        this.observedHp        = b.observedHp;
        this.shinyBonus        = b.shinyBonus;
        this.rerolledBy        = b.rerolledBy != null ? b.rerolledBy : "";
        this.rerollHistory     = b.rerollHistory != null
                ? Collections.unmodifiableList(new ArrayList<>(b.rerollHistory))
                : Collections.emptyList();
    }

    private static String firstNonEmpty(String a, String b) {
        return a != null && !a.isEmpty() ? a : (b != null ? b : "");
    }

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private String id = UUID.randomUUID().toString();
        private int npcId;
        private String npcName = "Unknown";
        private int npcCombatLevel = -1;
        private CreatureRarity rarity = CreatureRarity.COMMON;
        private CreatureQuality quality;
        private Instant captureTime = Instant.now();
        private String regionName = "Unknown";
        private int captureLevel = 1;
        private int killsBeforeCapture = 0;
        private String playerName = "";
        private String originalOwner = "";
        private String currentOwner = "";
        private boolean shiny = false;
        private int observedHp = 0;
        private double shinyBonus = 0.0;
        private String rerolledBy = "";
        private List<RerollState> rerollHistory = null;

        public Builder id(String v)              { this.id = v; return this; }
        public Builder npcId(int v)             { this.npcId = v; return this; }
        public Builder npcName(String v)         { this.npcName = v; return this; }
        public Builder npcCombatLevel(int v)     { this.npcCombatLevel = v; return this; }
        public Builder rarity(CreatureRarity v)  { this.rarity = v; return this; }
        public Builder quality(CreatureQuality v){ this.quality = v; return this; }
        public Builder captureTime(Instant v)    { this.captureTime = v; return this; }
        public Builder regionName(String v)      { this.regionName = v; return this; }
        public Builder captureLevel(int v)       { this.captureLevel = v; return this; }
        public Builder killsBeforeCapture(int v) { this.killsBeforeCapture = v; return this; }
        public Builder playerName(String v)       { this.playerName = v; return this; }
        public Builder originalOwner(String v)     { this.originalOwner = v; return this; }
        public Builder currentOwner(String v)      { this.currentOwner = v; return this; }
        public Builder shiny(boolean v)           { this.shiny = v; return this; }
        public Builder observedHp(int v)          { this.observedHp = v; return this; }
        public Builder shinyBonus(double v)       { this.shinyBonus = v; return this; }
        public Builder rerolledBy(String v)       { this.rerolledBy = v; return this; }
        public Builder rerollHistory(List<RerollState> v) { this.rerollHistory = v; return this; }

        public CapturedCreature build() {
            if (quality == null) {
                quality = new CreatureQuality(50, 50, 50, 50, 50, 50, 10);
            }
            return new CapturedCreature(this);
        }
    }

    /** True when this capture won the independent shiny roll at capture time. */
    public boolean isShiny() {
        return shiny;
    }

    /**
     * Transfers this card to another of the player's accounts (#50): updates {@link #currentOwner}
     * while leaving {@link #originalOwner} untouched, preserving provenance. No-op for a blank name.
     */
    public void transferTo(String newOwner) {
        if (newOwner != null && !newOwner.isEmpty()) {
            this.currentOwner = newOwner;
        }
    }

    /** How many times this card has been rerolled (0 = a raw pull). */
    public int rerollCount() {
        return rerollHistory.size();
    }

    /** The distinct set of players who have ever rerolled this card, in first-seen order. */
    public Set<String> uniqueRerollers() {
        Set<String> names = new LinkedHashSet<>();
        for (RerollState s : rerollHistory) {
            if (s.rerolledBy != null && !s.rerolledBy.isEmpty()) names.add(s.rerolledBy);
        }
        return names;
    }

    /**
     * The HP used for this card: the damage the player actually dealt to the kill
     * ("observed HP") when known, else the monster's placeholder wiki HP. For solo
     * kills of normal monsters these are ~equal; for scaled/group content observed
     * reflects the player's own contribution.
     */
    public int hitpoints() {
        return observedHp > 0 ? observedHp : MonsterRoster.getHitpoints(npcName);
    }

    /**
     * "Power Level" — the headline card metric. The average of the 7 rolled stats (6 combat +
     * Prayer, all on the 1-99 scale) PLUS two factual difficulty terms, each at 1/6 weight: the
     * monster's HP and its combat level. Splitting the terms keeps the stat average at face value
     * (~its rolled quality) while the two objective attributes separate the tiers: HP/6 adds ~13
     * at 80 HP, ~40 at 250 HP, ~165 at 1000 HP; combat level/6 adds a comparable lift (~21 at cmb
     * 124, ~233 at cmb 1400). Combat level is the killed NPC's own level (stored per capture), so
     * same-name variants keep their individual value. Power Level can exceed 99 for bosses;
     * stats/prayer are flavour.
     */
    public int powerLevel() {
        return Math.round(quality.statSum() / 7f
                + hitpoints() / 6f
                + Math.max(0, npcCombatLevel) / 6f);
    }

    @Override
    public String toString() {
        return String.format("[%s] %s (ID %d) - %s @ %s",
                rarity.label, npcName, npcId, captureTime, regionName);
    }
}

package com.bestiary.model;

import java.awt.Color;

public enum CreatureRarity {

    COMMON    (0.750, new Color(180, 180, 180), 1.0,  "Common"),
    UNCOMMON  (0.170, new Color(80,  200, 80),  2.0,  "Uncommon"),
    RARE      (0.060, new Color(80,  140, 255),  5.0,  "Rare"),
    EPIC      (0.015, new Color(190, 80,  220),  10.0, "Epic"),
    LEGENDARY (0.004, new Color(255, 165, 0),    25.0, "Legendary"),
    MYTHIC    (0.001, new Color(255, 50,  50),   50.0, "Mythic");

    /** Weight used by RarityRoller; values sum to 1.0. */
    public final double probability;

    /** Colour used by the UI to tint creature cards. */
    public final Color displayColor;

    /** Multiplier applied on top of the base capture XP award. */
    public final double xpMultiplier;

    /** Human-readable label. */
    public final String label;

    CreatureRarity(double probability, Color displayColor, double xpMultiplier, String label) {
        this.probability  = probability;
        this.displayColor = displayColor;
        this.xpMultiplier = xpMultiplier;
        this.label        = label;
    }

    /** Returns the first rarity whose display label matches (case-insensitive). */
    public static CreatureRarity fromLabel(String label) {
        for (CreatureRarity r : values()) {
            if (r.label.equalsIgnoreCase(label)) return r;
        }
        return COMMON;
    }
}

package com.bestiary.model;

/**
 * Seven randomised stats for a captured creature, each in [1, 99].
 * Indices: 0=ATK  1=STR  2=DEF  3=MAG  4=RNG  5=AGI  6=PRAYER
 * Agility and Prayer are "utility" stats rolled at half scale; the other five are full-scale
 * combat stats. Generated once at capture time; never changes for a given capture record.
 */
public class CreatureQuality {

    public final int attack;
    public final int strength;
    public final int defence;
    public final int magic;
    public final int ranged;
    public final int agility;
    public final int prayer;

    public CreatureQuality(int attack, int strength, int defence,
                           int magic, int ranged, int agility, int prayer) {
        this.attack   = clamp(attack);
        this.strength = clamp(strength);
        this.defence  = clamp(defence);
        this.magic    = clamp(magic);
        this.ranged   = clamp(ranged);
        this.agility  = clamp(agility);
        this.prayer   = clamp(prayer);
    }

    /** Sum of all seven rolled stats (six combat + Prayer). */
    public int statSum() {
        return attack + strength + defence + magic + ranged + agility + prayer;
    }

    /** Average of all seven stats, rounded to the nearest integer (pure stat flavour). */
    public int overallRating() {
        return Math.round(statSum() / 7f);
    }

    private static int clamp(int v) {
        return Math.max(1, Math.min(99, v));
    }

    @Override
    public String toString() {
        return String.format("ATK:%d STR:%d DEF:%d MAG:%d RNG:%d AGI:%d PRAY:%d",
                attack, strength, defence, magic, ranged, agility, prayer);
    }
}

package com.bestiary.model;

/**
 * Combat class for a monster. Determines primary (high), secondary (mid), and
 * tertiary (dump) stats across the 6 indices: 0=ATK 1=STR 2=DEF 3=MAG 4=RNG 5=AGI.
 * Any index not listed as primary or tertiary is implicitly secondary.
 * APEX has 3 primaries and only 1 tertiary (AGI), making it the most dominant class.
 */
public enum CombatClass {
    NIMBLE   ("Nimble",   new int[]{1, 5},    new int[]{2, 3}),   // P: STR AGI  | T: DEF MAG
    BRUTE    ("Brute",    new int[]{0, 1},    new int[]{3, 4}),   // P: ATK STR  | T: MAG RNG
    TANK     ("Tank",     new int[]{1, 2},    new int[]{4, 5}),   // P: STR DEF  | T: RNG AGI
    PREDATOR ("Predator", new int[]{0, 5},    new int[]{2, 3}),   // P: ATK AGI  | T: DEF MAG
    MYSTIC   ("Mystic",   new int[]{2, 3},    new int[]{0, 1}),   // P: DEF MAG  | T: ATK STR
    STALKER  ("Stalker",  new int[]{3, 4},    new int[]{0, 2}),   // P: MAG RNG  | T: ATK DEF
    RANGER   ("Ranger",   new int[]{4, 5},    new int[]{1, 3}),   // P: RNG AGI  | T: STR MAG
    TITAN    ("Titan",    new int[]{1, 3},    new int[]{4, 5}),   // P: STR MAG  | T: RNG AGI
    APEX     ("Apex",     new int[]{0, 1, 3, 4}, new int[]{}),    // tribrid: ATK STR MAG RNG (DEF/AGI secondary)
    JUGGERNAUT("Juggernaut", new int[]{0, 1, 2}, new int[]{3, 4}),// P: ATK STR DEF | T: MAG RNG
    ARCHON   ("Archon",   new int[]{2, 3, 4},  new int[]{1}),     // P: DEF MAG RNG | T: STR (legacy)

    // ---- Attack-style x weight taxonomy (#70). AGI is never primary/tertiary here:
    // it is the flavour stat shown in the attribute band, driven by its own base. ----
    WARRIOR  ("Warrior",   new int[]{0, 1},    new int[]{3, 4}),  // melee            | dump MAG RNG
    MAGE     ("Mage",      new int[]{3},       new int[]{0, 1, 4}),// magic           | dump ATK STR RNG
    MARKSMAN ("Marksman",  new int[]{4},       new int[]{0, 1, 3}),// ranged          | dump ATK STR MAG
    BATTLEMAGE("Battlemage", new int[]{0, 1, 3}, new int[]{4}),   // melee+magic      | dump RNG
    WARDEN   ("Warden",    new int[]{0, 1, 4}, new int[]{3}),     // melee+ranged     | dump MAG
    OCCULTIST("Occultist", new int[]{3, 4},    new int[]{0, 1}),  // magic+ranged     | dump ATK STR

    // ---- Profile-derived flavour classes (assigned programmatically, not by attack style):
    // MEATSHIELD = passive/tanky (low damage, often high HP) e.g. cows, crabs.
    // NIMBLE     = fast + fragile (very low HP, high agility) e.g. rats, chickens, spiders. ----
    MEATSHIELD("Meatshield", new int[]{2}, new int[]{3, 4});      // defensive lump    | dump MAG RNG

    public final String label;
    public final int[]  primaryIndices;
    public final int[]  tertiaryIndices;

    CombatClass(String label, int[] primaryIndices, int[] tertiaryIndices) {
        this.label            = label;
        this.primaryIndices   = primaryIndices;
        this.tertiaryIndices  = tertiaryIndices;
    }

    public boolean isPrimary(int statIndex) {
        for (int i : primaryIndices)   { if (i == statIndex) return true; }
        return false;
    }

    public boolean isTertiary(int statIndex) {
        for (int i : tertiaryIndices)  { if (i == statIndex) return true; }
        return false;
    }
}

