    /** Captured (unlocked) card. */
    public AlbumCard(int dexNumber, String npcName, List<CapturedCreature> captures,
                     BestiaryCollection collection, @Nullable WikiImageService imageService) {
        this.dexNumber    = dexNumber;
        this.npcName      = npcName;
        this.captures     = captures;
        this.collection   = collection;
        this.imageService = imageService;
        this.locked       = false;
        this.discovered   = false;
        this.killCount    = 0;

        // Card appearance is driven by the player-chosen album cover if one is set;
        // otherwise the "best" capture (highest rarity, then highest overall quality).
        CapturedCreature cover = captures.stream().filter(c -> c.albumCover).findFirst().orElse(null);
        CapturedCreature best = cover != null ? cover : captures.stream()
                .max(Comparator.comparingInt((CapturedCreature c) -> c.rarity.ordinal())
                        .thenComparingInt(c -> c.powerLevel()))
                .orElse(captures.get(0));
        this.combatLevel = best.npcCombatLevel;

        this.rarest = best.rarity;

        // Rarity dots show every rarity the player has unlocked across all captures
        CreatureRarity[] order = {
            CreatureRarity.MYTHIC, CreatureRarity.LEGENDARY, CreatureRarity.EPIC,
            CreatureRarity.RARE,   CreatureRarity.UNCOMMON,  CreatureRarity.COMMON
        };
        List<CreatureRarity> dots = new ArrayList<>();
        for (CreatureRarity r : order) {
            if (captures.stream().anyMatch(c -> c.rarity == r)) { dots.add(r); if (dots.size() == 3) break; }
        }
        this.rarityDots = dots;

        // Stats displayed are the best capture's individual stats, not an average
        this.avgStats = new int[]{
            best.quality.attack,
            best.quality.strength,
            best.quality.defence,
            best.quality.magic,
            best.quality.ranged,
            best.quality.agility,
        };

        this.difficulty     = MonsterRoster.getDifficulty(npcName, combatLevel);
        this.combatClass    = MonsterRoster.getCombatClass(npcName, combatLevel);
        this.species        = MonsterRoster.getSpecies(npcName, combatLevel);
        // Shiny styling must come from the SAME capture that drives the card's rarity/look
        // (the cover, or the "best" capture) — not any shiny capture. Otherwise a lower-rarity
        // shiny would make a higher-rarity non-shiny cover render as shiny (#66).
        this.hasShiny       = best.isShiny();
        this.overallQuality = best.powerLevel();
        this.prayerValue    = best.quality.prayer;
        // Show the SAME HP the power level was computed from (observed damage preferred),
        // so the heart pill matches the capture popup and the P: value — not the wiki default.
        this.hitpoints      = best.hitpoints();
        // Hover metadata (#44) — overlay only, never part of the exported PNG.
        setToolTipText(hoverTip(best));
        init(imageService, true);
    }

    /**
     * Uncaptured card. {@code discovered} = the monster has been killed (unlocked): the card is
     * clickable and shows the wiki image / placeholder. {@code !discovered} = never killed
     * (locked): shows a padlock and is not clickable.
     */
    public AlbumCard(int dexNumber, String npcName, int killCount, boolean discovered,
                     @Nullable WikiImageService imageService) {
        this.dexNumber    = dexNumber;
        this.npcName      = npcName;
        this.captures     = null;
        this.collection   = null;
        this.imageService = imageService;
        this.locked       = true;
        this.discovered   = discovered;
        this.killCount    = killCount;
        this.combatLevel  = 0;
        this.rarest       = null;
        this.rarityDots   = null;
        this.avgStats     = new int[6];

        this.difficulty     = MonsterRoster.getDifficulty(npcName, 0);
        this.combatClass    = MonsterRoster.getCombatClass(npcName, 0);
        this.species        = MonsterRoster.getSpecies(npcName, 0);
        this.hasShiny       = false;
        this.overallQuality = 0;
        this.prayerValue    = MonsterRoster.getPrayer(npcName);
        this.hitpoints      = MonsterRoster.getHitpoints(npcName);
        // Only fetch art for discovered (unlocked) cards — locked slots show a padlock, never the creature.
        init(imageService, discovered && imageService != null);
    }

    private static final java.time.format.DateTimeFormatter TIP_DATE =
            java.time.format.DateTimeFormatter.ofPattern("d MMM yyyy").withZone(java.time.ZoneId.systemDefault());

    /** HTML hover tooltip (#44): capture date, region, kills-before. Overlay only — not exported. */
    private static String hoverTip(CapturedCreature c) {
        String rarityHex = String.format("#%06x", c.rarity.displayColor.getRGB() & 0xFFFFFF);
        String region = c.regionName != null && !c.regionName.isEmpty() ? c.regionName : "Unknown";
        StringBuilder sb = new StringBuilder("<html><b>").append(c.npcName)
                .append("</b> · <font color='").append(rarityHex).append("'>").append(c.rarity.label)
                .append("</font>").append(c.isShiny() ? " ✦" : "")
                .append("<br>Caught: ").append(TIP_DATE.format(c.captureTime))
                .append("<br>Region: ").append(region)
                .append("<br>Kills before catch: ").append(c.killsBeforeCapture);
        if (c.rerollCount() > 0) sb.append("<br>Rerolled ").append(c.rerollCount()).append("×");
        sb.append("<br><i>Left-click or right-click → Card info + export</i></html>");
        return sb.toString();
    }

    private void init(@Nullable WikiImageService imgService, boolean fetchImage) {
        setOpaque(false);
        setPreferredSize(new Dimension(CARD_W, CARD_H));
        setMinimumSize(new Dimension(CARD_W, CARD_H));
        setMaximumSize(new Dimension(CARD_W, CARD_H));
        if (!locked || discovered) setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        if (fetchImage && imgService != null) {
            imgService.requestImage(npcName, this::repaint);
        }

        if (!locked && ((rarest != null && rarest.ordinal() >= CreatureRarity.EPIC.ordinal()) || hasShiny)) {
            shimmerTimer = new javax.swing.Timer(30, e -> {
                shimmerPhase += 0.022f;
                if (shimmerPhase > 1.05f) {
                    shimmerTimer.stop(); shimmerPhase = 0f;
                    if (hovered) {
                        javax.swing.Timer repeat = new javax.swing.Timer(500, ev -> {
                            if (hovered) { shimmerPhase = 0f; shimmerTimer.restart(); }
                        });
                        repeat.setRepeats(false); repeat.start();
                    }
                }
                repaint();
                if (shimmerCallback != null) shimmerCallback.run();
            });
            shimmerTimer.setRepeats(true);
            SHIMMER_CARDS.add(this);
            if (GLOBAL_SHIMMER_TIMER == null) {
                GLOBAL_SHIMMER_TIMER = new javax.swing.Timer(10_000, e -> {
                    if (sharedConfig != null && !sharedConfig.autoShimmer()) return;
                    for (AlbumCard c : new java.util.ArrayList<>(SHIMMER_CARDS)) {
                        if (!c.getVisibleRect().isEmpty()) { c.shimmerPhase = 0f; c.shimmerTimer.restart(); }
                    }
                });
                GLOBAL_SHIMMER_TIMER.setRepeats(true);
                GLOBAL_SHIMMER_TIMER.start();
            }
        }

        addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) {
                hovered = true;
                if (shimmerTimer != null) { shimmerPhase = 0f; shimmerTimer.restart(); }
                repaint();
            }
            @Override public void mouseExited(MouseEvent e) {
                hovered = false;
                if (shimmerTimer != null) shimmerTimer.stop();
                repaint();
            }

            // macOS delivers the popup trigger on press, Windows/Linux on release — handle both.
            @Override public void mousePressed(MouseEvent e)  { maybeShowMenu(e); }
            @Override public void mouseReleased(MouseEvent e) { maybeShowMenu(e); }

            private void maybeShowMenu(MouseEvent e) {
                if (e.isPopupTrigger() && !locked && captures != null) {
                    showExportMenu(e);   // read-only view shows only Copy + Card info/export (#48)
                }
            }

            @Override
            public void mouseClicked(MouseEvent e) {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                if (clickOverride != null) {
                    clickOverride.run();
                    return;
                }
                if (!locked && captures != null && collection != null) {
                    List<CapturedCreature> forDialog = (detailCaptures != null && !detailCaptures.isEmpty())
                            ? detailCaptures : captures;
                    new CreatureDetailDialog(
                            SwingUtilities.getWindowAncestor(AlbumCard.this), forDialog, collection, "By Rarity", rarest);
                }
            }

            private void showExportMenu(MouseEvent e) {
                // Viewing another account is look-only: only Copy + Card info/export are offered;
                // favourite/album-cover/nickname/reroll/discard are hidden (#48).
                boolean readOnly = BestiaryPanel.isReadOnly();
                JPopupMenu menu = new JPopupMenu();
                if (copyCallback != null) {
                    JMenuItem copyItem = new JMenuItem("Copy Card");
                    copyItem.addActionListener(ev -> copyCallback.run());
                    menu.add(copyItem);
                    menu.addSeparator();
                }
                if (!readOnly && favToggleCallback != null) {
                    boolean isFav = favStateSupplier != null && Boolean.TRUE.equals(favStateSupplier.get());
                    JMenuItem favItem = new JMenuItem(isFav ? "✩ Remove Favourite" : "★ Favourite");
                    favItem.addActionListener(ev -> favToggleCallback.run());
                    menu.add(favItem);
                    if (albumCoverToggleCallback != null) {
                        boolean isCover = albumCoverStateSupplier != null
                                && Boolean.TRUE.equals(albumCoverStateSupplier.get());
                        JMenuItem coverItem = new JMenuItem(isCover ? "Remove album cover" : "Set as album cover");
                        coverItem.addActionListener(ev -> albumCoverToggleCallback.run());
                        menu.add(coverItem);
                    }
                    menu.addSeparator();
                } else if (!readOnly && unfavouriteCallback != null) {
                    JMenuItem unfavItem = new JMenuItem("✩ Remove Favourite");
                    unfavItem.addActionListener(ev -> unfavouriteCallback.run());
                    menu.add(unfavItem);
                    menu.addSeparator();
                }
                List<CapturedCreature> sorted = new ArrayList<>(captures);
                sorted.sort(java.util.Comparator.<CapturedCreature>
                        comparingInt(c -> c.rarity.ordinal())
                        .reversed()
                        .thenComparingInt(c -> -c.powerLevel()));

                if (sorted.size() == 1) {
                    CapturedCreature only = sorted.get(0);
                    JMenuItem dataItem = new JMenuItem("Card info + export");
                    dataItem.addActionListener(ev ->
                            CardDataDialog.open(SwingUtilities.getWindowAncestor(AlbumCard.this),
                                    only, CardDataDialog.TAB_EXPORT));
                    menu.add(dataItem);
                } else {
                    JMenu oddsSub = new JMenu("Card info + export");
                    int shown = Math.min(sorted.size(), 8);
                    for (int i = 0; i < shown; i++) {
                        CapturedCreature c = sorted.get(i);
                        String label = (c.nickname != null && !c.nickname.isEmpty())
                                ? "\"" + c.nickname + "\"  PWR:" + c.powerLevel()
                                : c.rarity.label + "  PWR:" + c.powerLevel();
                        JMenuItem oItem = new JMenuItem(label);
                        oItem.setForeground(c.rarity.displayColor);
                        oItem.addActionListener(ev ->
                                CardDataDialog.open(SwingUtilities.getWindowAncestor(AlbumCard.this),
                                        c, CardDataDialog.TAB_EXPORT));
                        oddsSub.add(oItem);
                    }
                    menu.add(oddsSub);
                }
                if (!readOnly && !locked && captures != null && captures.size() == 1) {
                    CapturedCreature nickCap = captures.get(0);
                    String nickLabel = (nickCap.nickname != null && !nickCap.nickname.isEmpty()) ? "Rename…" : "Name capture…";
                    JMenuItem nickItem = new JMenuItem(nickLabel);
                    nickItem.addActionListener(ev -> openNicknameDialog(AlbumCard.this, nickCap, () -> {
                        repaint();
                        if (nicknameCallback != null) nicknameCallback.run();
                    }));
                    menu.add(nickItem);
                }
                if (!readOnly && !locked && captures != null && captures.size() == 1
                        && (discardHandler != null || rerollHandler != null)) {
                    menu.addSeparator();
                    if (rerollHandler != null) {
                        JMenuItem rerollItem = new JMenuItem("Reroll (shop)…");
                        rerollItem.setForeground(new Color(120, 200, 120));
                        rerollItem.addActionListener(ev -> rerollHandler.accept(AlbumCard.this, captures.get(0)));
                        menu.add(rerollItem);
                    }
                    if (discardHandler != null) {
                        JMenuItem discardItem = new JMenuItem("Discard…");
                        discardItem.setForeground(new Color(224, 112, 112));
                        discardItem.addActionListener(ev -> discardHandler.accept(AlbumCard.this, captures.get(0)));
                        menu.add(discardItem);
                    }
                }
                menu.show(AlbumCard.this, e.getX(), e.getY());
            }
        });
    }

    /**
     * Opens the shared MODELESS "Name capture" editor for a capture, anchored to
     * {@code anchor}. Runs {@code onSaved} after the nickname is committed so callers
     * can repaint / persist. Static so both AlbumCard and CardExportDialog use one editor.
     */
    static void openNicknameDialog(Component anchor, CapturedCreature c, Runnable onSaved) {
        JTextField field = new JTextField(c.nickname != null ? c.nickname : "", 20);
        JLabel counter = new JLabel(field.getText().length() + " / 20");
        counter.setFont(FontManager.getRunescapeSmallFont());
        counter.setForeground(Color.GRAY);
        ((javax.swing.text.AbstractDocument) field.getDocument()).setDocumentFilter(new javax.swing.text.DocumentFilter() {
            private void upd(FilterBypass fb) { counter.setText(fb.getDocument().getLength() + " / 20"); }
            @Override public void insertString(FilterBypass fb, int off, String s, javax.swing.text.AttributeSet a) throws javax.swing.text.BadLocationException {
                if (fb.getDocument().getLength() + (s == null ? 0 : s.length()) <= 20) { super.insertString(fb, off, s, a); upd(fb); }
            }
            @Override public void replace(FilterBypass fb, int off, int len, String s, javax.swing.text.AttributeSet a) throws javax.swing.text.BadLocationException {
                if (fb.getDocument().getLength() - len + (s == null ? 0 : s.length()) <= 20) { super.replace(fb, off, len, s, a); upd(fb); }
            }
            @Override public void remove(FilterBypass fb, int off, int len) throws javax.swing.text.BadLocationException { super.remove(fb, off, len); upd(fb); }
        });
        JPanel inputPanel = new JPanel(new BorderLayout(6, 4));
        inputPanel.add(new JLabel("Name (blank to clear):"), BorderLayout.NORTH);
        inputPanel.add(field, BorderLayout.CENTER);
        inputPanel.add(counter, BorderLayout.EAST);
        JButton okBtn = new JButton("OK");
        JButton cancelBtn = new JButton("Cancel");
        JPanel btnRow = new JPanel(new GridLayout(1, 2, 4, 0));
        btnRow.add(okBtn); btnRow.add(cancelBtn);
        JLabel warn = new JLabel(" ");
        warn.setFont(FontManager.getRunescapeSmallFont());
        warn.setForeground(new Color(0xE0, 0x40, 0x40));
        warn.setVisible(false);
        JPanel content = new JPanel(new BorderLayout(0, 8));
        content.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        content.add(inputPanel, BorderLayout.CENTER);
        content.add(warn, BorderLayout.NORTH);
        content.add(btnRow, BorderLayout.SOUTH);
        Window owner = SwingUtilities.getWindowAncestor(anchor);
        JDialog dlg = new JDialog(owner, "Name Capture", java.awt.Dialog.ModalityType.MODELESS);
        dlg.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dlg.setResizable(false);
        dlg.setContentPane(content);
        dlg.pack();
        dlg.setLocationRelativeTo(anchor);
        okBtn.addActionListener(ae -> {
            String val = field.getText().trim();
            if (com.bestiary.util.ProfanityFilter.isProfane(val)) {
                warn.setText("Let's keep it clean. Try another name");
                warn.setVisible(true);
                dlg.pack();
                return;
            }
            c.nickname = val.isBlank() ? null : val;
            if (onSaved != null) onSaved.run();
            BestiaryPanel.recheckAchievements();   // "Personal Touch" — name a card
            dlg.dispose();
        });
        cancelBtn.addActionListener(ae -> dlg.dispose());
        field.addActionListener(ae -> okBtn.doClick());
        dlg.setVisible(true);
    }

    /** Draws a padlock in the image area for locked (never-killed) slots — hides the creature. */
    private static void drawLockedPlaceholder(Graphics2D g2, int imgX, int imgW) {
        g2.setColor(new Color(38, 38, 38));
        g2.setStroke(new BasicStroke(1f));
        g2.drawRoundRect(imgX, IMAGE_Y, imgW, IMAGE_H, 6, 6);

        int cx = imgX + imgW / 2;
        int cy = IMAGE_Y + IMAGE_H / 2;
        int bodyW = 34, bodyH = 26;
        int bodyX = cx - bodyW / 2, bodyY = cy - 2;
        // Shackle
        g2.setColor(new Color(70, 70, 70));
        g2.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.drawArc(cx - 11, bodyY - 20, 22, 26, 0, 180);
        // Body
        g2.setColor(new Color(60, 60, 60));
        g2.fillRoundRect(bodyX, bodyY, bodyW, bodyH, 5, 5);
        g2.setColor(new Color(90, 90, 90));
        g2.drawRoundRect(bodyX, bodyY, bodyW, bodyH, 5, 5);
        // Keyhole
        g2.setColor(new Color(30, 30, 30));
        g2.fillOval(cx - 3, bodyY + 7, 6, 6);
        g2.fillRect(cx - 1, bodyY + 11, 3, 7);
    }

    @Override
    public void removeNotify() {
        super.removeNotify();
        if (shimmerTimer != null) shimmerTimer.stop();
        SHIMMER_CARDS.remove(this);
    }

    // -------------------------------------------------------------------------
    // Paint
    // -------------------------------------------------------------------------

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2 = makeG2(g);
        int w    = getWidth();
        int imgX = PAD;
        int imgW = w - PAD * 2;

        // Background + accent bar
        if (locked) {
            g2.setColor(hovered ? LOCKED_HOVER : LOCKED_BG);
            g2.fillRoundRect(0, 0, w, CARD_H, 8, 8);
            g2.setColor(LOCKED_ACCENT);
        } else {
            boolean shimmerLit = shimmerTimer != null && shimmerTimer.isRunning();
            g2.setColor((hovered || shimmerLit) ? HOVER_BG : NORMAL_BG);
            g2.fillRoundRect(0, 0, w, CARD_H, 8, 8);
            if (hasShiny) {
                // Golden wash so shiny cards read differently from normal ones
                g2.setPaint(new java.awt.GradientPaint(
                        0, 0, new Color(255, 224, 120, 60),
                        0, CARD_H, new Color(255, 196, 60, 16)));
                g2.fillRoundRect(0, 0, w, CARD_H, 8, 8);
            }
            g2.setColor(rarest.displayColor);
        }
        g2.fillRoundRect(0, 0, 4, CARD_H, 4, 4);

        Font smallFont = FontManager.getRunescapeSmallFont();
        Font boldFont  = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD);
        Font smallBold = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 14f);

        g2.setFont(smallFont);
        FontMetrics sfm = g2.getFontMetrics();

        // --- Header: left side (nickname or rarity dots) + right side ---
        // Catalog view: plain dex number. Single-capture (detail/favourites/export) view:
        // a colour-banded Power pill ("P:123") with the monster's factual HP beside it.
        FontMetrics dfm = sfm;
        g2.setFont(smallFont);
        int dexY = HEADER_Y + (HEADER_H + dfm.getAscent() - dfm.getDescent()) / 2;
        int dexX; // left edge of the right-side content (nickname/dots truncate against this)
        if (locked || !showQuality) {
            String dexStr = String.format("no. %03d", dexNumber);
            dexX = w - PAD - dfm.stringWidth(dexStr);
            g2.setColor(locked ? new Color(75, 75, 75) : rarest.displayColor);
            g2.drawString(dexStr, dexX, dexY);
        } else {
            // Power pill, right-aligned, coloured by power band
            String pText = "P:" + overallQuality;
            int pillPadX = 5, pillH2 = 15;
            int pillW = dfm.stringWidth(pText) + pillPadX * 2;
            int pillX = w - PAD - pillW;
            int pillY2 = HEADER_Y + (HEADER_H - pillH2) / 2;
            Color band = powerColor(overallQuality);
            g2.setColor(band);
            g2.fillRoundRect(pillX, pillY2, pillW, pillH2, 5, 5);
            g2.setColor(textOn(band));
            g2.drawString(pText, pillX + pillPadX,
                    pillY2 + (pillH2 + dfm.getAscent() - dfm.getDescent()) / 2);
            dexX = pillX;
        }
        if (hasShiny) {
            String star = "✦";
            g2.setColor(new Color(255, 215, 0));
            g2.drawString(star, dexX - dfm.stringWidth(star) - 3, dexY);
            dexX -= dfm.stringWidth(star) + 3;
        }

        // Left of header: nickname (single-capture card only) or rarity dots
        String headerNickname = (!locked && captures != null && captures.size() == 1
                && captures.get(0).nickname != null && !captures.get(0).nickname.isEmpty())
                ? captures.get(0).nickname : null;
        if (headerNickname != null) {
            int dotSize = 7, dotY = HEADER_Y + (HEADER_H - dotSize) / 2, dotX = PAD + 2;
            g2.setColor(rarest.displayColor);
            g2.fillOval(dotX, dotY, dotSize, dotSize);
            int nickStartX = dotX + dotSize + 4;
            Font nickFont = smallFont.deriveFont(Font.BOLD | Font.ITALIC, 11f);
            g2.setFont(nickFont);
            FontMetrics nfm = g2.getFontMetrics();
            int maxNickW = dexX - nickStartX - 4;
            String nick = truncate(headerNickname, nfm, maxNickW);
            g2.setColor(new Color(200, 155, 50));
            g2.drawString(nick, nickStartX, dexY);
            g2.setFont(smallFont);
        } else if (!locked && rarityDots != null) {
            int dotSize = 7, dotY = HEADER_Y + (HEADER_H - 7) / 2, dotX = PAD + 2;
            for (CreatureRarity r : rarityDots) {
                g2.setColor(r.displayColor);
                g2.fillOval(dotX, dotY, dotSize, dotSize);
                dotX += dotSize + 4;
            }
        }

        // --- Image area ---
        g2.setColor(IMAGE_BG);
        g2.fillRoundRect(imgX, IMAGE_Y, imgW, IMAGE_H, 6, 6);

        BufferedImage npcImage = imageService != null ? imageService.getImage(npcName) : null;
        if (npcImage != null) {
            // Scale-to-fit, centred
            double scale = Math.min((double) imgW / npcImage.getWidth(),
                                    (double) IMAGE_H / npcImage.getHeight());
            int dw = (int) (npcImage.getWidth()  * scale);
            int dh = (int) (npcImage.getHeight() * scale);
            int dx = imgX + (imgW - dw) / 2;
            int dy = IMAGE_Y + (IMAGE_H - dh) / 2;
            Shape clip = g2.getClip();
            g2.setClip(imgX, IMAGE_Y, imgW, IMAGE_H);
            g2.drawImage(npcImage, dx, dy, dw, dh, null);
            if (locked && !discovered) {
                // ~65% black overlay for the "greyed out" look (never-killed locked slots only)
                g2.setColor(new Color(0, 0, 0, 165));
                g2.fillRect(imgX, IMAGE_Y, imgW, IMAGE_H);
            }
            g2.setClip(clip);
        } else if (locked && !discovered) {
            // Never killed: a padlock placeholder (the creature stays hidden until you earn it).
            drawLockedPlaceholder(g2, imgX, imgW);
        } else {
            // Captured card placeholder while loading
            g2.setColor(new Color(45, 45, 45));
            g2.setStroke(new BasicStroke(1f));
            g2.drawRoundRect(imgX, IMAGE_Y, imgW, IMAGE_H, 6, 6);
            int cx = imgX + imgW / 2, cy = IMAGE_Y + IMAGE_H / 2 + 6;
            g2.setColor(new Color(50, 50, 50));
            g2.fillPolygon(new int[]{cx-24, cx-6,  cx-40}, new int[]{cy-10, cy+6, cy+6}, 3);
            g2.fillPolygon(new int[]{cx+10, cx+30, cx-10}, new int[]{cy-18, cy+6, cy+6}, 3);
            g2.setColor(new Color(60, 60, 60));
            g2.fillOval(cx - 34, IMAGE_Y + 10, 9, 9);
        }

        // --- Name row + difficulty badge ---
        g2.setFont(smallFont);
        sfm = g2.getFontMetrics();
        int nameBaseline = NAME_Y + (NAME_H + sfm.getAscent() - sfm.getDescent()) / 2;

        // Difficulty badge (right-aligned)
        g2.setFont(smallBold);
        FontMetrics sbfm = g2.getFontMetrics();
        String badgeText = difficulty.label;
        int badgePad = 5;
        int badgeW   = sbfm.stringWidth(badgeText) + badgePad * 2;
        int badgeH   = 16;
        int badgeX   = w - PAD - badgeW;
        int badgeY   = NAME_Y + (NAME_H - badgeH) / 2;

        Color badgeBg = locked
                ? new Color(difficulty.displayColor.getRed(), difficulty.displayColor.getGreen(),
                            difficulty.displayColor.getBlue(), 100)
                : new Color(difficulty.displayColor.getRed(), difficulty.displayColor.getGreen(),
                            difficulty.displayColor.getBlue(), 200);
        g2.setColor(badgeBg);
        g2.fillRoundRect(badgeX, badgeY, badgeW, badgeH, 4, 4);
        g2.setColor(locked ? new Color(120, 120, 120) : Color.WHITE);
        g2.drawString(badgeText, badgeX + badgePad,
                badgeY + (badgeH + sbfm.getAscent() - sbfm.getDescent()) / 2);

        // NPC name (truncated)
        g2.setFont(boldFont);
        FontMetrics bfm = g2.getFontMetrics();
        int maxNameW = badgeX - PAD - 4;
        g2.setColor(locked ? new Color(90, 90, 90) : Color.WHITE);
        g2.drawString(truncate(npcName, bfm, maxNameW), imgX + 2, nameBaseline);

        // --- Sub-name row: combat level (captured) or kill count (locked) ---
        g2.setFont(smallFont);
        g2.setFont(smallFont);
        sfm = g2.getFontMetrics();
        int subBaseline = COMBAT_Y + (COMBAT_H + sfm.getAscent() - sfm.getDescent()) / 2;

        int pillH = 12, pillPad = 4;
        int pillY = COMBAT_Y + (COMBAT_H - pillH) / 2;
        int pillBase = pillY + (pillH + sfm.getAscent() - sfm.getDescent()) / 2;

        if (!locked) {
            // Level pill — dark/black background, white text
            String lvlLabel = combatLevel > 0 ? "Lvl " + combatLevel : "Non-combat";
            int lvlW = sfm.stringWidth(lvlLabel) + pillPad * 2;
            int lvlX = imgX - 2;
            g2.setColor(new Color(12, 12, 12));
            g2.fillRoundRect(lvlX, pillY, lvlW, pillH, 4, 4);
            g2.setColor(Color.WHITE);
            g2.drawString(lvlLabel, lvlX + pillPad, pillBase);

            // Class + species pills share the row's remaining width. Pick the largest common
            // font (<= small) at which BOTH fit side by side, so a long class like JUGGERNAUT
            // stays legible instead of shrinking to a sliver while species keeps full size.
            int clsX  = lvlX + lvlW + 4;
            int gap   = 4;
            int avail = (w - PAD) - clsX;
            String clsLabel = combatClass.label;
            String spLabel  = species.label;
            float fs = smallFont.getSize2D();
            Font  pillFont = smallFont;
            FontMetrics pfm = sfm;
            while (fs > 8f
                    && pfm.stringWidth(clsLabel) + pfm.stringWidth(spLabel) + pillPad * 4 + gap > avail) {
                fs -= 0.5f;
                pillFont = smallFont.deriveFont(fs);
                pfm = g2.getFontMetrics(pillFont);
            }
            int pillBase2 = pillY + (pillH + pfm.getAscent() - pfm.getDescent()) / 2;
            g2.setFont(pillFont);

            // Species — right-aligned
            int spW = pfm.stringWidth(spLabel) + pillPad * 2;
            int spX = (w - PAD) - spW;
            g2.setColor(new Color(species.displayColor.getRed(), species.displayColor.getGreen(),
                    species.displayColor.getBlue(), 160));
            g2.fillRoundRect(spX, pillY, spW, pillH, 4, 4);
            g2.setColor(Color.WHITE);
            g2.drawString(spLabel, spX + pillPad, pillBase2);

            // Class — amber, after the level pill; capped so it can't reach the species pill
            int clsW = Math.min(pfm.stringWidth(clsLabel) + pillPad * 2, spX - gap - clsX);
            if (clsW > 6) {
                g2.setColor(new Color(160, 110, 30, 180));
                g2.fillRoundRect(clsX, pillY, clsW, pillH, 4, 4);
                g2.setColor(Color.WHITE);
                g2.drawString(clsLabel, clsX + pillPad, pillBase2);
            }
            g2.setFont(smallFont);
        } else {
            // Locked: grey species badge (right-aligned) + plain kill count text
            String spLabel = species.label;
            int spW = sfm.stringWidth(spLabel) + pillPad * 2;
            int spX = w - PAD - spW;
            g2.setColor(new Color(50, 50, 50));
            g2.fillRoundRect(spX, pillY, spW, pillH, 4, 4);
            g2.setColor(new Color(75, 75, 75));
            g2.drawString(spLabel, spX + pillPad, pillBase);

            g2.setColor(new Color(65, 65, 65));
            String killStr = killCount > 0 ? killCount + " kills" : "Not encountered";
            g2.drawString(killStr, imgX + 2, subBaseline);
        }

        // --- Attribute pills: HP (left half) + Prayer + Agility (right half, split) ---
        // HP/Prayer are factual monster info; Agility is the capture's rolled AGI stat,
        // relocated here so the stat block below is the 5 combat stats. Real skill icons.
        {
            int gap = 4;
            int usable = imgW - gap * 2;
            // HP gets a narrower slice so Prayer + Agility have room (agility was clipping on export).
            int hpW = Math.round(usable * 0.50f) - 24;
            int prW = (usable - hpW - gap) / 2;
            int agW = usable - hpW - prW;
            int aY = ATTR_Y;
            int x0 = imgX;
            // Locked cards hide the factual HP/Prayer too (show "?"), matching Agility —
            // uncaptured monsters reveal nothing until encountered.
            String hpVal     = locked ? "?" : String.valueOf(hitpoints);
            String prayerVal = locked ? "?" : String.valueOf(prayerValue);
            drawAttrPill(g2, x0, aY, hpW, ATTR_H, IconType.HP, hpVal, locked);
            x0 += hpW + gap;
            drawAttrPill(g2, x0, aY, prW, ATTR_H, IconType.PRAYER, prayerVal, locked);
            x0 += prW + gap;
            String agiVal = locked ? "?" : String.valueOf(avgStats[AGI_STAT_INDEX]);
            drawAttrPill(g2, x0, aY, agW, ATTR_H, IconType.AGILITY, agiVal, locked);
        }

        // --- Stat bars (captured) / empty outlines (locked) ---
        g2.setFont(smallFont);
        sfm = g2.getFontMetrics();
        // Gold highlight is now stat-driven (class no longer influences stats): a stat glows
        // if it's maxed (>= HL_MAX) or is one of the two highest AND meaningfully high (>= HL_MIN),
        // so weak monsters (e.g. a chicken with all-1 combat stats) don't glow.
        final int HL_MIN = 50, HL_MAX = 90;
        int hl2nd = 0;
        if (!locked) {
            int[] top = java.util.Arrays.copyOf(avgStats, STAT_LABELS.length); // ATK..RNG only
            java.util.Arrays.sort(top); // ascending
            hl2nd = top[top.length - 2]; // 2nd-highest combat stat
        }
        for (int i = 0; i < STAT_LABELS.length; i++) {
            int rowY     = STATS_Y + i * STAT_ROW;
            int baseline = rowY + (STAT_ROW + sfm.getAscent() - sfm.getDescent()) / 2;

            g2.setFont(smallFont);
            boolean primary = !locked
                && (avgStats[i] >= HL_MAX || (avgStats[i] >= HL_MIN && avgStats[i] >= hl2nd));
            // Skill icon as the row label (falls back to the abbreviation if unavailable)
            BufferedImage statIcon = skillImg(STAT_SKILLS[i]);
            if (statIcon != null) {
                int isz = STAT_ROW - 6;
                int ix = imgX + (LABEL_W - isz) / 2;
                int iy = rowY + (STAT_ROW - isz) / 2;
                Graphics2D gi = (Graphics2D) g2.create();
                gi.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                if (locked) gi.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.35f));
                gi.drawImage(statIcon, ix, iy, isz, isz, null);
                gi.dispose();
            } else {
                g2.setColor(primary ? new Color(200, 160, 60) : locked ? new Color(48, 48, 48) : new Color(160, 160, 160));
                g2.drawString(STAT_LABELS[i], imgX, baseline);
            }

            int barX = imgX + LABEL_W + 3;
            int barW = imgW - LABEL_W - VAL_W - 6;
            int barY = rowY + (STAT_ROW - BAR_H) / 2;
            g2.setColor(new Color(28, 28, 28));
            g2.fillRoundRect(barX, barY, barW, BAR_H, 3, 3);

            if (!locked) {
                // Stats cap at 99, so treat 99 as a full (100%) bar.
                int fill = Math.min(barW, Math.round(barW * avgStats[i] / 99f));
                if (fill > 0) {
                    g2.setColor(new Color(rarest.displayColor.getRed(),
                            rarest.displayColor.getGreen(), rarest.displayColor.getBlue(), 210));
                    g2.fillRoundRect(barX, barY, fill, BAR_H, 3, 3);
                }
                g2.setFont(boldFont);
                FontMetrics vfm = g2.getFontMetrics();
                String valStr = String.valueOf(avgStats[i]);
                // Amber value marks a standout stat (top-two / maxed) — see hl2nd above.
                g2.setColor(primary ? new Color(230, 190, 80) : Color.WHITE);
                g2.drawString(valStr, imgX + imgW - vfm.stringWidth(valStr), baseline);
            }
        }

        // Shimmer overlay for Epic+. Strip = 2×actual width so both transparent ends
        // are always off-screen — peak is fully bright when it crosses the right edge.
        if (shimmerTimer != null && shimmerTimer.isRunning()
                && rarest != null && rarest.ordinal() >= CreatureRarity.EPIC.ordinal()) {
            int sw    = getWidth(); // use actual layout width, not the constant
            float cx  = shimmerPhase * (3 * sw) - sw;
            Color mid = rarest == CreatureRarity.MYTHIC
                    ? new Color(255, 120, 120, 110)
                    : rarest == CreatureRarity.LEGENDARY
                    ? new Color(255, 210, 80,  110)
                    : new Color(210, 120, 240, 100);
            Color none = new Color(mid.getRed(), mid.getGreen(), mid.getBlue(), 0);
            g2.setPaint(new java.awt.LinearGradientPaint(
                    cx - sw, 0, cx + sw, 0,
                    new float[]{0f, 0.5f, 1f},
                    new Color[]{none, mid, none}));
            g2.fillRoundRect(0, 0, sw, CARD_H, 8, 8);
        }

        // Shiny: twinkling sparkles + a gold border. Sparkles animate while the
        // timer runs (on hover, and during the periodic global pulse).
        if (hasShiny && !locked) {
            drawShinySparkles(g2, w);
            g2.setStroke(new java.awt.BasicStroke(1.4f));
            g2.setColor(new Color(255, 216, 130, 205));
            g2.drawRoundRect(1, 1, w - 3, CARD_H - 3, 8, 8);
        }

        g2.dispose();
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    /**
     * Draws a handful of small twinkling sparkle stars over a shiny card. Each
     * sparkle's brightness/size is modulated by shimmerPhase (which advances while
     * the animation timer is running), giving a shimmering feel on hover / pulse.
     */
    private void drawShinySparkles(Graphics2D g2, int w) {
        // Confine sparkles to the image box only (x in [PAD, w-PAD], y in [IMAGE_Y, IMAGE_Y+IMAGE_H]).
        int x0 = PAD, y0 = IMAGE_Y, iw = w - PAD * 2, ih = IMAGE_H;
        float[][] frac = {
            { 0.15f, 0.13f }, { 0.76f, 0.22f }, { 0.42f, 0.54f },
            { 0.85f, 0.70f }, { 0.23f, 0.83f },
        };
        java.awt.Stroke old = g2.getStroke();
        g2.setStroke(new java.awt.BasicStroke(1f));
        for (int i = 0; i < frac.length; i++) {
            int x = x0 + Math.round(frac[i][0] * iw);
            int y = y0 + Math.round(frac[i][1] * ih);
            double phase = ((shimmerPhase * 2.0) + i * 0.41) % 1.0;
            double b     = Math.abs(Math.sin(phase * Math.PI)); // 0..1 twinkle
            int alpha    = (int) (70 + 150 * b);
            int size     = 2 + (int) Math.round(3 * b);
            g2.setColor(new Color(255, 244, 180, Math.min(255, alpha)));
            g2.drawLine(x - size, y, x + size, y);
            g2.drawLine(x, y - size, x, y + size);
        }
        g2.setStroke(old);
    }

    private static Graphics2D makeG2(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING,         RenderingHints.VALUE_RENDER_QUALITY);
        return g2;
    }

    private static String truncate(String text, FontMetrics fm, int maxW) {
        if (fm.stringWidth(text) <= maxW) return text;
        while (text.length() > 0 && fm.stringWidth(text + "…") > maxW) {
            text = text.substring(0, text.length() - 1);
        }
        return text + "…";
    }

    /**
     * Escalating colour band for a Power Level, so the pill colour maps consistently
     * to a range: grey → green → blue → purple → orange → red as power climbs.
     * Power can exceed 99 (bosses), so the top bands cover the boss range.
     */
    public static Color powerColor(int power) {
        if (power < 20)  return new Color(150, 150, 150); // trivial
        if (power < 40)  return new Color(110, 190, 110); // low
        if (power < 70)  return new Color(80, 160, 230);  // mid
        if (power < 100) return new Color(170, 120, 235); // high
        if (power < 160) return new Color(240, 150, 45);  // boss
        return new Color(225, 70, 70);                    // apex
    }

    /** Black or white text depending on the band's perceived brightness. */
    private static Color textOn(Color bg) {
        double lum = 0.299 * bg.getRed() + 0.587 * bg.getGreen() + 0.114 * bg.getBlue();
        return lum > 150 ? new Color(25, 25, 25) : Color.WHITE;
    }

    private enum IconType { HP, PRAYER, AGILITY }

    /** Draws a dark rounded pill with an in-game-style icon and a value. */
    private static void drawAttrPill(Graphics2D g, int x, int y, int w, int h,
                                     IconType type, String value, boolean locked) {
        g.setColor(locked ? new Color(24, 24, 24) : new Color(30, 30, 30));
        g.fillRoundRect(x, y, w, h, 5, 5);
        g.setColor(locked ? new Color(40, 40, 40) : new Color(55, 55, 55));
        g.setStroke(new BasicStroke(1f));
        g.drawRoundRect(x, y, w - 1, h - 1, 5, 5);

        int iconSize = h - 4;
        int iconX = x + 5;
        int iconY = y + (h - iconSize) / 2;
        net.runelite.api.Skill sk = type == IconType.HP ? net.runelite.api.Skill.HITPOINTS
                : type == IconType.PRAYER ? net.runelite.api.Skill.PRAYER
                : net.runelite.api.Skill.AGILITY;
        BufferedImage sprite = skillImg(sk);
        if (sprite != null) {
            Graphics2D gi = (Graphics2D) g.create();
            gi.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            if (locked) gi.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.4f));
            gi.drawImage(sprite, iconX, iconY, iconSize, iconSize, null);
            gi.dispose();
        } else {
            // Fallback if the sprite manager isn't wired yet
            if (type == IconType.HP) {
                drawHeartIcon(g, iconX, iconY, iconSize, locked ? new Color(70, 70, 70) : new Color(220, 60, 60));
            } else if (type == IconType.PRAYER) {
                drawPrayerIcon(g, iconX, iconY, iconSize, locked ? new Color(70, 70, 70) : new Color(90, 190, 235));
            } else {
                g.setColor(locked ? new Color(70, 70, 70) : new Color(120, 200, 120));
                g.fillOval(iconX, iconY + 1, iconSize - 2, iconSize - 2);
            }
        }

        // Value text — shrink the font to fit the remaining pill width so large HP
        // (4-5 digits) never overflows into the neighbouring pill.
        int textX = iconX + iconSize + 3;
        int avail = (x + w) - 4 - textX;
        Font vf = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD);
        FontMetrics fm = g.getFontMetrics(vf);
        float vs = vf.getSize2D();
        while (fm.stringWidth(value) > avail && vs > 7f) {
            vs -= 0.5f;
            vf = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, vs);
            fm = g.getFontMetrics(vf);
        }
        g.setFont(vf);
        g.setColor(locked ? new Color(90, 90, 90) : Color.WHITE);
        g.drawString(value, textX, y + (h + fm.getAscent() - fm.getDescent()) / 2);
    }

    /** Red heart, OSRS hitpoints-style. */
    private static void drawHeartIcon(Graphics2D g, int x, int y, int s, Color c) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(c);
        float w = s, h = s;
        java.awt.geom.Path2D.Float p = new java.awt.geom.Path2D.Float();
        p.moveTo(x + w / 2, y + h * 0.82f);
        p.curveTo(x - w * 0.05f, y + h * 0.34f, x + w * 0.18f, y + h * 0.02f, x + w / 2, y + h * 0.30f);
        p.curveTo(x + w * 0.82f, y + h * 0.02f, x + w * 1.05f, y + h * 0.34f, x + w / 2, y + h * 0.82f);
        p.closePath();
        g2.fill(p);
        g2.dispose();
    }

    /** Light-blue teardrop, evoking the OSRS prayer orb. */
    private static void drawPrayerIcon(Graphics2D g, int x, int y, int s, Color c) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(c);
        float w = s, h = s;
        java.awt.geom.Path2D.Float p = new java.awt.geom.Path2D.Float();
        p.moveTo(x + w / 2, y);
        p.curveTo(x + w * 0.98f, y + h * 0.55f, x + w * 0.80f, y + h, x + w / 2, y + h);
        p.curveTo(x + w * 0.20f, y + h, x + w * 0.02f, y + h * 0.55f, x + w / 2, y);
        p.closePath();
        g2.fill(p);
        // soft inner highlight
        g2.setColor(new Color(255, 255, 255, 90));
        g2.fill(new java.awt.geom.Ellipse2D.Float(x + w * 0.42f, y + h * 0.45f, w * 0.22f, h * 0.30f));
        g2.dispose();
    }
}

