    private JPanel upgradeCard(ShopUpgrade u) {
        int owned  = dataService.getUpgradeTier(u);
        boolean maxed = owned >= u.maxTier;
        long cost  = dataService.upgradeCost(u);

        // Cap height to the card's *current* preferred height (recomputed live) so the parent
        // BoxLayout can't stretch the card, while the wrapping description can still grow it.
        JPanel card = new JPanel() {
            @Override public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setBorder(BorderFactory.createCompoundBorder(
                new LineBorder(new Color(255, 165, 0, 70), 1, true),
                new EmptyBorder(8, 8, 8, 8)));
        card.setAlignmentX(LEFT_ALIGNMENT);

        JLabel title = new JLabel(u.title);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(ORANGE);
        title.setAlignmentX(LEFT_ALIGNMENT);
        card.add(title);

        // A wrapping JTextArea in a BorderLayout wraps to the card's real width and reports a
        // correct height (a fixed-width HTML label clips when the panel is narrower than assumed).
        JTextArea desc = new JTextArea(u.description);
        desc.setEditable(false);
        desc.setFocusable(false);
        desc.setLineWrap(true);
        desc.setWrapStyleWord(true);
        desc.setOpaque(false);
        desc.setFont(FontManager.getRunescapeSmallFont());
        desc.setForeground(DIM);
        JPanel descWrap = new JPanel(new BorderLayout());
        descWrap.setOpaque(false);
        descWrap.setAlignmentX(LEFT_ALIGNMENT);
        descWrap.setBorder(new EmptyBorder(2, 0, 4, 0));
        descWrap.add(desc, BorderLayout.CENTER);
        card.add(descWrap);

        // Effect: current bonus, and (unless maxed) what the next tier upgrades it to.
        String effectText = maxed
                ? "Bonus: " + formatEffect(u, owned) + "  (max)"
                : "Bonus: " + formatEffect(u, owned) + "  →  " + formatEffect(u, owned + 1);
        JLabel effect = new JLabel(effectText);
        effect.setFont(FontManager.getRunescapeSmallFont());
        effect.setForeground(GOLD);
        effect.setAlignmentX(LEFT_ALIGNMENT);
        card.add(effect);

        // Tier pips + "N/5"
        JPanel pips = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        pips.setOpaque(false);
        pips.setAlignmentX(LEFT_ALIGNMENT);
        pips.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        for (int i = 0; i < u.maxTier; i++) {
            pips.add(new Pip(i < owned));
        }
        JLabel tierLbl = new JLabel(owned + "/" + u.maxTier);
        tierLbl.setFont(FontManager.getRunescapeSmallFont());
        tierLbl.setForeground(DIM);
        pips.add(tierLbl);
        card.add(pips);

        // Buy button
        JButton buy = new JButton();
        buy.setFont(FontManager.getRunescapeSmallFont());
        buy.setFocusPainted(false);
        buy.setAlignmentX(LEFT_ALIGNMENT);
        if (maxed) {
            buy.setText("MAXED");
            buy.setEnabled(false);
            buy.setForeground(PIP_ON);
        } else {
            boolean afford = dataService.getCredits() >= cost;
            buy.setText("Buy tier " + (owned + 1) + "  ·  " + cost + " credits");
            buy.setEnabled(afford);
            buy.setForeground(afford ? GOLD : DIM);
            buy.addActionListener(e -> {
                if (dataService.purchaseUpgrade(u)) {
                    refresh();
                    BestiaryPanel.recheckAchievements();
                }
            });
            // Registered so a credit-only change (e.g. a capture) can re-check affordability in place,
            // without rebuilding the card (the rebuild is what made the shop jiggle on capture).
            buyButtons.put(u, buy);
        }
        card.add(Box.createVerticalStrut(4));
        card.add(buy);
        return card;
    }

    /** Formats a fractional probability as a percentage, e.g. 0.003 -> "0.3%". */
    private static String formatPct(double frac) {
        return String.format("%.1f%%", frac * 100.0);
    }

    /** Formats an upgrade's total effect at {@code tiers} — flat credits, flat XP, or a percentage. */
    private static String formatEffect(ShopUpgrade u, int tiers) {
        if (u.isFlatCredits()) return "+" + (long) u.effectFor(tiers) + " credits";
        if (u.isFlatXp())      return "+" + (long) u.effectFor(tiers) + " XP";
        return "+" + formatPct(u.effectFor(tiers));
    }

    /** A small round tier indicator. */
    private static final class Pip extends JComponent {
        private final boolean on;
        Pip(boolean on) {
            this.on = on;
            setPreferredSize(new Dimension(10, 10));
        }
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(on ? PIP_ON : PIP_OFF);
            g2.fillOval(0, 0, 9, 9);
            g2.dispose();
        }
    }

    // -------------------------------------------------------------------------
    // Refresh
    // -------------------------------------------------------------------------

    public void refresh() {
        // Rebuilding the upgrade cards (removeAll + re-add) is what makes the shop visibly "jiggle".
        // The panel refreshes on every kill, and a CAPTURE awards credits — so rebuilding whenever
        // credits move meant the shop jumped on every capture. Split the cases:
        //   • an owned TIER changed (a purchase) → full rebuild (rare, user-initiated, expected).
        //   • only CREDITS changed (a capture / discard) → re-check buy-button affordability in place,
        //     with NO teardown, so nothing shifts.
        //   • nothing changed → no-op.
        long credits  = dataService.getCredits();
        int  tierSig  = tierSignature();

        if (tierSig != lastTierSig) {
            lastTierSig = tierSig;
            lastCredits = credits;
            creditsLabel.setText(credits + " credits");
            if (contentCards != null) {
                // Preserve the active tab's scroll position so a rebuild doesn't jump the shop.
                final JScrollPane active = categoryScrolls.get(ShopCategory.values()[selectedCat]);
                final Point pos = active != null ? active.getViewport().getViewPosition() : null;
                rebuildUpgrades();
                if (active != null && pos != null) {
                    SwingUtilities.invokeLater(() -> active.getViewport().setViewPosition(pos));
                }
            }
            return;
        }

        if (credits != lastCredits) {
            lastCredits = credits;
            creditsLabel.setText(credits + " credits");
            updateAffordability(credits);
        }
    }

    /** Owned tiers when the cards were last built; a change means a purchase → full rebuild needed. */
    private int  lastTierSig = Integer.MIN_VALUE;
    /** Credit balance at the last refresh; a change alone only re-checks affordability (no rebuild). */
    private long lastCredits = Long.MIN_VALUE;

    /** A fingerprint of every upgrade's owned tier — changes only on a purchase. */
    private int tierSignature() {
        int sig = 1;
        for (ShopUpgrade u : ShopUpgrade.values()) {
            sig = sig * 31 + dataService.getUpgradeTier(u);
        }
        // Fold in the Level 99 unlock so reaching level 99 rebuilds the shop (revealing the tab).
        sig = sig * 31 + (dataService.isLevel99Unlocked() ? 1 : 0);
        return sig;
    }

    /**
     * Re-checks each (non-maxed) buy button against the new credit balance, toggling only its
     * enabled state and colour. This touches no layout, so it can run on every capture without the
     * shop shifting — unlike a full {@link #rebuildUpgrades()}. Tier costs are unchanged here (only a
     * purchase changes a tier, and that path rebuilds), so the button text needs no update.
     */
    private void updateAffordability(long credits) {
        for (java.util.Map.Entry<ShopUpgrade, JButton> e : buyButtons.entrySet()) {
            long cost = dataService.upgradeCost(e.getKey());   // -1 if maxed (not in the map anyway)
            boolean afford = cost >= 0 && credits >= cost;
            JButton buy = e.getValue();
            buy.setEnabled(afford);
            buy.setForeground(afford ? GOLD : DIM);
        }
    }
}

package com.bestiary.ui;

import com.bestiary.model.Achievement;
import com.bestiary.service.ProgressionService;
import com.bestiary.service.SessionTracker;
import com.bestiary.util.XpTable;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * Progress tab: Capture Level bar, XP totals, achievement list, and session recap button.
 */
public class ProgressTab extends JPanel {

    private final ProgressionService progressionService;
    private final SessionTracker sessionTracker;

    private final JLabel levelLabel;
    private final JProgressBar xpBar;
    private final JLabel xpLabel;
    private final JPanel achievementPanel;
    private final JLabel achievementHeader = new JLabel("Achievements");
    private final JToggleButton hideCompleteBox = new JToggleButton("Hide complete");

    public ProgressTab(ProgressionService progressionService, SessionTracker sessionTracker,
                       Runnable showDashboard) {
        this.progressionService = progressionService;
        this.sessionTracker     = sessionTracker;
        setLayout(new BorderLayout(0, 8));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(8, 8, 8, 8));

        // Level header
        JPanel levelPanel = new JPanel(new BorderLayout(0, 4));
        levelPanel.setOpaque(false);

        levelLabel = new JLabel("Capture Level 1", SwingConstants.CENTER);
        levelLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
        levelLabel.setForeground(Color.WHITE);

        xpBar = new JProgressBar(0, 100);
        xpBar.setStringPainted(false);
        xpBar.setForeground(new Color(255, 165, 0)); // orange theme
        xpBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        xpBar.setBorderPainted(false);
        xpBar.setPreferredSize(new Dimension(0, 8));

        xpLabel = new JLabel("0 XP  |  Next level: calculating...", SwingConstants.CENTER);
        xpLabel.setFont(FontManager.getRunescapeSmallFont());
        xpLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        levelPanel.add(levelLabel, BorderLayout.NORTH);
        levelPanel.add(xpBar,     BorderLayout.CENTER);
        levelPanel.add(xpLabel,   BorderLayout.SOUTH);

        // Session Recap button
        JButton recapBtn = new JButton("Session Recap");
        recapBtn.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        recapBtn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        recapBtn.setForeground(new Color(255, 165, 0));
        recapBtn.setFocusPainted(false);
        recapBtn.setBorderPainted(true);
        recapBtn.setToolTipText("View captures from this session");
        recapBtn.addActionListener(e ->
            SessionRecapDialog.open(SwingUtilities.getWindowAncestor(this), sessionTracker));

        // Show Dashboard button — opens the Progression dashboard (same flow as the Info tab stat boxes)
        JButton dashBtn = new JButton("Show Dashboard");
        dashBtn.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        dashBtn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        dashBtn.setForeground(new Color(255, 165, 0));
        dashBtn.setFocusPainted(false);
        dashBtn.setBorderPainted(true);
        dashBtn.setToolTipText("Open the Progression dashboard");
        dashBtn.addActionListener(e -> { if (showDashboard != null) showDashboard.run(); });

        // Two full-span rows, stacked (Session Recap above, Show Dashboard below).
        JPanel recapRow = new JPanel(new GridLayout(2, 1, 0, 4));
        recapRow.setOpaque(false);
        recapRow.setBorder(new EmptyBorder(4, 0, 4, 0));
        recapRow.add(recapBtn);
        recapRow.add(dashBtn);

        // Achievements
        achievementPanel = new JPanel();
        achievementPanel.setLayout(new BoxLayout(achievementPanel, BoxLayout.Y_AXIS));
        achievementPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JScrollPane scroll = new JScrollPane(achievementPanel);
        scroll.setBorder(null);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        // Invisible vertical scrollbar (no width taken) — mouse wheel still scrolls
        scroll.getVerticalScrollBar().setPreferredSize(new java.awt.Dimension(0, 0));
        scroll.getVerticalScrollBar().setUnitIncrement(16);

        achievementHeader.setFont(FontManager.getRunescapeBoldFont());
        achievementHeader.setForeground(Color.WHITE);
        achievementHeader.setBorder(new EmptyBorder(4, 0, 4, 0));
        achievementHeader.setAlignmentX(LEFT_ALIGNMENT);

        // "Hide complete" filter — hides unlocked achievements so the remaining goals are easy to scan.
        TabStyle.prepare(hideCompleteBox);
        TabStyle.style(hideCompleteBox, false);
        hideCompleteBox.setToolTipText("Only show achievements you haven't unlocked yet");
        hideCompleteBox.addActionListener(e -> {
            TabStyle.style(hideCompleteBox, hideCompleteBox.isSelected());
            hideCompleteBox.setText(hideCompleteBox.isSelected() ? "✔ Hide complete" : "Hide complete");
            refresh();
        });

        // Own row above the header: sharing a row with "Achievements (x / y)" clipped the checkbox
        // in the narrow side panel.
        hideCompleteBox.setAlignmentX(LEFT_ALIGNMENT);
        JPanel achTop = new JPanel();
        achTop.setOpaque(false);
        achTop.setLayout(new BoxLayout(achTop, BoxLayout.Y_AXIS));
        achTop.add(hideCompleteBox);
        achTop.add(achievementHeader);

        JPanel centerPanel = new JPanel(new BorderLayout());
        centerPanel.setOpaque(false);
        centerPanel.add(achTop, BorderLayout.NORTH);
        centerPanel.add(scroll, BorderLayout.CENTER);

        JPanel northStack = new JPanel(new BorderLayout(0, 0));
        northStack.setOpaque(false);
        northStack.add(levelPanel, BorderLayout.NORTH);
        northStack.add(recapRow,   BorderLayout.CENTER);

        add(northStack,  BorderLayout.NORTH);
        add(centerPanel, BorderLayout.CENTER);

        refresh();
    }

    /** Rebuild UI to reflect current progression state. Call on EDT. */
    public void refresh() {
        int level      = progressionService.getLevel();
        long totalXp   = progressionService.getTotalXp();
        long toNext    = progressionService.getXpToNextLevel();

        levelLabel.setText("Capture Level " + level);

        if (level < XpTable.MAX_VIRTUAL_LEVEL) {
            // Normal per-level progress, including virtual levels 100-126 past the skill cap.
            long xpThisLevel  = totalXp - XpTable.xpForLevel(level);
            long xpLevelRange = XpTable.xpForLevel(level + 1) - XpTable.xpForLevel(level);
            int pct = (int) (100L * xpThisLevel / Math.max(1, xpLevelRange));
            xpBar.setValue(pct);
            xpLabel.setText(String.format("%,d XP  |  Next level in %,d XP", totalXp, toNext));
        } else {
            // Level 126 / 200M XP: fully maxed.
            xpBar.setValue(100);
            xpLabel.setText(String.format("%,d XP  |  200M XP reached!", totalXp));
        }

        // Rebuild achievement rows
        achievementPanel.removeAll();
        ProgressionService.ProgressionState state = progressionService.getState();

        int total    = Achievement.values().length;
        int unlocked = state.unlockedAchievements.size();
        achievementHeader.setText("Achievements  (" + unlocked + " / " + total + ")");

        boolean hideComplete = hideCompleteBox.isSelected();
        for (Achievement a : Achievement.values()) {
            boolean done = state.unlockedAchievements.contains(a);
            if (done && hideComplete) continue;
            achievementPanel.add(buildAchievementRow(a, done));
            achievementPanel.add(Box.createVerticalStrut(2));
        }
        if (hideComplete && unlocked == total) {
            JLabel allDone = new JLabel("All achievements complete!");
            allDone.setFont(FontManager.getRunescapeSmallFont());
            allDone.setForeground(new Color(80, 200, 80));
            achievementPanel.add(allDone);
        }

        achievementPanel.revalidate();
        achievementPanel.repaint();
        revalidate();
        repaint();
    }

    private JPanel buildAchievementRow(Achievement a, boolean unlocked) {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setBackground(unlocked ? ColorScheme.DARKER_GRAY_COLOR : new Color(30, 30, 30));
        Color accent = unlocked ? new Color(80, 200, 80) : new Color(55, 55, 55);
        row.setBorder(BorderFactory.createCompoundBorder(
                new javax.swing.border.MatteBorder(0, 3, 0, 0, accent),
                new EmptyBorder(5, 8, 5, 8)));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
        // Tooltip must sit on the leaf components too — Swing shows the tooltip of the
        // component directly under the cursor, not the parent row.
        String tip = a.creditReward > 0
                ? "Reward: +" + a.creditReward + " credits" + (unlocked ? " (earned)" : "")
                : null;
        row.setToolTipText(tip);

        JLabel icon = new JLabel(unlocked ? "✔" : "○");
        icon.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        icon.setForeground(unlocked ? new Color(80, 200, 80) : ColorScheme.MEDIUM_GRAY_COLOR);

        JPanel text = new JPanel(new GridLayout(2, 1, 0, 1));
        text.setOpaque(false);

        JLabel title = new JLabel(a.title);
        title.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        title.setForeground(unlocked ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);

        JLabel desc = new JLabel(a.description);
        desc.setFont(FontManager.getRunescapeSmallFont());
        desc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        text.add(title);
        text.add(desc);

        icon.setToolTipText(tip);
        text.setToolTipText(tip);
        title.setToolTipText(tip);
        desc.setToolTipText(tip);

        row.add(icon, BorderLayout.WEST);
        row.add(text, BorderLayout.CENTER);
        return row;
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureQuality;
import com.bestiary.util.OddsCalculator;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;

/**
 * Per-card graphs, switchable via a dropdown:
 *  - <b>Reroll timeline</b> — a line chart of each stat across the reroll timeline (Original → Now);
 *    every stat is a toggleable series, the Y axis auto-zooms to the visible values, and hovering a
 *    point shows that roll's per-stat deltas.
 *  - <b>Percentile</b> — how this card's current stats rank within the possible roll band for its
 *    rarity (0% = the weakest possible roll, 100% = the best).
 */
public class RerollGraph extends JPanel {

    private enum Mode { TIMELINE, PERCENTILE }

    private static final String[] NAMES  = {"ATK", "STR", "DEF", "MAG", "RNG", "AGI", "PRAY", "PWR"};
    private static final Color[]  COLORS = {
            new Color(210, 90, 90),  new Color(230, 150, 60), new Color(90, 140, 255),
            new Color(175, 105, 225), new Color(90, 200, 90),  new Color(80, 205, 205),
            new Color(235, 205, 95),  new Color(235, 235, 235)
    };

    // Timeline data
    private final String[] labels;      // point labels
    private final int[][] values;       // [series 0..7][point]; -1 = missing
    private final boolean[] available;
    private final boolean[] visible;

    // Percentile data (current card vs its rarity's roll band)
    private final String[] pctNames;
    private final int[] pctValue, pctLo, pctHi;

    private Mode mode;
    private final Chart chart;
    private final JPanel toggles;

    public RerollGraph(CapturedCreature c) {
        setLayout(new BorderLayout(0, 4));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(8, 12, 10, 12));

        // ---- timeline series ----
        int n = c.rerollCount() + 1;
        labels = new String[n];
        values = new int[8][n];
        available = new boolean[8];
        visible = new boolean[8];
        List<CapturedCreature.RerollState> h = c.rerollHistory;
        for (int i = 0; i < n; i++) {
            boolean isCurrent = i == h.size();
            CreatureQuality q = isCurrent ? c.quality : h.get(i).quality;
            int prayer = q != null ? q.prayer : -1;
            int power  = isCurrent ? c.powerLevel() : h.get(i).powerLevel;
            labels[i] = isCurrent ? "Now" : (i == 0 ? "Orig" : "R" + i);
            int[] combat = q != null
                    ? new int[]{q.attack, q.strength, q.defence, q.magic, q.ranged, q.agility}
                    : new int[]{-1, -1, -1, -1, -1, -1};
            for (int s = 0; s < 6; s++) values[s][i] = combat[s];
            values[6][i] = prayer;
            values[7][i] = power;
        }
        for (int s = 0; s < 8; s++) {
            boolean ok = true;
            for (int i = 0; i < n; i++) if (values[s][i] < 0) ok = false;
            available[s] = ok;
            visible[s]   = ok && s != 7;   // default: stats + prayer on, Power off
        }

        // ---- percentile bands (current card vs rarity range) ----
        OddsCalculator.Result r = OddsCalculator.compute(c);
        int m = r.stats.size();
        pctNames = new String[m];
        pctValue = new int[m];
        pctLo = new int[m];
        pctHi = new int[m];
        for (int i = 0; i < m; i++) {
            OddsCalculator.StatOdds s = r.stats.get(i);
            pctNames[i] = s.name;
            pctValue[i] = s.value;
            pctLo[i] = s.lo;
            pctHi[i] = s.hi;
        }

        boolean rerolled = c.rerollCount() > 0;
        mode = Mode.PERCENTILE;   // percentile is the more broadly useful default

        chart = new Chart();
        toggles = buildToggles();
        add(buildSwitcher(rerolled), BorderLayout.NORTH);
        add(chart, BorderLayout.CENTER);
        add(toggles, BorderLayout.SOUTH);
        toggles.setVisible(false);
    }

    private JComponent buildSwitcher(boolean rerolled) {
        JComboBox<String> combo = new JComboBox<>(rerolled
                ? new String[]{"Percentile (this rarity)", "Reroll timeline"}
                : new String[]{"Percentile (this rarity)"});
        combo.setFont(FontManager.getRunescapeSmallFont());
        combo.addActionListener(e -> {
            mode = "Reroll timeline".equals(combo.getSelectedItem()) ? Mode.TIMELINE : Mode.PERCENTILE;
            toggles.setVisible(mode == Mode.TIMELINE);
            chart.repaint();
            revalidate();
        });
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);
        JLabel l = new JLabel("Graph:  ");
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        row.add(l, BorderLayout.WEST);
        row.add(combo, BorderLayout.CENTER);
        return row;
    }

    private JPanel buildToggles() {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        row.setOpaque(false);
        for (int s = 0; s < 8; s++) {
            final int idx = s;
            JToggleButton b = new JToggleButton(NAMES[s], visible[s]);
            b.setFont(FontManager.getRunescapeSmallFont());
            b.setForeground(COLORS[s]);
            b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            b.setOpaque(true);
            b.setFocusPainted(false);
            b.setBorderPainted(false);
            b.setMargin(new Insets(1, 5, 1, 5));
            b.setEnabled(available[s]);
            if (!available[s]) b.setToolTipText("No data for this stat on older rerolls");
            b.addActionListener(e -> { visible[idx] = b.isSelected(); chart.repaint(); });
            row.add(b);
        }
        return row;
    }

    private final class Chart extends JPanel {
        Chart() {
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            addMouseMotionListener(new MouseAdapter() {
                @Override public void mouseMoved(MouseEvent e) { setToolTipText(pointTip(e.getX())); }
            });
        }

        @Override
        protected void paintComponent(Graphics g0) {
            super.paintComponent(g0);
            Graphics2D g = (Graphics2D) g0.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setFont(FontManager.getRunescapeSmallFont());
            if (mode == Mode.PERCENTILE) drawPercentile(g);
            else drawTimeline(g);
            g.dispose();
        }

        private void drawTimeline(Graphics2D g) {
            int w = getWidth(), h = getHeight();
            int padL = 36, padR = 10, padT = 10, padB = 20;
            int plotW = w - padL - padR, plotH = h - padT - padB;
            int n = labels.length;

            if (n < 2) { message(g, w, h, "Reroll this card to chart how its stats change."); return; }

            int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
            boolean any = false;
            for (int s = 0; s < 8; s++) if (visible[s] && available[s]) {
                any = true;
                for (int v : values[s]) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
            }
            if (!any) { message(g, w, h, "Toggle a stat below to plot it."); return; }
            if (hi == lo) { lo -= 2; hi += 2; }
            int pad = Math.max(1, (int) Math.ceil((hi - lo) * 0.15));
            int yLo = Math.max(0, lo - pad), yHi = hi + pad;
            double span = Math.max(1, yHi - yLo);

            for (int gl = 0; gl <= 4; gl++) {
                int y = padT + plotH - (plotH * gl / 4);
                int val = (int) Math.round(yLo + span * gl / 4);
                g.setColor(new Color(58, 58, 58));
                g.drawLine(padL, y, padL + plotW, y);
                g.setColor(new Color(120, 120, 120));
                g.drawString(String.valueOf(val), 4, y + 4);
            }
            g.setColor(new Color(150, 150, 150));
            for (int i = 0; i < n; i++) {
                int x = padL + plotW * i / (n - 1);
                g.drawString(labels[i], x - g.getFontMetrics().stringWidth(labels[i]) / 2, h - 6);
            }
            for (int s = 0; s < 8; s++) {
                if (!visible[s] || !available[s]) continue;
                g.setColor(COLORS[s]);
                g.setStroke(new BasicStroke(2f));
                int prevX = 0, prevY = 0;
                for (int i = 0; i < n; i++) {
                    int x = padL + plotW * i / (n - 1);
                    int y = padT + plotH - (int) ((values[s][i] - yLo) / span * plotH);
                    if (i > 0) g.drawLine(prevX, prevY, x, y);
                    g.fillOval(x - 3, y - 3, 6, 6);
                    prevX = x; prevY = y;
                }
            }
        }

        private void drawPercentile(Graphics2D g) {
            int w = getWidth(), h = getHeight();
            int n = pctNames.length;
            int padT = 10, padB = 10, left = 64, right = 118;
            int barX = left, barW = Math.max(20, w - left - right);
            int rows = n + 1;   // Overall + per-stat
            int rowH = Math.max(16, (h - padT - padB) / rows);

            // Overall = average of the per-stat percentiles ("how maxed out" — 50% ≈ an average roll).
            double overall = 0;
            for (int i = 0; i < n; i++) overall += pOf(i);
            overall = n > 0 ? overall / n : 0;
            drawPctRow(g, padT + rowH / 2, "Overall", overall,
                    Math.round(overall * 100) + "%  " + tier(overall), barX, barW, true);
            g.setColor(new Color(72, 72, 72));
            g.drawLine(4, padT + rowH, w - 6, padT + rowH);

            for (int i = 0; i < n; i++) {
                int cy = padT + (i + 1) * rowH + rowH / 2;
                double p = pOf(i);
                drawPctRow(g, cy, pctNames[i], p,
                        pctValue[i] + "  (" + Math.round(p * 100) + "%)", barX, barW, false);
            }
        }

        private double pOf(int i) {
            double p = pctHi[i] > pctLo[i]
                    ? (pctValue[i] - pctLo[i]) / (double) (pctHi[i] - pctLo[i])
                    : (pctValue[i] >= pctHi[i] ? 1.0 : 0.5);
            return Math.max(0, Math.min(1, p));
        }

        private void drawPctRow(Graphics2D g, int cy, String label, double p, String rightText,
                                int barX, int barW, boolean bold) {
            g.setFont(bold ? FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD)
                           : FontManager.getRunescapeSmallFont());
            g.setColor(bold ? new Color(255, 200, 90) : new Color(200, 200, 200));
            g.drawString(label, 4, cy + 4);
            int by = cy - 5;
            g.setColor(new Color(45, 45, 45));
            g.fillRoundRect(barX, by, barW, 10, 4, 4);
            g.setColor(pctColor(p));
            g.fillRoundRect(barX, by, Math.max(2, (int) (barW * p)), 10, 4, 4);
            g.setColor(bold ? Color.WHITE : new Color(200, 200, 200));
            g.drawString(rightText, barX + barW + 6, cy + 4);
        }

        private String tier(double p) {
            if (p >= 0.85) return "near-max";
            if (p >= 0.65) return "strong";
            if (p >= 0.40) return "average";
            if (p >= 0.20) return "low";
            return "poor";
        }

        private void message(Graphics2D g, int w, int h, String msg) {
            g.setColor(new Color(150, 150, 150));
            g.drawString(msg, (w - g.getFontMetrics().stringWidth(msg)) / 2, h / 2);
        }
    }

    /** Timeline hover tooltip: the nearest roll's per-stat values + deltas from the previous roll. */
    private String pointTip(int mouseX) {
        if (mode != Mode.TIMELINE) return null;
        int n = labels.length;
        if (n < 2) return null;
        int padL = 36, padR = 10;
        int plotW = chart.getWidth() - padL - padR;
        if (plotW <= 0) return null;
        int best = -1;
        double bestDx = 14;
        for (int i = 0; i < n; i++) {
            int x = padL + plotW * i / (n - 1);
            if (Math.abs(mouseX - x) < bestDx) { best = i; bestDx = Math.abs(mouseX - x); }
        }
        if (best < 0) return null;

        StringBuilder sb = new StringBuilder("<html><b>").append(labelLong(best)).append("</b>");
        for (int s = 0; s < 8; s++) {
            if (!visible[s] || !available[s]) continue;
            String hex = String.format("#%06x", COLORS[s].getRGB() & 0xFFFFFF);
            sb.append("<br><font color='").append(hex).append("'>").append(NAMES[s]).append("</font> ")
              .append(values[s][best]);
            if (best > 0) {
                int d = values[s][best] - values[s][best - 1];
                String dcol = d > 0 ? "#78dc78" : d < 0 ? "#e07070" : "#909090";
                sb.append(" <font color='").append(dcol).append("'>")
                  .append(d > 0 ? "+" + d : String.valueOf(d)).append("</font>");
            }
        }
        return sb.append("</html>").toString();
    }

    private String labelLong(int i) {
        if (i == 0) return "Original roll";
        if (i == labels.length - 1) return "Current";
        return "Reroll " + i;
    }

    private static Color pctColor(double p) {
        // red (weak roll) → amber → green (top roll)
        int red   = (int) (235 * (1 - p) + 90 * p);
        int green = (int) (90 * (1 - p) + 210 * p);
        return new Color(Math.min(255, red), Math.min(255, green), 70);
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;

import javax.swing.*;
import java.awt.*;

/**
 * MODELESS standalone "What were the odds?" dialog — a thin wrapper around {@link OddsView}
 * (which is also embedded in the {@link CardDataDialog} "Odds" tab).
 */
public class OddsDialog extends JDialog {

    private static OddsDialog current;

    public static void open(Window owner, CapturedCreature capture) {
        if (current != null && current.isShowing()) current.dispose();
        current = new OddsDialog(owner, capture);
        current.setVisible(true);
    }

    private OddsDialog(Window owner, CapturedCreature capture) {
        super(owner, "What were the odds?", ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setResizable(true);

        OddsView root = new OddsView(capture);
        JScrollPane scroll = new JScrollPane(root,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(null);
        scroll.getVerticalScrollBar().setUnitIncrement(16);

        Dimension pref = root.getPreferredSize();
        Rectangle screen = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
        int w = Math.max(360, Math.min(screen.width - 80, pref.width + 30));
        int h = Math.min(screen.height - 120, pref.height + 8);
        scroll.setPreferredSize(new Dimension(w, h));

        setContentPane(scroll);
        pack();
        setMinimumSize(new Dimension(340, 260));
        setLocationRelativeTo(owner);
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.service.BestiaryDataService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * MODELESS bulk-discard screen. Finds duplicate captures (same creature + rarity,
 * count > 1), lists each group with an "Investigate" link (filters the album behind
 * it), and converts the extras to credits — keeping the best of each.
 */
public class DiscardDialog extends JDialog {

    private static DiscardDialog current;

    private final BestiaryDataService dataService;
    private final Runnable onDone;
    private final Map<CreatureRarity, JCheckBox> rarityBoxes = new LinkedHashMap<>();
    private JCheckBox protectBox;
    private JCheckBox protectShinyBox;
    private JPanel groupsPanel;
    private JLabel totalLabel;
    private JButton discardBtn;

    public static void open(Window owner, BestiaryDataService dataService, Runnable onDone) {
        if (current != null && current.isShowing()) current.dispose();
        current = new DiscardDialog(owner, dataService, onDone);
        current.setVisible(true);
    }

    /** Re-scan for duplicates (e.g. after a card was discarded elsewhere). */
    public static void refreshOpen() {
        if (current != null && current.isShowing()) current.recompute();
    }

    private DiscardDialog(Window owner, BestiaryDataService dataService, Runnable onDone) {
        super(owner, "Discard duplicates", ModalityType.MODELESS);
        this.dataService = dataService;
        this.onDone = onDone;
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(new EmptyBorder(12, 14, 12, 14));

        JLabel title = new JLabel("Discard duplicates for credits");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(title);
        JLabel help = new JLabel("<html><div style='width:320px'>Keeps the best (highest Power Level) "
                + "of each creature + rarity and discards the rest. Use <i>Investigate</i> to review a "
                + "group in the album first.</div></html>");
        help.setFont(FontManager.getRunescapeSmallFont());
        help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        help.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(help);

        root.add(Box.createVerticalStrut(8));
        JLabel rHdr = header("RARITIES TO INCLUDE");
        root.add(rHdr);
        JPanel rarRow = new JPanel(new GridLayout(0, 3, 4, 0));
        rarRow.setOpaque(false);
        rarRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        rarRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
        for (CreatureRarity rar : CreatureRarity.values()) {
            JCheckBox cb = new JCheckBox(rar.label, rar.ordinal() <= CreatureRarity.RARE.ordinal());
            cb.setOpaque(false);
            cb.setForeground(rar.displayColor);
            cb.setFont(FontManager.getRunescapeSmallFont());
            cb.addActionListener(e -> recompute());
            rarityBoxes.put(rar, cb);
            rarRow.add(cb);
        }
        root.add(rarRow);

        protectBox = new JCheckBox("Protect favourites & album covers", true);
        protectBox.setOpaque(false);
        protectBox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        protectBox.setFont(FontManager.getRunescapeSmallFont());
        protectBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        protectBox.addActionListener(e -> recompute());
        root.add(Box.createVerticalStrut(4));
        root.add(protectBox);

        protectShinyBox = new JCheckBox("Protect shinies", true);
        protectShinyBox.setOpaque(false);
        protectShinyBox.setForeground(new Color(255, 225, 120));
        protectShinyBox.setFont(FontManager.getRunescapeSmallFont());
        protectShinyBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        protectShinyBox.addActionListener(e -> recompute());
        root.add(protectShinyBox);

        root.add(Box.createVerticalStrut(8));
        root.add(header("DUPLICATE GROUPS FOUND"));
        groupsPanel = new JPanel();
        groupsPanel.setLayout(new BoxLayout(groupsPanel, BoxLayout.Y_AXIS));
        groupsPanel.setOpaque(false);
        JScrollPane groupScroll = new JScrollPane(groupsPanel,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        groupScroll.setBorder(BorderFactory.createLineBorder(new Color(60, 60, 60)));
        groupScroll.getVerticalScrollBar().setUnitIncrement(16);
        groupScroll.setPreferredSize(new Dimension(360, 200));
        groupScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        groupScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 200));
        root.add(groupScroll);

        root.add(Box.createVerticalStrut(8));
        totalLabel = new JLabel();
        totalLabel.setFont(FontManager.getRunescapeSmallFont());
        totalLabel.setForeground(Color.WHITE);
        totalLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(totalLabel);

        root.add(Box.createVerticalStrut(6));
        discardBtn = new JButton("Discard");
        discardBtn.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        discardBtn.setBackground(new Color(150, 60, 60));
        discardBtn.setForeground(Color.WHITE);
        discardBtn.setFocusPainted(false);
        discardBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
        discardBtn.addActionListener(e -> doDiscard());
        root.add(discardBtn);

        setContentPane(root);
        recompute();
        pack();
        setLocationRelativeTo(owner);
    }

    private JLabel header(String text) {
        JLabel l = new JLabel(text);
        l.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        l.setForeground(new Color(255, 152, 31));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        l.setBorder(new EmptyBorder(0, 0, 3, 0));
        return l;
    }

    /** One duplicate group: same creature + rarity, keep the best, discard the rest. */
    private static final class Group {
        final String npc;
        final CreatureRarity rarity;
        final List<CapturedCreature> discard = new ArrayList<>();
        Group(String npc, CreatureRarity rarity) { this.npc = npc; this.rarity = rarity; }
    }

    private List<Group> groups() {
        Map<String, List<CapturedCreature>> byKey = new LinkedHashMap<>();
        for (CapturedCreature c : dataService.getCollection().creatures) {
            byKey.computeIfAbsent(c.npcName + "|" + c.rarity.name(), k -> new ArrayList<>()).add(c);
        }
        boolean protect = protectBox.isSelected();
        boolean protectShiny = protectShinyBox.isSelected();
        List<Group> out = new ArrayList<>();
        for (List<CapturedCreature> list : byKey.values()) {
            if (list.size() <= 1) continue;
            CreatureRarity rar = list.get(0).rarity;
            if (!rarityBoxes.get(rar).isSelected()) continue;
            list.sort((a, b) -> Integer.compare(b.powerLevel(), a.powerLevel())); // best first
            Group g = new Group(list.get(0).npcName, rar);
            for (int i = 1; i < list.size(); i++) {
                CapturedCreature c = list.get(i);
                if (protect && (c.favourite || c.albumCover)) continue;
                if (protectShiny && c.isShiny()) continue;
                g.discard.add(c);
            }
            if (!g.discard.isEmpty()) out.add(g);
        }
        return out;
    }

    private void recompute() {
        List<Group> groups = groups();
        groupsPanel.removeAll();
        long total = 0;
        long totalBonus = 0;
        int cards = 0;
        for (Group g : groups) {
            long credits = g.discard.stream().mapToLong(dataService::discardValue).sum();
            long base    = g.discard.stream().mapToLong(dataService::discardValueBase).sum();
            long bonus   = credits - base;   // extra credits from the Salvager's Eye shop upgrade
            total += credits;
            totalBonus += bonus;
            cards += g.discard.size();

            JPanel rowP = new JPanel(new BorderLayout(6, 0));
            rowP.setOpaque(false);
            rowP.setAlignmentX(Component.LEFT_ALIGNMENT);
            rowP.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
            rowP.setBorder(new EmptyBorder(1, 2, 1, 2));
            String main = g.npc + "  ·  " + g.rarity.label + "  ·  discard " + g.discard.size()
                    + "  (+" + base + "cr)";
            String html = "<html><span style='color:" + hex(g.rarity.displayColor) + "'>" + main + "</span>"
                    + (bonus > 0 ? "<span style='color:" + hex(BONUS_COLOR) + "'> (+" + bonus + ")</span>" : "")
                    + "</html>";
            JLabel l = new JLabel(html);
            l.setFont(FontManager.getRunescapeSmallFont());
            l.setForeground(g.rarity.displayColor);

            JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
            actions.setOpaque(false);
            JButton inv = new JButton("Investigate");
            inv.setFont(FontManager.getRunescapeSmallFont());
            inv.setMargin(new Insets(0, 5, 0, 5));
            inv.setFocusPainted(false);
            inv.addActionListener(e -> AlbumDialog.requestOpenDetail(g.npc, g.rarity));
            JButton drop = new JButton("Discard");
            drop.setFont(FontManager.getRunescapeSmallFont());
            drop.setMargin(new Insets(0, 5, 0, 5));
            drop.setFocusPainted(false);
            drop.setForeground(new Color(230, 140, 140));
            drop.addActionListener(e -> discardCards(new ArrayList<>(g.discard)));
            actions.add(inv);
            actions.add(drop);

            rowP.add(l, BorderLayout.CENTER);
            rowP.add(actions, BorderLayout.EAST);
            groupsPanel.add(rowP);
        }
        if (groups.isEmpty()) {
            JLabel none = new JLabel("No duplicates match the current filters.");
            none.setFont(FontManager.getRunescapeSmallFont());
            none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            none.setBorder(new EmptyBorder(6, 4, 0, 0));
            groupsPanel.add(none);
        }
        groupsPanel.revalidate();
        groupsPanel.repaint();

        String totalMain = cards + " duplicate card" + (cards == 1 ? "" : "s")
                + " across " + groups.size() + " group" + (groups.size() == 1 ? "" : "s")
                + "  →  " + (total - totalBonus) + " credits";
        totalLabel.setText("<html><span style='color:#ffffff'>" + totalMain + "</span>"
                + (totalBonus > 0 ? "<span style='color:" + hex(BONUS_COLOR)
                        + "'> (+" + totalBonus + " from upgrades)</span>" : "")
                + "</html>");
        discardBtn.setEnabled(cards > 0);
        discardBtn.setText(cards == 0 ? "Nothing to discard" : "Discard " + cards + " for " + total + " credits");
    }

    private void doDiscard() {
        List<CapturedCreature> sel = new ArrayList<>();
        for (Group g : groups()) sel.addAll(g.discard);
        discardCards(sel);
    }

    /** Confirms and discards the given cards, then refreshes callers + this dialog. */
    private void discardCards(List<CapturedCreature> cards) {
        if (cards.isEmpty()) return;
        long credits = cards.stream().mapToLong(dataService::discardValue).sum();
        int choice = JOptionPane.showConfirmDialog(this,
                "Discard " + cards.size() + " card" + (cards.size() == 1 ? "" : "s")
                        + " for " + credits + " credits? This cannot be undone.",
                "Confirm discard", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (choice != JOptionPane.YES_OPTION) return;
        dataService.discardCaptures(cards);
        BestiaryPanel.recheckAchievements();   // discard milestones (shiny/Mythic/value tiers)
        if (onDone != null) onDone.run();
        recompute();
    }

    /** Colour used for the shop-upgrade bonus shown in brackets. */
    private static final Color BONUS_COLOR = new Color(120, 210, 120);

    private static String hex(Color c) {
        return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
    }
}

package com.bestiary.ui;

import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class MonsterSummaryCard extends JPanel {

    private static final Color HOVER_BG  = new Color(50, 50, 50);
    private static final Color NORMAL_BG = ColorScheme.DARKER_GRAY_COLOR;

    private static final String[] RARITY_ABBREV = { "Cmn", "Unc", "Rare", "Epic", "Lgd", "Mth" };

    public MonsterSummaryCard(String npcName, List<CapturedCreature> captures,
                               BestiaryCollection collection) {
        // Left border = rarest rarity this NPC has been caught at
        CreatureRarity rarest = captures.stream()
                .map(c -> c.rarity)
                .max(Comparator.comparingInt(Enum::ordinal))
                .orElse(CreatureRarity.COMMON);

        // Count per rarity, rarest first, skipping absent rarities
        Map<CreatureRarity, Integer> countByRarity = new LinkedHashMap<>();
        CreatureRarity[] rarityOrder = {
            CreatureRarity.MYTHIC, CreatureRarity.LEGENDARY, CreatureRarity.EPIC,
            CreatureRarity.RARE,   CreatureRarity.UNCOMMON,  CreatureRarity.COMMON
        };
        for (CreatureRarity r : rarityOrder) {
            int cnt = (int) captures.stream().filter(c -> c.rarity == r).count();
            if (cnt > 0) countByRarity.put(r, cnt);
        }

        int rarityRows = Math.max(1, (int) Math.ceil(countByRarity.size() / 3.0));
        int cardHeight = 32 + rarityRows * 20;

        setBackground(NORMAL_BG);
        setBorder(BorderFactory.createCompoundBorder(
                new MatteBorder(0, 3, 0, 0, rarest.displayColor),
                new EmptyBorder(5, 8, 5, 8)));
        setLayout(new GridLayout(1 + rarityRows, 1, 0, 2));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, cardHeight));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        // Top row: NPC name (centre, compresses) + total caught (right, fixed)
        JPanel topRow = new JPanel(new BorderLayout(4, 0));
        topRow.setOpaque(false);

        JLabel nameLabel = new JLabel(npcName);
        nameLabel.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        nameLabel.setForeground(Color.WHITE);

        JLabel totalLabel = new JLabel(captures.size() + " caught");
        totalLabel.setFont(FontManager.getRunescapeSmallFont());
        totalLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        topRow.add(nameLabel,  BorderLayout.CENTER);
        topRow.add(totalLabel, BorderLayout.EAST);

        // One label per row of up to 3 rarities (rarest first)
        List<Map.Entry<CreatureRarity, Integer>> rarityEntries = new ArrayList<>(countByRarity.entrySet());

        add(topRow);

        for (int i = 0; i < rarityEntries.size(); i += 3) {
            StringBuilder sb = new StringBuilder("<html>");
            for (int j = i; j < Math.min(i + 3, rarityEntries.size()); j++) {
                CreatureRarity r = rarityEntries.get(j).getKey();
                if (j > i) sb.append("&nbsp;&nbsp;");
                sb.append(String.format("<font color='#%02x%02x%02x'>&#9679; %d %s</font>",
                        r.displayColor.getRed(), r.displayColor.getGreen(), r.displayColor.getBlue(),
                        rarityEntries.get(j).getValue(), RARITY_ABBREV[r.ordinal()]));
            }
            sb.append("</html>");
            JLabel rowLabel = new JLabel(sb.toString());
            rowLabel.setFont(FontManager.getRunescapeSmallFont());
            add(rowLabel);
        }

        addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { setBackground(HOVER_BG); }
            @Override public void mouseExited(MouseEvent e)  { setBackground(NORMAL_BG); }
            @Override public void mouseClicked(MouseEvent e) {
                AlbumDialog.requestOpenDetail(captures.get(0).npcName);
            }
        });
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.service.BestiaryDataService;
import com.bestiary.service.CaptureService;
import com.bestiary.util.OddsCalculator;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * MODELESS reroll confirmation: shows the card's current stats + Power Level breakdown
 * (via {@link OddsBreakdownPanel}) so the player can judge whether a reroll is worth it,
 * then Reroll / Cancel. Non-blocking.
 */
public class RerollConfirmDialog extends JDialog {

    private static RerollConfirmDialog current;

    public static void open(Window owner, CapturedCreature card, long cost, int currentLevel,
                            double shinyBonus, double rarityBonus, Runnable onReroll) {
        if (current != null && current.isShowing()) current.dispose();
        current = new RerollConfirmDialog(owner, card, cost, currentLevel, shinyBonus, rarityBonus, onReroll);
        current.setVisible(true);
    }

    private RerollConfirmDialog(Window owner, CapturedCreature card, long cost, int currentLevel,
                               double shinyBonus, double rarityBonus, Runnable onReroll) {
        super(owner, "Reroll card", ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setResizable(false);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(new EmptyBorder(12, 14, 12, 14));

        JLabel title = new JLabel((card.isShiny() ? "✦ " : "") + card.rarity.label + " " + card.npcName);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(card.rarity.displayColor);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(title);
        JLabel sub = new JLabel("Current roll. A reroll re-rolls the stats & shiny at the same rarity.");
        sub.setFont(FontManager.getRunescapeSmallFont());
        sub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        sub.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(sub);

        root.add(Box.createVerticalStrut(8));
        JPanel breakdown = OddsBreakdownPanel.build(OddsCalculator.compute(card));
        breakdown.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(breakdown);

        // Live reroll chances at the player's current level
        root.add(Box.createVerticalStrut(10));
        // Live odds include the passive shop bonuses, since the reroll itself applies them.
        double shinyPct = (CaptureService.shinyChance(currentLevel) + shinyBonus) * 100.0;
        double rankPct  = card.rarity == CreatureRarity.MYTHIC
                ? 0.0 : (BestiaryDataService.RARITY_UP_CHANCE + rarityBonus) * 100.0;
        String shinyBonusStr = shinyBonus > 0 ? String.format(" <font color='#ffd24d'>(+%.1f%%)</font>", shinyBonus * 100.0) : "";
        String rankBonusStr  = rarityBonus > 0 ? String.format(" (+%.0f%%)", rarityBonus * 100.0) : "";
        // A shiny card stays shiny through a reroll, so there's no shiny chance to quote.
        String shinyStr = card.isShiny()
                ? "<font color='#ffd24d'>already shiny ✦ (stays shiny)</font>"
                : String.format("<font color='#78dc78'>shiny %.1f%%</font>%s", shinyPct, shinyBonusStr);
        JLabel chances = new JLabel(String.format("<html>This reroll: %s"
                + " &nbsp;·&nbsp; <font color='#ffd24d'>rank up %s</font> (at level %d)</html>",
                shinyStr, card.rarity == CreatureRarity.MYTHIC ? "n/a (already Mythic)"
                        : String.format("%.0f%%%s", rankPct, rankBonusStr),
                currentLevel));
        chances.setFont(FontManager.getRunescapeSmallFont());
        chances.setForeground(Color.WHITE);
        chances.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(chances);
        JLabel warn = new JLabel("<html><div style='width:300px'><i>Disclaimer: rerolling marks this card as "
                + "rerolled, so it's no longer a raw pull.</i></div></html>");
        warn.setFont(FontManager.getRunescapeSmallFont());
        warn.setForeground(new Color(224, 170, 90));
        warn.setAlignmentX(Component.LEFT_ALIGNMENT);
        warn.setBorder(new EmptyBorder(3, 0, 0, 0));
        root.add(warn);

        root.add(Box.createVerticalStrut(12));
        JButton reroll = new JButton("Reroll: " + cost + " credits");
        reroll.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        reroll.setBackground(new Color(60, 120, 60));
        reroll.setForeground(Color.WHITE);
        reroll.setFocusPainted(false);
        reroll.addActionListener(e -> { dispose(); onReroll.run(); });
        JButton cancel = new JButton("Cancel");
        cancel.setFont(FontManager.getRunescapeSmallFont());
        cancel.setFocusPainted(false);
        cancel.addActionListener(e -> dispose());
        JPanel btns = new JPanel(new GridLayout(1, 2, 8, 0));
        btns.setOpaque(false);
        btns.setAlignmentX(Component.LEFT_ALIGNMENT);
        btns.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        btns.add(reroll);
        btns.add(cancel);
        root.add(btns);

        setContentPane(new JScrollPane(root,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER));
        pack();
        setLocationRelativeTo(owner);
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.util.OddsCalculator;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;

/**
 * The "What were the odds?" breakdown for a single capture, as a reusable, width-tracking
 * content panel: the roll chain (catch/rarity/shiny → per-capture/per-kill), the stat roll
 * bands, and the Power Level maths with an average-roll comparison. Embedded both by the
 * standalone {@link OddsDialog} and the {@link CardDataDialog} "Odds" tab.
 */
public class OddsView extends JPanel implements Scrollable {

    private final OddsCalculator.Result r;
    private final CapturedCreature capture;
    private final Font body;
    private final Font bodyBold;

    public OddsView(CapturedCreature capture) {
        this.capture = capture;
        this.r = OddsCalculator.compute(capture);
        float base = FontManager.getRunescapeSmallFont().getSize2D();
        this.body     = FontManager.getRunescapeSmallFont().deriveFont(base + 1f);
        this.bodyBold = body.deriveFont(Font.BOLD);

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(12, 14, 12, 14));
        build();
    }

    private void build() {
        // Title row — name + rarity on the left, REROLLED flag pinned top-right (if applicable)
        boolean rerolled = capture.rerolledBy != null && !capture.rerolledBy.isEmpty();
        Box titleRow = Box.createHorizontalBox();
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel title = new JLabel(capture.npcName + "  ·  " + r.rarity.label + (r.shiny ? "  ✦ SHINY" : ""));
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(r.rarity.displayColor);
        titleRow.add(title);
        titleRow.add(Box.createHorizontalGlue());
        if (rerolled) {
            titleRow.add(rerolledBadge());
        }
        add(titleRow);
        JLabel sub = new JLabel("Captured at Bestiary level " + r.level + "  ·  " + r.difficulty.label + " tier");
        sub.setFont(body);
        sub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        sub.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(sub);

        if (rerolled) {
            add(paragraph("This card was rerolled, so the odds below describe a raw pull at this rarity, "
                    + "not how this particular card was produced.", new Color(150, 120, 200)));
        }

        add(Box.createVerticalStrut(8));

        // Roll chain
        add(sectionHeader("The roll chain"));
        add(kvRow("Catch (gate)", body, Color.WHITE,
                OddsCalculator.pct(r.catchChance) + "  (" + OddsCalculator.oneIn(r.catchChance) + ")"));
        add(kvRow("This rarity", body, r.rarity.displayColor,
                OddsCalculator.pct(r.rarityChance) + "  (" + OddsCalculator.oneIn(r.rarityChance) + ")"));
        if (r.shiny) {
            String bonusNote = r.shinyBonus > 0 ? "  (+" + OddsCalculator.pct(r.shinyBonus) + ")" : "";
            add(kvRow("Shiny", body, new Color(255, 215, 0),
                    OddsCalculator.pct(r.shinyChance) + bonusNote
                            + "  (" + OddsCalculator.oneIn(r.shinyChance) + ")"));
        }
        add(Box.createVerticalStrut(4));
        add(separator());
        add(Box.createVerticalStrut(4));
        Box perCap = kvRow("Per capture (" + (r.shiny ? "Rarity × Shiny" : "Rarity chance") + ")",
                bodyBold, Color.WHITE, OddsCalculator.oneIn(r.perCapture));
        styleValue(perCap, new Color(120, 200, 120));
        add(perCap);
        Box perKill = kvRow("Per kill (Catch chance × Rarity chance" + (r.shiny ? " × Shiny" : "") + ")",
                bodyBold, Color.WHITE, OddsCalculator.oneIn(r.perKill));
        styleValue(perKill, Color.WHITE);
        add(perKill);
        add(paragraph("<i>Per capture = how often a capture is this rarity at level " + r.level
                + " (high levels make rarities much more common). Per kill folds in the catch chance. "
                + "Stat rolls are flavour; they don't affect these odds.</i>"));

        add(Box.createVerticalStrut(10));

        // Stats
        add(sectionHeader(r.shiny
                ? "Stats: shiny roll bands (above " + r.rarity.label + ")"
                : "Stats: " + r.rarity.label + " roll bands"));
        add(statsTable());
        add(paragraph("Higher rarities lift the roll toward 99 (bigger lift for low stats); "
                + "lower rarities can dip below the base (never under 1). Bands overlap, so a lucky Rare "
                + "can beat an unlucky Epic. Prayer and Agility roll the same way at half scale. "
                + "<font color='#a0a0a0'>Example, base&nbsp;50: Common&nbsp;37–50, Uncommon&nbsp;41–52, "
                + "Rare&nbsp;45–53, Epic&nbsp;50–61, Legendary&nbsp;56–74, Mythic&nbsp;70–90.</font>"));

        add(Box.createVerticalStrut(10));

        // Power Level
        int sevenStats = r.statSum;
        int statAvg = Math.round(sevenStats / 7f);
        Color nearWhite = new Color(235, 235, 235);
        add(sectionHeader("Power Level"));
        add(styleValue(kvRow("7 stats total", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(sevenStats)), nearWhite));
        add(styleValue(kvRow("Stat average  (" + sevenStats + " ÷ 7)", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(statAvg)), nearWhite));
        add(styleValue(kvRow("Hitpoints (factual)  ÷ 6", body, new Color(120, 200, 120),
                "+" + Math.round(r.hp / 6f)), nearWhite));
        add(styleValue(kvRow("Combat level (factual)  ÷ 6", body, new Color(120, 200, 120),
                "+" + Math.round(r.combatLevel / 6f)), nearWhite));
        add(styleValue(kvRow("= Power Level  (" + sevenStats + " ÷ 7) + (" + r.hp + " ÷ 6) + (" + r.combatLevel + " ÷ 6)",
                body, Color.WHITE, String.valueOf(r.powerLevel)), new Color(120, 200, 120)));

        add(Box.createVerticalStrut(4));
        add(separator());
        add(Box.createVerticalStrut(4));

        add(styleValue(kvRow("Average " + r.rarity.label + " roll", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(r.avgPowerLevel)), nearWhite));
        int delta = r.powerLevel - r.avgPowerLevel;
        String deltaStr = delta > 0 ? "+" + delta + " above avg" : delta < 0 ? delta + " below avg" : "bang on avg";
        Color deltaCol = delta > 0 ? new Color(120, 200, 120) : delta < 0 ? new Color(224, 112, 112) : new Color(176, 176, 176);
        add(styleValue(kvRow("This card vs average", body, Color.WHITE, deltaStr), deltaCol));

        add(styleValue(kvRow("Average " + r.rarity.label + " shiny roll", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(r.avgShinyPowerLevel)), nearWhite));
        int dShiny = r.powerLevel - r.avgShinyPowerLevel;
        String dShinyStr = dShiny > 0 ? "+" + dShiny + " above avg shiny" : dShiny < 0 ? dShiny + " below avg shiny" : "bang on avg shiny";
        Color dShinyCol = dShiny > 0 ? new Color(120, 200, 120) : dShiny < 0 ? new Color(224, 112, 112) : new Color(176, 176, 176);
        add(styleValue(kvRow("This card vs average shiny", body, Color.WHITE, dShinyStr), dShinyCol));

        add(paragraph("Power Level = the 7-stat average + the monster's HP and combat level, each at "
                + "1/6 weight. HP and combat level aren't on the 1–99 scale, so they're added "
                + "separately. <font color='#a0a0a0'>Negligible for a weak creature (stats decide), but "
                + "dominant for a boss (1200&nbsp;HP adds ~200, a 1400 combat level ~233).</font>"));
    }

