import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * Reusable stats table + Power Level breakdown (with average-roll comparison) for a
 * capture, without the roll-chain odds or explainer text. Used by the reroll-confirm
 * screen to give context before spending credits.
 */
final class OddsBreakdownPanel {

    private OddsBreakdownPanel() {}

    static JPanel build(OddsCalculator.Result r) {
        float base = FontManager.getRunescapeSmallFont().getSize2D();
        Font body     = FontManager.getRunescapeSmallFont().deriveFont(base + 1f);
        Font bodyBold = body.deriveFont(Font.BOLD);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setOpaque(false);

        // Stats
        root.add(header(r.shiny
                ? "Stats: shiny roll bands (above " + r.rarity.label + ")"
                : "Stats: " + r.rarity.label + " roll bands", bodyBold));
        root.add(statsTable(r, body, bodyBold));

        root.add(Box.createVerticalStrut(10));

        // Power Level: 7-stat average + HP at 1/6 weight + combat level at 1/6 weight (Prayer is the 7th stat)
        int sevenStats = r.statSum;
        int statAvg = Math.round(sevenStats / 7f);
        Color nearWhite = new Color(235, 235, 235);
        root.add(header("Power Level", bodyBold));
        root.add(value(kvRow("Stat average  (" + sevenStats + " ÷ 7)", body, ColorScheme.LIGHT_GRAY_COLOR, String.valueOf(statAvg)), nearWhite));
        root.add(value(kvRow("Hitpoints (factual)  ÷ 6", body, new Color(120, 200, 120), "+" + Math.round(r.hp / 6f)), nearWhite));
        root.add(value(kvRow("Combat level (factual)  ÷ 6", body, new Color(120, 200, 120), "+" + Math.round(r.combatLevel / 6f)), nearWhite));
        root.add(value(kvRow("= Power Level  (" + sevenStats + " ÷ 7) + (" + r.hp + " ÷ 6) + (" + r.combatLevel + " ÷ 6)", body, Color.WHITE,
                String.valueOf(r.powerLevel)), new Color(120, 200, 120)));

        root.add(Box.createVerticalStrut(4));
        root.add(separator());
        root.add(Box.createVerticalStrut(4));

        root.add(value(kvRow("Average " + r.rarity.label + " roll", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(r.avgPowerLevel)), nearWhite));
        int delta = r.powerLevel - r.avgPowerLevel;
        String deltaStr = delta > 0 ? "+" + delta + " above avg" : delta < 0 ? delta + " below avg" : "bang on avg";
        Color deltaCol = delta > 0 ? new Color(120, 200, 120) : delta < 0 ? new Color(224, 112, 112) : new Color(176, 176, 176);
        root.add(value(kvRow("This card vs average", body, Color.WHITE, deltaStr), deltaCol));

        root.add(value(kvRow("Average " + r.rarity.label + " shiny roll", body, ColorScheme.LIGHT_GRAY_COLOR,
                String.valueOf(r.avgShinyPowerLevel)), nearWhite));
        int dShiny = r.powerLevel - r.avgShinyPowerLevel;
        String dShinyStr = dShiny > 0 ? "+" + dShiny + " above avg shiny" : dShiny < 0 ? dShiny + " below avg shiny" : "bang on avg shiny";
        Color dShinyCol = dShiny > 0 ? new Color(120, 200, 120) : dShiny < 0 ? new Color(224, 112, 112) : new Color(176, 176, 176);
        root.add(value(kvRow("This card vs average shiny", body, Color.WHITE, dShinyStr), dShinyCol));

        return root;
    }

    private static JLabel header(String text, Font bold) {
        JLabel l = new JLabel(text.toUpperCase());
        l.setFont(bold);
        l.setForeground(new Color(255, 152, 31));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        l.setBorder(new EmptyBorder(0, 0, 3, 0));
        return l;
    }

    private static JPanel statsTable(OddsCalculator.Result r, Font body, Font bodyBold) {
        JPanel t = new JPanel(new GridBagLayout());
        t.setOpaque(false);
        t.setAlignmentX(Component.LEFT_ALIGNMENT);
        GridBagConstraints g = new GridBagConstraints();
        g.insets = new Insets(1, 0, 1, 14);
        String[] heads = {"Stat", "Base", "Roll", "Band", "Quality"};
        for (int c = 0; c < heads.length; c++) {
            g.gridx = c; g.gridy = 0;
            g.anchor = (c == 1 || c == 2) ? GridBagConstraints.EAST : GridBagConstraints.WEST;
            t.add(cell(heads[c], bodyBold, new Color(140, 140, 140)), g);
        }
        int row = 1;
        for (OddsCalculator.StatOdds s : r.stats) {
            g.gridy = row++;
            g.gridx = 0; g.anchor = GridBagConstraints.WEST;
            t.add(cell(s.name, body, new Color(210, 210, 210)), g);
            g.gridx = 1; g.anchor = GridBagConstraints.EAST;
            t.add(cell(String.valueOf(s.base), body, new Color(150, 150, 150)), g);
            g.gridx = 2; g.anchor = GridBagConstraints.EAST;
            t.add(cell(String.valueOf(s.value), bodyBold, Color.WHITE), g);
            g.gridx = 3; g.anchor = GridBagConstraints.WEST;
            t.add(cell(s.lo + "–" + s.hi, body, ColorScheme.LIGHT_GRAY_COLOR), g);
            g.gridx = 4; g.anchor = GridBagConstraints.WEST;
            t.add(rollTagCell(s.value, s.lo, s.hi, body), g);
        }
        t.setMaximumSize(new Dimension(Integer.MAX_VALUE, t.getPreferredSize().height));
        return t;
    }

    private static JLabel cell(String text, Font font, Color colour) {
        JLabel l = new JLabel(text);
        l.setFont(font);
        l.setForeground(colour);
        return l;
    }

    private static JLabel rollTagCell(int value, int lo, int hi, Font body) {
        String label; Color colour;
        if (hi <= lo) {
            label = value >= 99 ? "MAX roll" : "fixed";
            colour = value >= 99 ? new Color(122, 214, 122) : new Color(144, 144, 144);
        } else {
            double f = (value - lo) / (double) (hi - lo);
            if (value >= hi)    { label = "MAX roll";  colour = new Color(122, 214, 122); }
            else if (f >= 0.67) { label = "high roll"; colour = new Color(143, 208, 143); }
            else if (f <= 0.33) { label = value <= lo ? "MIN roll" : "low roll"; colour = new Color(224, 112, 112); }
            else                { label = "mid roll";  colour = new Color(176, 176, 176); }
        }
        return cell(label, body, colour);
    }

    private static JPanel separator() {
        JPanel s = new JPanel();
        s.setBackground(new Color(70, 70, 70));
        s.setAlignmentX(Component.LEFT_ALIGNMENT);
        s.setPreferredSize(new Dimension(10, 1));
        s.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        return s;
    }

    private static Box kvRow(String left, Font leftFont, Color leftColor, String right) {
        Box row = Box.createHorizontalBox();
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, leftFont.getSize() + 8));
        JLabel l = new JLabel(left);
        l.setFont(leftFont);
        l.setForeground(leftColor);
        JLabel rr = new JLabel(right);
        rr.setFont(leftFont.deriveFont(Font.PLAIN));
        rr.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        row.add(l);
        row.add(Box.createHorizontalStrut(14));
        row.add(Box.createHorizontalGlue());
        row.add(rr);
        return row;
    }

    private static Box value(Box row, Color colour) {
        ((JLabel) row.getComponent(row.getComponentCount() - 1)).setForeground(colour);
        return row;
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.service.BestiaryDataService;
import com.bestiary.service.BestiaryStore;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * MODELESS bulk-transfer screen (#50, "Mockup B"): tick the cards to send, pick one of your other
 * accounts as the target, and move them there. The card leaves this collection and is deposited in
 * the target account's file (works even if that account is offline). Mirrors {@link DiscardDialog}:
 * owned by the album window, so it is auto-disposed when the album closes.
 */
public class TransferDialog extends JDialog {

    private static TransferDialog current;

    private final BestiaryDataService dataService;
    private final Runnable onDone;

    private final JComboBox<BestiaryStore.AccountRef> targetCombo = new JComboBox<>();
    private final JPanel cardsPanel = new JPanel();
    private final List<CardRow> rows = new ArrayList<>();
    private JTextField searchField;
    private JLabel emptyNote;
    private JButton sendBtn;

    /** A checkbox bound to the capture it would transfer. */
    private static final class CardRow {
        final JCheckBox box;
        final CapturedCreature card;
        CardRow(JCheckBox box, CapturedCreature card) { this.box = box; this.card = card; }
    }

    public static void open(Window owner, BestiaryDataService dataService, Runnable onDone) {
        if (current != null && current.isShowing()) current.dispose();
        current = new TransferDialog(owner, dataService, onDone);
        current.setVisible(true);
    }

    /** Rebuilds the open transfer dialog (e.g. after cards changed elsewhere). */
    public static void refreshOpen() {
        if (current != null && current.isShowing()) current.rebuild();
    }

    private TransferDialog(Window owner, BestiaryDataService dataService, Runnable onDone) {
        super(owner, "Transfer cards", ModalityType.MODELESS);
        this.dataService = dataService;
        this.onDone = onDone;
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(new EmptyBorder(12, 14, 12, 14));

        JLabel title = new JLabel("Send cards to another account");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(title);

        JLabel help = new JLabel("<html><div style='width:320px'>Tick the cards to send and choose one "
                + "of your other accounts. They leave this collection and appear in the target account "
                + "(favourites, nicknames and provenance travel with them).</div></html>");
        help.setFont(FontManager.getRunescapeSmallFont());
        help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        help.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(help);

        root.add(Box.createVerticalStrut(8));
        root.add(header("SEND TO"));
        targetCombo.setFont(FontManager.getRunescapeSmallFont());
        targetCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        targetCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
        targetCombo.setRenderer(new AccountRenderer());
        targetCombo.addActionListener(e -> updateSendButton());
        root.add(targetCombo);

        emptyNote = new JLabel("No other accounts found on this machine. Log into another character first.");
        emptyNote.setFont(FontManager.getRunescapeSmallFont());
        emptyNote.setForeground(new Color(210, 160, 90));
        emptyNote.setAlignmentX(Component.LEFT_ALIGNMENT);
        emptyNote.setBorder(new EmptyBorder(4, 1, 0, 0));
        emptyNote.setVisible(false);
        root.add(emptyNote);

        root.add(Box.createVerticalStrut(8));
        JPanel cardHdr = new JPanel(new BorderLayout());
        cardHdr.setOpaque(false);
        cardHdr.setAlignmentX(Component.LEFT_ALIGNMENT);
        cardHdr.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        cardHdr.add(header("CARDS TO SEND"), BorderLayout.WEST);
        JPanel selRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        selRow.setOpaque(false);
        selRow.add(smallBtn("All",  () -> setAllChecked(true)));
        selRow.add(smallBtn("None", () -> setAllChecked(false)));
        cardHdr.add(selRow, BorderLayout.EAST);
        root.add(cardHdr);

        // Search filter — the card list can get very long late game.
        searchField = new JTextField();
        searchField.setFont(FontManager.getRunescapeSmallFont());
        searchField.setAlignmentX(Component.LEFT_ALIGNMENT);
        searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        searchField.setToolTipText("Filter cards by monster name");
        searchField.putClientProperty("JTextField.placeholderText", "Search cards…");
        searchField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override public void insertUpdate(javax.swing.event.DocumentEvent e)  { applyFilter(); }
            @Override public void removeUpdate(javax.swing.event.DocumentEvent e)  { applyFilter(); }
            @Override public void changedUpdate(javax.swing.event.DocumentEvent e) { applyFilter(); }
        });
        root.add(searchField);
        root.add(Box.createVerticalStrut(4));

        cardsPanel.setLayout(new BoxLayout(cardsPanel, BoxLayout.Y_AXIS));
        cardsPanel.setOpaque(false);
        JScrollPane scroll = new JScrollPane(cardsPanel,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createLineBorder(new Color(60, 60, 60)));
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setPreferredSize(new Dimension(360, 240));
        scroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        scroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 240));
        root.add(scroll);

        root.add(Box.createVerticalStrut(8));
        sendBtn = new JButton("Send");
        sendBtn.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        sendBtn.setBackground(new Color(60, 110, 150));
        sendBtn.setForeground(Color.WHITE);
        sendBtn.setFocusPainted(false);
        sendBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
        sendBtn.addActionListener(e -> doSend());
        root.add(sendBtn);

        setContentPane(root);
        rebuild();
        pack();
        setLocationRelativeTo(owner);
    }

    private JLabel header(String text) {
        JLabel l = new JLabel(text);
        l.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        l.setForeground(new Color(255, 152, 31));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        l.setBorder(new EmptyBorder(0, 0, 3, 0));
        return l;
    }

    private JButton smallBtn(String text, Runnable action) {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setMargin(new Insets(0, 6, 0, 6));
        b.setFocusPainted(false);
        b.addActionListener(e -> action.run());
        return b;
    }

    /** Rebuilds the target list and the card checkboxes from the current collection. */
    private void rebuild() {
        // Target accounts
        BestiaryStore.AccountRef previouslySelected = (BestiaryStore.AccountRef) targetCombo.getSelectedItem();
        targetCombo.removeAllItems();
        List<BestiaryStore.AccountRef> others = dataService.listOtherAccounts();
        for (BestiaryStore.AccountRef a : others) targetCombo.addItem(a);
        if (previouslySelected != null) {
            for (BestiaryStore.AccountRef a : others) {
                if (a.hash == previouslySelected.hash) { targetCombo.setSelectedItem(a); break; }
            }
        }
        boolean haveTargets = !others.isEmpty();
        targetCombo.setVisible(haveTargets);
        emptyNote.setVisible(!haveTargets);

        // Card checkboxes — rarity desc, then Power Level desc
        cardsPanel.removeAll();
        rows.clear();
        List<CapturedCreature> cards = new ArrayList<>(dataService.getCollection().creatures);
        cards.sort((a, b) -> {
            int r = Integer.compare(b.rarity.ordinal(), a.rarity.ordinal());
            return r != 0 ? r : Integer.compare(b.powerLevel(), a.powerLevel());
        });
        for (CapturedCreature c : cards) {
            String star = c.favourite ? "★ " : "";
            String shiny = c.isShiny() ? "✦ " : "";
            JCheckBox cb = new JCheckBox(shiny + star + c.rarity.label + "  " + c.npcName
                    + "  · PWR " + c.powerLevel());
            cb.setOpaque(false);
            cb.setForeground(c.rarity.displayColor);
            cb.setFont(FontManager.getRunescapeSmallFont());
            cb.setAlignmentX(Component.LEFT_ALIGNMENT);
            cb.addActionListener(e -> updateSendButton());
            cardsPanel.add(cb);
            rows.add(new CardRow(cb, c));
        }
        if (rows.isEmpty()) {
            JLabel none = new JLabel("This collection has no cards to send.");
            none.setFont(FontManager.getRunescapeSmallFont());
            none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            none.setBorder(new EmptyBorder(6, 4, 0, 0));
            cardsPanel.add(none);
        }
        applyFilter();
        cardsPanel.revalidate();
        cardsPanel.repaint();
        updateSendButton();
    }

    /** Shows only card rows whose monster name matches the search box (case-insensitive). */
    private void applyFilter() {
        String q = searchField == null ? "" : searchField.getText().trim().toLowerCase(java.util.Locale.ROOT);
        for (CardRow r : rows) {
            boolean match = q.isEmpty() || r.card.npcName.toLowerCase(java.util.Locale.ROOT).contains(q);
            r.box.setVisible(match);
        }
        cardsPanel.revalidate();
        cardsPanel.repaint();
    }

    private void setAllChecked(boolean checked) {
        // Only affects the currently-visible (filtered) rows.
        for (CardRow r : rows) if (r.box.isVisible()) r.box.setSelected(checked);
        updateSendButton();
    }

    private List<CapturedCreature> selected() {
        List<CapturedCreature> out = new ArrayList<>();
        for (CardRow r : rows) if (r.box.isSelected()) out.add(r.card);
        return out;
    }

    private void updateSendButton() {
        int n = selected().size();
        BestiaryStore.AccountRef target = (BestiaryStore.AccountRef) targetCombo.getSelectedItem();
        boolean canSend = n > 0 && target != null;
        sendBtn.setEnabled(canSend);
        sendBtn.setText(n == 0 ? "Select cards to send"
                : "Send " + n + " → " + (target != null ? accountName(target) : "…"));
    }

    private void doSend() {
        List<CapturedCreature> sel = selected();
        BestiaryStore.AccountRef target = (BestiaryStore.AccountRef) targetCombo.getSelectedItem();
        if (sel.isEmpty() || target == null) return;
        String name = accountName(target);
        int choice = JOptionPane.showConfirmDialog(this,
                "Send " + sel.size() + " card" + (sel.size() == 1 ? "" : "s") + " to " + name
                        + "?\nThey will leave this collection.",
                "Confirm transfer", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
        if (choice != JOptionPane.YES_OPTION) return;

        int moved = dataService.transferCards(sel, target.hash, target.rsn);
        if (moved == 0) {
            JOptionPane.showMessageDialog(this,
                    "Could not transfer the cards (target account file could not be written).",
                    "Transfer failed", JOptionPane.WARNING_MESSAGE);
            return;
        }
        if (onDone != null) onDone.run();   // refresh panel + album
        rebuild();
    }

    private static String accountName(BestiaryStore.AccountRef a) {
        return a.rsn != null && !a.rsn.isEmpty() ? a.rsn : "Account " + a.hash;
    }

    /** Renders an account row as its RSN (fallback to the hash). */
    private static final class AccountRenderer extends DefaultListCellRenderer {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                      boolean isSelected, boolean cellHasFocus) {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof BestiaryStore.AccountRef) {
                setText(accountName((BestiaryStore.AccountRef) value));
            }
            return this;
        }
    }
}

package com.bestiary.ui;

import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.MonsterRoster;
import com.bestiary.service.WikiImageService;
import com.bestiary.util.CardId;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Reusable export view for a single capture: a 2× scaled card + banner preview with
 * Copy Image / Save PNG buttons and a right-click menu (copy / favourite / album cover /
 * rename / save). Embedded as the first tab of {@link CardDataDialog}; the shared image
 * service and collection are pulled from {@link CardExportDialog}'s static wiring.
 */
public class CardExportPanel extends JPanel {

    // Preview scale is < 2 so the card + banner + Copy/Save buttons all fit the card window
    // without scrolling. The exported PNG/clipboard image still renders at 3× (see renderCard).
    private static final double PREVIEW_SCALE = 1.7;
    private static final int BOTTOM_H = 42;

    private final AlbumCard card;
    private final String cardId;
    private final String owner;
    private final String npcName;
    private final int rerollCount;

    public CardExportPanel(CapturedCreature capture) {
        WikiImageService imageService = CardExportDialog.sharedImageService();
        java.util.function.Supplier<BestiaryCollection> collectionSupplier = CardExportDialog.collectionSupplier();
        int dexNumber = MonsterRoster.getDexNumber(capture.npcName);

        String capturedBy = capture.playerName != null && !capture.playerName.isEmpty()
                ? capture.playerName : "Unknown";
        this.npcName = capture.npcName;
        this.card    = new AlbumCard(dexNumber, capture.npcName, List.of(capture),
                collectionSupplier.get(), imageService);
        this.card.setShowQuality(true);
        this.cardId = CardId.encode(dexNumber, capture);
        this.owner  = capturedBy;
        this.rerollCount = capture.rerollCount();

        // Re-query the live collection at click time to avoid a stale snapshot.
        card.setClickOverride(() -> {
            BestiaryCollection live = collectionSupplier.get();
            List<CapturedCreature> fresh = live.creatures.stream()
                    .filter(c -> c.npcName.equals(capture.npcName))
                    .collect(Collectors.toList());
            List<CapturedCreature> list = fresh.isEmpty() ? List.of(capture) : fresh;
            new CreatureDetailDialog(window(), list, live, "By Rarity", capture.rarity).setVisible(true);
        });

        JPanel previewPanel = new JPanel() {
            { setPreferredSize(new Dimension((int) (AlbumCard.CARD_W * PREVIEW_SCALE),
                                             (int) ((AlbumCard.CARD_H + BOTTOM_H) * PREVIEW_SCALE)));
              setOpaque(false); }
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                g2.scale(PREVIEW_SCALE, PREVIEW_SCALE);
                card.setSize(AlbumCard.CARD_W, AlbumCard.CARD_H);
                card.print(g2);
                g2.setColor(new Color(12, 12, 12));
                g2.fillRect(0, AlbumCard.CARD_H, AlbumCard.CARD_W, BOTTOM_H);
                String ownerStr = "Captured by " + owner;
                CardExportDialog.drawBanner(g2, 0, AlbumCard.CARD_H, AlbumCard.CARD_W, BOTTOM_H,
                        cardId, ownerStr, capture.rerollCount());
                g2.dispose();
            }
        };
        imageService.requestImage(npcName, previewPanel::repaint);
        card.setShimmerCallback(previewPanel::repaint);
        previewPanel.setCursor(Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR));
        previewPanel.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override public void mouseEntered(java.awt.event.MouseEvent e) { card.hoverStart(); }
            @Override public void mouseExited(java.awt.event.MouseEvent  e) { card.hoverStop();  }
            @Override public void mousePressed(java.awt.event.MouseEvent e)  { popup(e); }
            @Override public void mouseReleased(java.awt.event.MouseEvent e) { popup(e); }
            private void popup(java.awt.event.MouseEvent e) {
                if (!e.isPopupTrigger() || BestiaryPanel.isReadOnly()) return;   // look-only while viewing (#48)
                BestiaryCollection live = collectionSupplier.get();
                Runnable onMutate = CardExportDialog.onMutate();
                JPopupMenu menu = new JPopupMenu();

                JMenuItem copy = new JMenuItem("Copy Card");
                copy.addActionListener(ev -> copyToClipboard());
                menu.add(copy);
                menu.addSeparator();

                JMenuItem fav = new JMenuItem(capture.favourite ? "✩ Remove Favourite" : "★ Favourite");
                fav.addActionListener(ev -> {
                    if (!capture.favourite && live.countFavourites() >= 20) return;
                    capture.favourite = !capture.favourite;
                    previewPanel.repaint();
                    if (onMutate != null) onMutate.run();
                });
                menu.add(fav);

                JMenuItem cover = new JMenuItem(capture.albumCover ? "Remove album cover" : "Set as album cover");
                cover.addActionListener(ev -> {
                    if (capture.albumCover) capture.albumCover = false;
                    else live.setAlbumCover(capture);
                    previewPanel.repaint();
                    if (onMutate != null) onMutate.run();
                });
                menu.add(cover);
                menu.addSeparator();

                String nickLabel = (capture.nickname != null && !capture.nickname.isEmpty())
                        ? "Rename…" : "Name capture…";
                JMenuItem name = new JMenuItem(nickLabel);
                name.addActionListener(ev -> AlbumCard.openNicknameDialog(previewPanel, capture, () -> {
                    previewPanel.repaint();
                    if (onMutate != null) onMutate.run();
                }));
                menu.add(name);

                JMenuItem save = new JMenuItem("Save PNG…");
                save.addActionListener(ev -> savePng());
                menu.add(save);

                menu.show(previewPanel, e.getX(), e.getY());
            }
        });

        JButton copyBtn = new JButton("Copy Image");
        copyBtn.setFont(FontManager.getRunescapeSmallFont());
        copyBtn.setBackground(new Color(255, 153, 0));
        copyBtn.setForeground(Color.BLACK);
        copyBtn.setFocusPainted(false);
        copyBtn.addActionListener(e -> { copyToClipboard(); flash(copyBtn, "✓ Copied!"); });

        JButton saveBtn = new JButton("Save PNG…");
        saveBtn.setFont(FontManager.getRunescapeSmallFont());
        saveBtn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        saveBtn.setForeground(Color.WHITE);
        saveBtn.setFocusPainted(false);
        saveBtn.addActionListener(e -> { if (savePng()) flash(saveBtn, "✓ Saved!"); });

        JPanel btnRow = new JPanel(new GridLayout(1, 2, 6, 0));
        btnRow.setOpaque(false);
        btnRow.setBorder(new EmptyBorder(8, 0, 0, 0));
        btnRow.add(copyBtn);
        btnRow.add(saveBtn);

        // Preview centred in a viewport-width holder so it stays centred (and scrolls if the
        // window is short); the Copy/Save row is pinned to the bottom of the tab.
        JPanel centre = new JPanel(new GridBagLayout()) {
            @Override public Dimension getPreferredSize() {
                Dimension d = super.getPreferredSize();
                if (getParent() != null) d.width = getParent().getWidth();
                return d;
            }
        };
        centre.setOpaque(false);
        centre.add(previewPanel, new GridBagConstraints());
        JScrollPane previewScroll = new JScrollPane(centre,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        previewScroll.setBorder(null);
        previewScroll.setOpaque(false);
        previewScroll.getViewport().setOpaque(false);
        previewScroll.getVerticalScrollBar().setUnitIncrement(16);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 12, 10, 12));
        add(previewScroll, BorderLayout.CENTER);
        add(btnRow, BorderLayout.SOUTH);
    }

    /** Free the card's shimmer registration when this tab/panel is torn down. */
    @Override
    public void removeNotify() {
        super.removeNotify();
        card.removeNotify();
    }

    private Window window() {
        return SwingUtilities.getWindowAncestor(this);
    }

    private BufferedImage renderCard() {
        int scale   = 3;
        card.setSize(AlbumCard.CARD_W, AlbumCard.CARD_H);
        BufferedImage img = new BufferedImage(AlbumCard.CARD_W * scale,
                (AlbumCard.CARD_H + BOTTOM_H) * scale, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.scale(scale, scale);
        card.print(g2);
        g2.setColor(new Color(12, 12, 12));
        g2.fillRect(0, AlbumCard.CARD_H, AlbumCard.CARD_W, BOTTOM_H);
        String ownerStr = "Captured by " + owner;
        CardExportDialog.drawBanner(g2, 0, AlbumCard.CARD_H, AlbumCard.CARD_W, BOTTOM_H,
                cardId, ownerStr, rerollCount);
        g2.dispose();
        return img;
    }

    private void copyToClipboard() {
        BufferedImage img = renderCard();
        Transferable t = new Transferable() {
            @Override public DataFlavor[] getTransferDataFlavors() { return new DataFlavor[]{DataFlavor.imageFlavor}; }
            @Override public boolean isDataFlavorSupported(DataFlavor f) { return f.equals(DataFlavor.imageFlavor); }
            @Override public Object getTransferData(DataFlavor f) throws UnsupportedFlavorException {
                if (!f.equals(DataFlavor.imageFlavor)) throw new UnsupportedFlavorException(f);
                return img;
            }
        };
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(t, null);
        java.util.function.Consumer<String> onCopy = CardExportDialog.onCopyAction();
        if (onCopy != null) {
            onCopy.accept("Card exported to clipboard for " + npcName + ", ID: " + cardId);
        }
    }

    private boolean savePng() {
        JFileChooser chooser = new JFileChooser();
        String fileName = "bestiary_" + npcName.toLowerCase().replace(" ", "_") + ".png";
        chooser.setSelectedFile(new File(System.getProperty("user.home"), fileName));
        if (chooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
            try {
                ImageIO.write(renderCard(), "PNG", chooser.getSelectedFile());
                return true;
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(this, "Failed to save: " + ex.getMessage(),
                        "Error", JOptionPane.ERROR_MESSAGE);
            }
        }
        return false;
    }

    private static void flash(JButton btn, String label) {
        String orig = btn.getText();
        btn.setText(label);
        btn.setEnabled(false);
        new javax.swing.Timer(1500, e -> {
            btn.setText(orig);
            btn.setEnabled(true);
            ((javax.swing.Timer) e.getSource()).stop();
        }).start();
    }
}

