/**
 * MODELESS per-card "Data" panel (right-click → Card Info…). Consolidates everything known about a
 * single capture into tabs: Overview (metadata), Odds (the "What were the odds?" breakdown via
 * {@link OddsView}), and Reroll history (the card's past states). Room for more tabs later
 * (provenance, capture context, …).
 */
public class CardDataDialog extends JDialog {

    private static CardDataDialog current;
    private static final DateTimeFormatter DATE =
            DateTimeFormatter.ofPattern("d MMM yyyy, HH:mm").withZone(ZoneId.systemDefault());
    private static final DateTimeFormatter DATE_SHORT =
            DateTimeFormatter.ofPattern("d/M/yy").withZone(ZoneId.systemDefault());

    public static final int TAB_EXPORT = 0, TAB_OVERVIEW = 1, TAB_ODDS = 2, TAB_GRAPH = 3, TAB_REROLLS = 4;

    /** Supplies the played account's current Hunter's Bounty flat capture-credit bonus (0 = none). */
    private static java.util.function.LongSupplier captureCreditBonus = () -> 0L;
    public static void setCaptureCreditBonus(java.util.function.LongSupplier s) {
        if (s != null) captureCreditBonus = s;
    }

    /** Current Scholar's Insight capture-XP bonus fraction (e.g. 0.25 = +25%; 0 = none). */
    private static java.util.function.DoubleSupplier captureXpBonus = () -> 0.0;
    public static void setCaptureXpBonus(java.util.function.DoubleSupplier s) {
        if (s != null) captureXpBonus = s;
    }

    /** Current Hunter's Focus flat kill-XP bonus (0 = none). */
    private static java.util.function.LongSupplier killXpFlatBonus = () -> 0L;
    public static void setKillXpFlatBonus(java.util.function.LongSupplier s) {
        if (s != null) killXpFlatBonus = s;
    }

    /** Colour for shop-upgrade bonus amounts shown in brackets. */
    private static final String BONUS_HEX = "#78d278";

    public static void open(Window owner, CapturedCreature capture) {
        open(owner, capture, TAB_EXPORT);
    }

    /** Opens the panel on a specific tab (see the TAB_* constants). */
    public static void open(Window owner, CapturedCreature capture, int tab) {
        if (current != null && current.isShowing()) current.dispose();
        current = new CardDataDialog(owner, capture);
        if (tab >= 0 && tab < current.tabs.getTabCount()) current.tabs.setSelectedIndex(tab);
        current.setVisible(true);
    }

    /** Close any open Card data dialog (called when the collection is reset / Album opens). */
    public static void disposeOpen() {
        if (current != null && current.isDisplayable()) current.dispose();
        current = null;
    }

    private final Font body;
    private final Font bodyBold;
    private final JTabbedPane tabs;
    private final JComponent bottomBar;

    private CardDataDialog(Window owner, CapturedCreature capture) {
        super(owner, "Card data: " + capture.npcName, ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        float base = FontManager.getRunescapeSmallFont().getSize2D();
        this.body     = FontManager.getRunescapeSmallFont().deriveFont(base + 1f);
        this.bodyBold = body.deriveFont(Font.BOLD);

        tabs = new JTabbedPane();
        tabs.setFont(FontManager.getRunescapeSmallFont());
        tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
        tabs.setForeground(Color.WHITE);
        tabs.addTab("Export", buildExportTab(capture));   // primary: card preview + Copy/Save
        tabs.addTab("Overview", scroll(buildOverview(capture)));
        tabs.addTab("Odds", scroll(new OddsView(capture)));
        tabs.addTab("Graph", new RerollGraph(capture));   // percentile + (if rerolled) stat timeline
        tabs.addTab("Rerolls", scroll(buildRerollHistory(capture)));
        bottomBar = buildBottomBar();
        bottomBar.setVisible(false);   // Export is the first/selected tab

        // A tab's scroll pane can open part-scrolled (layout quirk) — force it back to the top.
        // The generic Copy/Save-tab bar only applies to the data tabs; the Export tab has its own.
        tabs.addChangeListener(e -> {
            bottomBar.setVisible(tabs.getSelectedIndex() != TAB_EXPORT);
            SwingUtilities.invokeLater(() -> {
                Component tc = tabs.getSelectedComponent();
                if (tc instanceof JScrollPane) ((JScrollPane) tc).getViewport().setViewPosition(new Point(0, 0));
            });
        });

        JPanel root = new JPanel(new BorderLayout());
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.add(tabs, BorderLayout.CENTER);
        root.add(bottomBar, BorderLayout.SOUTH);
        setContentPane(root);
        pack();
        // pack() sizes to content preferred width (too narrow for the odds paragraphs), so fix it.
        // Tall enough to show the 2× card preview on the Export tab without scrolling.
        setSize(new Dimension(440, 740));
        setMinimumSize(new Dimension(380, 420));
        setLocationRelativeTo(owner);
    }

    /** Export tab: card preview centred above a bottom-anchored Copy/Save row (its own layout). */
    private JComponent buildExportTab(CapturedCreature capture) {
        return CardExportDialog.sharedImageService() != null
                ? new CardExportPanel(capture)
                : scroll(placeholder("Export unavailable."));
    }

    private JComponent placeholder(String text) {
        JLabel l = new JLabel(text);
        l.setFont(body);
        l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        l.setBorder(new EmptyBorder(16, 16, 16, 16));
        return l;
    }

    private JScrollPane scroll(JComponent content) {
        JScrollPane sp = new JScrollPane(content,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        sp.setBorder(null);
        sp.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        sp.getVerticalScrollBar().setUnitIncrement(16);
        return sp;
    }

    // -------------------------------------------------------------------------
    // Export (clipboard) / Save (PNG) — this tab or all tabs
    // -------------------------------------------------------------------------

    private JComponent buildBottomBar() {
        JButton export = barButton("Copy tab", new Color(60, 90, 150));
        export.addActionListener(e -> flashAfter(export, "✓ Copied",
                () -> copy(decorate(renderTab(tabs.getSelectedIndex())))));
        JButton save = barButton("Save tab PNG", new Color(55, 110, 60));
        save.addActionListener(e -> save(decorate(renderTab(tabs.getSelectedIndex())), "card-" + tabTitle()));

        JPanel bar = new JPanel(new GridLayout(1, 2, 6, 0));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bar.setBorder(new EmptyBorder(6, 8, 8, 8));
        bar.add(export);
        bar.add(save);
        return bar;
    }

    private String tabTitle() {
        return tabs.getTitleAt(tabs.getSelectedIndex()).toLowerCase();
    }

    private JButton barButton(String text, Color bg) {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setBackground(bg);
        b.setForeground(Color.WHITE);
        b.setFocusPainted(false);
        b.setBorderPainted(false);
        return b;
    }

    private void flashAfter(JButton b, String label, Runnable action) {
        action.run();
        String orig = b.getText();
        b.setText(label);
        new javax.swing.Timer(1400, e -> {
            b.setText(orig);
            ((javax.swing.Timer) e.getSource()).stop();
        }).start();
    }

    /** Renders one tab's content (including any scrolled-off part) to an image. */
    private BufferedImage renderTab(int index) {
        Component tab = tabs.getComponentAt(index);
        JComponent c = tab instanceof JScrollPane
                ? (JComponent) ((JScrollPane) tab).getViewport().getView()
                : (JComponent) tab;
        int w = c.getWidth() > 0 ? c.getWidth() : 420;
        int h = c.getHeight() > 0 ? c.getHeight() : Math.max(200, c.getPreferredSize().height);
        BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setColor(ColorScheme.DARK_GRAY_COLOR);
        g.fillRect(0, 0, w, h);
        c.printAll(g);
        g.dispose();
        return img;
    }

    private static final int FOOTER_H = 24;

    /** Wraps a rendered tab with a dashboard-style footer. */
    private BufferedImage decorate(BufferedImage c) {
        BufferedImage dst = new BufferedImage(c.getWidth(), c.getHeight() + FOOTER_H, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = dst.createGraphics();
        g.setColor(ColorScheme.DARK_GRAY_COLOR);
        g.fillRect(0, 0, dst.getWidth(), dst.getHeight());
        g.drawImage(c, 0, 0, null);
        drawFooter(g, c.getWidth(), c.getHeight());
        g.dispose();
        return dst;
    }

    /** Dashboard-style footer: orange rule + centred brand line, drawn in the FOOTER_H band at {@code top}. */
    private void drawFooter(Graphics2D g, int w, int top) {
        g.setColor(new Color(255, 165, 0, 60));
        g.fillRect(12, top + 3, w - 24, 1);
        g.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics fm = g.getFontMetrics();
        String footer = "RuneLite · Bestiary Plugin";
        g.setColor(new Color(110, 110, 110));
        g.drawString(footer, (w - fm.stringWidth(footer)) / 2, top + 10 + fm.getAscent());
    }

    private void copy(BufferedImage img) {
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new Transferable() {
            @Override public DataFlavor[] getTransferDataFlavors() { return new DataFlavor[]{DataFlavor.imageFlavor}; }
            @Override public boolean isDataFlavorSupported(DataFlavor f) { return DataFlavor.imageFlavor.equals(f); }
            @Override public Object getTransferData(DataFlavor f) { return img; }
        }, null);
    }

    private void save(BufferedImage img, String suggestedName) {
        JFileChooser fc = new JFileChooser();
        fc.setSelectedFile(new File(suggestedName + ".png"));
        if (fc.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) return;
        File f = fc.getSelectedFile();
        if (!f.getName().toLowerCase().endsWith(".png")) f = new File(f.getParentFile(), f.getName() + ".png");
        try {
            ImageIO.write(img, "png", f);
        } catch (java.io.IOException ex) {
            /* best effort — ignore */
        }
    }

    // -------------------------------------------------------------------------
    // Overview
    // -------------------------------------------------------------------------

    private JPanel buildOverview(CapturedCreature c) {
        JPanel p = column();

        JLabel title = new JLabel(c.npcName + (c.isShiny() ? "  ✦" : ""));
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(c.rarity.displayColor);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.add(title);
        p.add(Box.createVerticalStrut(8));

        com.bestiary.model.DifficultyTier diff =
                MonsterRoster.getDifficulty(c.npcName, c.npcCombatLevel);
        com.bestiary.model.CreatureSpecies species =
                MonsterRoster.getSpecies(c.npcName, c.npcCombatLevel);

        com.bestiary.model.CombatClass combatClass =
                MonsterRoster.getCombatClass(c.npcName, c.npcCombatLevel);

        p.add(sectionHeader("Card"));
        p.add(kv("Rarity", c.rarity.label, c.rarity.displayColor));
        p.add(kv("Species", species.label, species.displayColor));
        p.add(kv("Class", combatClass.label, new Color(210, 210, 210)));
        p.add(kv("Difficulty", diff.label, diff.displayColor));
        p.add(kv("Power Level", String.valueOf(c.powerLevel()), Color.WHITE));
        p.add(kv("Hitpoints", String.valueOf(c.hitpoints())
                + (c.observedHp > 0 ? "  (observed)" : ""), new Color(120, 200, 120)));
        p.add(kv("Prayer", String.valueOf(c.quality.prayer), Color.WHITE));
        p.add(kv("Shiny", c.isShiny() ? "Yes ✦" : "No",
                c.isShiny() ? new Color(255, 215, 0) : ColorScheme.LIGHT_GRAY_COLOR));

        p.add(Box.createVerticalStrut(10));
        p.add(sectionHeader("Capture"));
        p.add(kv("Caught", DATE.format(c.captureTime), Color.WHITE));
        p.add(kv("Region", c.regionName != null && !c.regionName.isEmpty() ? c.regionName : "Unknown", Color.WHITE));
        p.add(kv("Bestiary level", String.valueOf(c.captureLevel), Color.WHITE));
        p.add(kv("Kills before catch", String.valueOf(c.killsBeforeCapture), Color.WHITE));
        p.add(kv("Combat level", c.npcCombatLevel >= 0 ? String.valueOf(c.npcCombatLevel) : "-", Color.WHITE));

        // Use the ORIGINAL rarity/shiny (the first reroll snapshot) so a rerolled/upgraded card still
        // reports the reward + XP it earned when first caught, not its current form.
        com.bestiary.model.CreatureRarity capRarity =
                c.rerollHistory.isEmpty() ? c.rarity : c.rerollHistory.get(0).rarity;
        boolean capShiny = c.rerollHistory.isEmpty() ? c.isShiny() : c.rerollHistory.get(0).shiny;
        long baseCredits = com.bestiary.util.CreditCalculator.forCapture(diff, capRarity, capShiny);
        long earned = c.creditsEarned;   // true award recorded at capture (0 = legacy card)
        long bounty;
        if (earned > 0) {
            bounty = Math.max(0, earned - baseCredits);
        } else {                         // legacy: best-effort using the current Hunter's Bounty tier
            bounty = captureCreditBonus.getAsLong();
        }
        // A traded-in card's capture credits/XP were earned by the original owner, not this account.
        boolean tradedIn = com.bestiary.model.BestiaryCollection.isTradedIn(c);
        p.add(kv("Credits Earned", tradedIn ? "Transferred" : amountHtml(baseCredits, bounty),
                new Color(120, 190, 255)));

        // Kill XP: awarded on every kill of this monster (difficulty-tiered) + the Hunter's Focus
        // flat shop bonus. Not card-specific, so it reflects the current shop tier.
        long killXpBase  = com.bestiary.service.ProgressionService.killXp(diff);
        p.add(kv("Kill XP", tradedIn ? "Transferred" : amountHtml(killXpBase, killXpFlatBonus.getAsLong()),
                new Color(170, 210, 120)));

        // Capture XP: base (from the ORIGINAL rarity) + the Scholar's Insight % boost. Uses the true
        // awarded value when recorded (as-at-capture); legacy cards fall back to the current bonus.
        long capXpBase  = com.bestiary.service.ProgressionService.captureXp(c.npcCombatLevel, capRarity);
        long capXpBonus = c.xpEarned > 0
                ? Math.max(0, c.xpEarned - capXpBase)
                : Math.round(capXpBase * captureXpBonus.getAsDouble());
        p.add(kv("Capture XP", tradedIn ? "Transferred" : amountHtml(capXpBase, capXpBonus),
                new Color(170, 210, 120)));

        p.add(kv("Caught by", c.originalOwner != null && !c.originalOwner.isEmpty() ? c.originalOwner
                : (c.playerName != null && !c.playerName.isEmpty() ? c.playerName : "Unknown"),
                new Color(200, 155, 50)));
        if (tradedIn) {
            // Card was traded in from another of the player's accounts (#50).
            p.add(kv("Held by", c.currentOwner, new Color(120, 190, 255)));
        }
        if (c.rerollCount() > 0) {
            p.add(kv("Rerolled", c.rerollCount() + (c.rerollCount() == 1 ? " time" : " times"),
                    new Color(180, 150, 230)));
        }

        p.add(Box.createVerticalStrut(10));
        p.add(sectionHeader("Unique ID"));
        JTextField id = new JTextField(CardId.encode(MonsterRoster.getDexNumber(c.npcName), c));
        id.setEditable(false);
        id.setFont(FontManager.getRunescapeSmallFont());
        id.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        id.setForeground(new Color(150, 150, 150));
        id.setCaretPosition(0);
        id.setAlignmentX(Component.LEFT_ALIGNMENT);
        id.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        p.add(id);
        JLabel hint = new JLabel("Select + copy to share or look this card up.");
        hint.setFont(FontManager.getRunescapeSmallFont());
        hint.setForeground(new Color(120, 120, 120));
        hint.setAlignmentX(Component.LEFT_ALIGNMENT);
        hint.setBorder(new EmptyBorder(2, 0, 0, 0));
        p.add(hint);

        return p;
    }

    // -------------------------------------------------------------------------
    // Reroll history
    // -------------------------------------------------------------------------

    private JPanel buildRerollHistory(CapturedCreature c) {
        JPanel p = column();

        if (c.rerollCount() == 0) {
            JLabel none = new JLabel("This card has never been rerolled, so it's a raw pull.");
            none.setFont(body);
            none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            p.add(none);
            return p;
        }

        Set<String> rerollers = c.uniqueRerollers();
        p.add(sectionHeader("Rerolled " + c.rerollCount() + (c.rerollCount() == 1 ? " time" : " times")));
        JLabel who = new JLabel("<html><div style='width:390px'>"
                + rerollers.size() + (rerollers.size() == 1 ? " reroller: " : " rerollers: ")
                + String.join(", ", rerollers) + "</div></html>");
        who.setFont(body);
        who.setForeground(new Color(180, 150, 230));
        who.setAlignmentX(Component.LEFT_ALIGNMENT);
        p.add(who);
        p.add(Box.createVerticalStrut(8));

        // Timeline table: each past state, then the current state.
        JPanel t = new JPanel(new GridBagLayout());
        t.setOpaque(false);
        t.setAlignmentX(Component.LEFT_ALIGNMENT);
        GridBagConstraints g = new GridBagConstraints();
        g.insets = new Insets(2, 0, 2, 8);
        g.anchor = GridBagConstraints.WEST;
        g.weightx = 1.0;   // fill the table width (otherwise GridBag centres the columns)

        String[] heads = {"State", "Rarity", "PWR", "Shiny", "By", "When"};
        for (int i = 0; i < heads.length; i++) {
            g.gridx = i; g.gridy = 0;
            t.add(cell(heads[i], bodyBold, new Color(140, 140, 140)), g);
        }
        // thin rule under the header so the table reads as a table, not floating text
        GridBagConstraints sep = new GridBagConstraints();
        sep.gridx = 0; sep.gridy = 1; sep.gridwidth = heads.length;
        sep.fill = GridBagConstraints.HORIZONTAL;
        sep.insets = new Insets(2, 0, 4, 0);
        JPanel rule = new JPanel();
        rule.setBackground(new Color(70, 70, 70));
        rule.setPreferredSize(new Dimension(10, 1));
        t.add(rule, sep);

        int row = 2;
        java.util.List<CapturedCreature.RerollState> h = c.rerollHistory;
        for (int i = 0; i < h.size(); i++) {
            CapturedCreature.RerollState s = h.get(i);
            String stateLabel = i == 0 ? "Original" : "Roll " + i;
            addRerollRow(t, g, row++, stateLabel, s.rarity.label, s.rarity.displayColor,
                    s.powerLevel, s.shiny, s.rerolledBy,
                    DATE_SHORT.format(Instant.ofEpochSecond(s.epoch)));
        }
        // Current (latest) state
        addRerollRow(t, g, row, "Current", c.rarity.label, c.rarity.displayColor,
                c.powerLevel(), c.isShiny(), "-", "now");

        t.setMaximumSize(new Dimension(Integer.MAX_VALUE, t.getPreferredSize().height));
        p.add(t);

        p.add(Box.createVerticalStrut(6));
        JTextArea note = new JTextArea("Each reroll re-rolls the stats & shiny at the same monster; "
                + "a non-Mythic card has a small chance to rank up.");
        note.setFont(body);
        note.setForeground(new Color(120, 120, 120));
        note.setBackground(ColorScheme.DARK_GRAY_COLOR);
        note.setOpaque(false);
        note.setEditable(false);
        note.setFocusable(false);
        note.setLineWrap(true);
        note.setWrapStyleWord(true);
        JPanel noteWrap = new JPanel(new BorderLayout());
        noteWrap.setOpaque(false);
        noteWrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        noteWrap.setBorder(new EmptyBorder(6, 0, 0, 0));
        noteWrap.add(note, BorderLayout.CENTER);
        p.add(noteWrap);
        return p;
    }

    private void addRerollRow(JPanel t, GridBagConstraints g, int rowY, String state, String rarity,
                              Color rarityColor, int pwr, boolean shiny, String by, String when) {
        boolean isCurrent = "Current".equals(state);
        Font f = isCurrent ? bodyBold : body;
        g.gridy = rowY;
        g.gridx = 0; t.add(cell(state, f, isCurrent ? Color.WHITE : new Color(200, 200, 200)), g);
        g.gridx = 1; t.add(cell(rarity, f, rarityColor), g);
        g.gridx = 2; t.add(cell(String.valueOf(pwr), f, Color.WHITE), g);
        g.gridx = 3; t.add(cell(shiny ? "✦" : "–", f, shiny ? new Color(255, 215, 0) : new Color(110, 110, 110)), g);
        g.gridx = 4; t.add(cell(by, f, new Color(180, 150, 230)), g);
        g.gridx = 5; t.add(cell(when, f, new Color(140, 140, 140)), g);
    }

    // -------------------------------------------------------------------------
    // Shared helpers
    // -------------------------------------------------------------------------

    private JPanel column() {
        // Track the scroll viewport width so full-width children (the reroll table) fill it
        // instead of the panel sizing to a wide child's preferred width and clipping.
        JPanel p = new JPanel() {
            @Override public Dimension getPreferredSize() {
                Dimension d = super.getPreferredSize();
                if (getParent() != null) d.width = getParent().getWidth();
                return d;
            }
        };
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        p.setBackground(ColorScheme.DARK_GRAY_COLOR);
        p.setBorder(new EmptyBorder(12, 14, 12, 14));
        return p;
    }

    private JLabel sectionHeader(String text) {
        JLabel l = new JLabel(text.toUpperCase());
        l.setFont(bodyBold);
        l.setForeground(new Color(255, 152, 31));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        l.setBorder(new EmptyBorder(0, 0, 3, 0));
        return l;
    }

    private JLabel cell(String text, Font font, Color colour) {
        JLabel l = new JLabel(text);
        l.setFont(font);
        l.setForeground(colour);
        return l;
    }

    /** Renders "base" or "base <green>(+bonus)</green>" (green = a shop-upgrade bonus) as an HTML value. */
    private static String amountHtml(long base, long bonus) {
        return bonus > 0
                ? "<html>" + base + " <font color='" + BONUS_HEX + "'>(+" + bonus + ")</font></html>"
                : String.valueOf(base);
    }

    private Box kv(String left, String right, Color rightColor) {
        Box row = Box.createHorizontalBox();
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, body.getSize() + 8));
        JLabel l = new JLabel(left);
        l.setFont(body);
        l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        JLabel rr = new JLabel(right);
        rr.setFont(body);
        rr.setForeground(rightColor);
        // HTML labels report an unbounded max width, so the glue can't push them flush right —
        // pin the max to the preferred size so they stay compact like plain-text values.
        rr.setMaximumSize(rr.getPreferredSize());
        row.add(l);
        row.add(Box.createHorizontalStrut(14));
        row.add(Box.createHorizontalGlue());
        row.add(rr);
        return row;
    }
}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * MODELESS reroll outcome screen: shows the card's stats before vs after a reroll,
 * with per-stat deltas, plus any rarity/shiny change. Modeless so it never blocks
 * the game or other panels.
 */
public class RerollResultDialog extends JDialog {

    private static RerollResultDialog current;

    /**
     * @param onRerollAgain re-runs the reroll flow on the just-rerolled card (opens the confirm
     *                      dialog again); null hides the "Reroll again?" button.
     */
    public static void open(Window owner, CapturedCreature before, CapturedCreature after,
                            Runnable onRerollAgain) {
        if (current != null && current.isShowing()) current.dispose();
        current = new RerollResultDialog(owner, before, after, onRerollAgain);
        current.setVisible(true);
    }

    /** A small MODELESS info popup (non-blocking) — e.g. "not enough credits". */
    public static void info(Window owner, String title, String message) {
        JDialog d = new JDialog(owner, title, ModalityType.MODELESS);
        d.setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        JPanel p = new JPanel(new BorderLayout(0, 8));
        p.setBackground(ColorScheme.DARK_GRAY_COLOR);
        p.setBorder(new EmptyBorder(14, 16, 12, 16));
        JLabel l = new JLabel("<html><div style='width:240px'>" + message + "</div></html>");
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(Color.WHITE);
        JButton ok = new JButton("OK");
        ok.setFocusPainted(false);
        ok.addActionListener(e -> d.dispose());
        JPanel row = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        row.setOpaque(false);
        row.add(ok);
        p.add(l, BorderLayout.CENTER);
        p.add(row, BorderLayout.SOUTH);
        d.setContentPane(p);
        d.pack();
        d.setLocationRelativeTo(owner);
        d.setVisible(true);
    }

    private RerollResultDialog(Window owner, CapturedCreature b, CapturedCreature a, Runnable onRerollAgain) {
        super(owner, "Reroll result", ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setResizable(false);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(new EmptyBorder(12, 14, 12, 14));

        JLabel title = new JLabel(a.npcName);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(a.rarity.displayColor);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        root.add(title);

        if (a.rarity != b.rarity) {
            JLabel up = new JLabel("Rarity: " + b.rarity.label + "  →  " + a.rarity.label + "  ⬆");
            up.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
            up.setForeground(new Color(255, 215, 0));
            up.setAlignmentX(Component.LEFT_ALIGNMENT);
            root.add(up);
        }
        if (a.isShiny() && !b.isShiny()) {
            JLabel sh = new JLabel("✦ Now SHINY!");
            sh.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
            sh.setForeground(new Color(255, 215, 0));
            sh.setAlignmentX(Component.LEFT_ALIGNMENT);
            root.add(sh);
        }

        root.add(Box.createVerticalStrut(8));

        // Stats table: Stat | Before | After | Δ
        JPanel t = new JPanel(new GridBagLayout());
        t.setOpaque(false);
        t.setAlignmentX(Component.LEFT_ALIGNMENT);
        GridBagConstraints g = new GridBagConstraints();
        g.insets = new Insets(1, 0, 1, 14);
        String[] heads = {"Stat", "Before", "After", "Δ"};
        for (int c = 0; c < heads.length; c++) {
            g.gridx = c; g.gridy = 0;
            g.anchor = c == 0 ? GridBagConstraints.WEST : GridBagConstraints.EAST;
            t.add(cell(heads[c], true, new Color(140, 140, 140)), g);
        }
        String[] names = {"Attack", "Strength", "Defence", "Magic", "Ranged", "Agility", "Prayer", "Power Level"};
        int[] bv = {b.quality.attack, b.quality.strength, b.quality.defence, b.quality.magic,
                    b.quality.ranged, b.quality.agility, b.quality.prayer, b.powerLevel()};
        int[] av = {a.quality.attack, a.quality.strength, a.quality.defence, a.quality.magic,
                    a.quality.ranged, a.quality.agility, a.quality.prayer, a.powerLevel()};
        for (int i = 0; i < names.length; i++) {
            int d = av[i] - bv[i];
            g.gridy = i + 1;
            g.gridx = 0; g.anchor = GridBagConstraints.WEST;
            boolean pl = i == names.length - 1;
            t.add(cell(names[i], pl, new Color(210, 210, 210)), g);
            g.gridx = 1; g.anchor = GridBagConstraints.EAST;
            t.add(cell(String.valueOf(bv[i]), false, new Color(150, 150, 150)), g);
            g.gridx = 2; g.anchor = GridBagConstraints.EAST;
            t.add(cell(String.valueOf(av[i]), pl, Color.WHITE), g);
            g.gridx = 3; g.anchor = GridBagConstraints.EAST;
            String ds = d > 0 ? "+" + d : String.valueOf(d);
            Color dc = d > 0 ? new Color(120, 200, 120) : d < 0 ? new Color(224, 112, 112) : new Color(150, 150, 150);
            t.add(cell(ds, pl, dc), g);
        }
        root.add(t);

        // Benchmark the rerolled Power Level against the average and average-shiny roll for this
        // rarity (same figures as the Card Info → Odds tab), so the player can judge the roll.
        com.bestiary.util.OddsCalculator.Result odds3 = com.bestiary.util.OddsCalculator.compute(a);
        root.add(Box.createVerticalStrut(8));
        root.add(benchmark("Average " + a.rarity.label + " roll", odds3.avgPowerLevel));
        root.add(benchmark("Average " + a.rarity.label + " shiny roll", odds3.avgShinyPowerLevel));

        root.add(Box.createVerticalStrut(10));
        JButton odds = new JButton("Card Info…");
        odds.setFont(FontManager.getRunescapeSmallFont());
        odds.setBackground(new Color(60, 90, 150));
        odds.setForeground(Color.WHITE);
        odds.setFocusPainted(false);
        odds.addActionListener(e -> CardDataDialog.open(owner, a, CardDataDialog.TAB_ODDS));

        JButton close = new JButton("Close");
        close.setFont(FontManager.getRunescapeSmallFont());
        close.setFocusPainted(false);
        close.setAlignmentX(Component.LEFT_ALIGNMENT);
        close.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        close.addActionListener(e -> dispose());

        // Top row: Card Info… + Reroll again? (side by side). Close sits on its own full-width row below.
        if (onRerollAgain != null) {
            JButton again = new JButton("Reroll again?");
            again.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
            again.setBackground(new Color(60, 120, 60));
            again.setForeground(Color.WHITE);
            again.setFocusPainted(false);
            again.setToolTipText("Reroll this same card again (opens the confirm screen)");
            again.addActionListener(e -> { dispose(); onRerollAgain.run(); });
            JPanel topRow = new JPanel(new GridLayout(1, 2, 8, 0));
            topRow.setOpaque(false);
            topRow.setAlignmentX(Component.LEFT_ALIGNMENT);
            topRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
            topRow.add(odds);
            topRow.add(again);
            root.add(topRow);
            root.add(Box.createVerticalStrut(8));
        } else {
            odds.setAlignmentX(Component.LEFT_ALIGNMENT);
            odds.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
            root.add(odds);
            root.add(Box.createVerticalStrut(8));
        }
        root.add(close);

        setContentPane(root);
        pack();
        setLocationRelativeTo(owner);
    }

    /** A "label ....... value" benchmark row (dim label, white value), left-aligned. */
    private JLabel benchmark(String label, int value) {
        JLabel l = new JLabel(label + ":  " + value);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(new Color(176, 176, 176));
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }

    private JLabel cell(String text, boolean bold, Color colour) {
        JLabel l = new JLabel(text);
        l.setFont(bold ? FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD)
                       : FontManager.getRunescapeSmallFont());
        l.setForeground(colour);
        return l;
    }
}

package com.bestiary.ui;

import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.service.WikiImageService;
import com.bestiary.util.CardId;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Preview dialog for page grid export. Shows a scaled preview of the rendered
 * grid with column count selector and Copy / Save PNG actions.
 */
public class PageExportDialog extends JDialog {

    private static final int GAP      = 6;
    private static final int PAD      = 8;
    private static final int SCALE    = 2;
    private static final int BANNER_H = 42;
    private static final int PREVIEW_MAX_W = 420;

    private final List<CapturedCreature> captures;
    private final String monsterName;
    private final Map<String, Integer> dexNumbers;
    private final WikiImageService imageService;
    private final BestiaryCollection collection;

    private int selectedCols;
    private final JLabel previewLabel;
    private final JScrollPane previewScroll;
    private JButton activeCopyBtn;

    public PageExportDialog(Window parent, List<CapturedCreature> captures, String monsterName,
                            Map<String, Integer> dexNumbers, WikiImageService imageService,
                            BestiaryCollection collection) {
        super(parent, "Export Page: " + monsterName, ModalityType.MODELESS);
        this.captures    = captures;
        this.monsterName = monsterName;
        this.dexNumbers  = dexNumbers;
        this.imageService = imageService;
        this.collection  = collection;

        int count = captures.size();
        this.selectedCols = defaultCols(count);

        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setResizable(false);

        // Preview label inside a scroll pane
        previewLabel = new JLabel();
        previewLabel.setHorizontalAlignment(SwingConstants.CENTER);
        previewLabel.setBackground(new Color(18, 18, 18));
        previewLabel.setOpaque(true);
        previewScroll = new JScrollPane(previewLabel);
        previewScroll.setBorder(BorderFactory.createLineBorder(new Color(40, 40, 40)));
        previewScroll.getVerticalScrollBar().setUnitIncrement(16);

        // Column selector row
        JPanel colRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        colRow.setOpaque(false);
        int[] colOpts = colOptions(count);
        if (colOpts.length > 1) {
            JLabel colLabel = new JLabel("Cols:");
            colLabel.setFont(FontManager.getRunescapeSmallFont());
            colLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            colRow.add(colLabel);
            ButtonGroup bg = new ButtonGroup();
            for (int cols : colOpts) {
                JToggleButton btn = colBtn(cols, cols == selectedCols);
                bg.add(btn);
                colRow.add(btn);
            }
        }

        // Action buttons
        activeCopyBtn = new JButton("Copy");
        activeCopyBtn.setFont(FontManager.getRunescapeSmallFont());
        activeCopyBtn.setBackground(new Color(0, 80, 160));
        activeCopyBtn.setForeground(Color.WHITE);
        activeCopyBtn.setFocusPainted(false);
        activeCopyBtn.addActionListener(e -> copyGrid());

        JButton saveBtn = new JButton("Save PNG");
        saveBtn.setFont(FontManager.getRunescapeSmallFont());
        saveBtn.setBackground(new Color(0, 120, 40));
        saveBtn.setForeground(Color.WHITE);
        saveBtn.setFocusPainted(false);
        saveBtn.addActionListener(e -> saveGrid());

        JPanel actionRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        actionRow.setOpaque(false);
        actionRow.add(activeCopyBtn);
        actionRow.add(saveBtn);

        JPanel bottomBar = new JPanel(new BorderLayout(8, 0));
        bottomBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        bottomBar.setBorder(new EmptyBorder(4, 4, 4, 4));
        bottomBar.add(colRow,    BorderLayout.WEST);
        bottomBar.add(actionRow, BorderLayout.EAST);

        JPanel content = new JPanel(new BorderLayout(0, 6));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        content.setBorder(new EmptyBorder(8, 8, 8, 8));
        content.add(previewScroll, BorderLayout.CENTER);
        content.add(bottomBar,     BorderLayout.SOUTH);

        // Fix the scroll pane size to the tallest possible layout (fewest cols = most rows)
        // so the dialog never resizes when the user changes column count.
        int minCols = colOpts.length > 0 ? colOpts[0] : selectedCols;
        BufferedImage tallest = renderGrid(minCols);
        double fixScale = Math.min(1.0, (double) PREVIEW_MAX_W / tallest.getWidth());
        int fixedW = (int) (tallest.getWidth()  * fixScale);
        int fixedH = Math.min((int) (tallest.getHeight() * fixScale), 600);
        previewScroll.setPreferredSize(new Dimension(fixedW + 4, fixedH + 4));

        setContentPane(content);
        updatePreview();
        pack();
        setLocationRelativeTo(parent);
        setVisible(true);
    }

    private JToggleButton colBtn(int cols, boolean selected) {
        JToggleButton btn = new JToggleButton(cols + " cols");
        btn.setFont(FontManager.getRunescapeSmallFont());
        btn.setSelected(selected);
        btn.setFocusPainted(false);
        btn.addActionListener(e -> { selectedCols = cols; updatePreview(); });
        return btn;
    }

    private void updatePreview() {
        BufferedImage grid = renderGrid(selectedCols);
        double scale = Math.min(1.0, (double) PREVIEW_MAX_W / grid.getWidth());
        int pw = (int) (grid.getWidth()  * scale);
        int ph = (int) (grid.getHeight() * scale);
        Image scaled = grid.getScaledInstance(pw, ph, Image.SCALE_SMOOTH);
        previewLabel.setIcon(new ImageIcon(scaled));
        previewLabel.setPreferredSize(new Dimension(pw, ph));
        previewLabel.revalidate();
        previewLabel.repaint();
    }

    private void copyGrid() {
        BufferedImage img = renderGrid(selectedCols);
        Transferable t = new Transferable() {
            @Override public DataFlavor[] getTransferDataFlavors() { return new DataFlavor[]{DataFlavor.imageFlavor}; }
            @Override public boolean isDataFlavorSupported(DataFlavor f) { return DataFlavor.imageFlavor.equals(f); }
            @Override public Object getTransferData(DataFlavor f) throws UnsupportedFlavorException {
                if (!DataFlavor.imageFlavor.equals(f)) throw new UnsupportedFlavorException(f);
                return img;
            }
        };
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(t, null);
        flashButton(activeCopyBtn, "Copied!");
    }

    private void saveGrid() {
        JFileChooser fc = new JFileChooser();
        fc.setSelectedFile(new File(monsterName.replaceAll("[^a-zA-Z0-9_\\- ]", "") + "_export.png"));
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("PNG image", "png"));
        if (fc.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) return;
        File out = fc.getSelectedFile();
        if (!out.getName().toLowerCase().endsWith(".png")) out = new File(out.getPath() + ".png");
        try {
            ImageIO.write(renderGrid(selectedCols), "PNG", out);
        } catch (Exception ex) {
            JOptionPane.showMessageDialog(this, "Save failed: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void flashButton(JButton btn, String msg) {
        String prev = btn.getText();
        btn.setText(msg);
        btn.setForeground(new Color(120, 200, 120));
        javax.swing.Timer t = new javax.swing.Timer(2000, e -> {
            btn.setText(prev);
            btn.setForeground(Color.WHITE);
        });
        t.setRepeats(false);
        t.start();
    }

    // -------------------------------------------------------------------------
    // Rendering
    // -------------------------------------------------------------------------

    private BufferedImage renderGrid(int cols) {
        int count    = captures.size();
        int rows     = (count + cols - 1) / cols;
        final int SLOT_H   = AlbumCard.CARD_H + 2 + BANNER_H;
        final int HEADER_H = 34;

        String playerName = captures.stream()
                .map(c -> c.playerName).filter(n -> n != null && !n.isEmpty())
                .findFirst().orElse("Unknown");
        String headerText = monsterName + " · " + count + " card" + (count == 1 ? "" : "s");

        int logW = cols * AlbumCard.CARD_W + (cols - 1) * GAP + PAD * 2;
        int logH = HEADER_H + PAD + rows * SLOT_H + (rows - 1) * GAP + PAD;

        BufferedImage img = new BufferedImage(logW * SCALE, logH * SCALE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING,         RenderingHints.VALUE_RENDER_QUALITY);
        g2.scale(SCALE, SCALE);

        // Background + header
        g2.setColor(new Color(18, 18, 18));
        g2.fillRect(0, 0, logW, logH);
        g2.setColor(new Color(28, 28, 28));
        g2.fillRect(0, 0, logW, HEADER_H);
        g2.setFont(FontManager.getRunescapeBoldFont());
        FontMetrics hfm = g2.getFontMetrics();
        g2.setColor(captures.isEmpty() ? Color.WHITE : captures.get(0).rarity.displayColor);
        g2.drawString(headerText, (logW - hfm.stringWidth(headerText)) / 2,
                (HEADER_H + hfm.getAscent() - hfm.getDescent()) / 2);

        for (int i = 0; i < count; i++) {
            CapturedCreature cap = captures.get(i);
            int dex = dexNumbers.getOrDefault(cap.npcName, 0);
            AlbumCard card = new AlbumCard(dex, cap.npcName, List.of(cap), collection, imageService);
            card.setShowQuality(true);
            card.setSize(AlbumCard.CARD_W, AlbumCard.CARD_H);

            int col = i % cols;
            int row = i / cols;
            int x   = PAD + col * (AlbumCard.CARD_W + GAP);
            int y   = HEADER_H + PAD + row * (SLOT_H + GAP);

            Graphics2D cardG2 = (Graphics2D) g2.create();
            cardG2.translate(x, y);
            card.print(cardG2);
            cardG2.dispose();
            card.removeNotify();

            int bY = y + AlbumCard.CARD_H + 2;
            g2.setColor(new Color(25, 25, 25));
            g2.fillRoundRect(x, bY, AlbumCard.CARD_W, BANNER_H, 4, 4);

            String capBy = (cap.playerName != null && !cap.playerName.isEmpty()) ? cap.playerName : playerName;
            String cardId = CardId.encode(dex, cap);
            CardExportDialog.drawBanner(g2, x, bY, AlbumCard.CARD_W, BANNER_H, cardId, "Captured by " + capBy);
        }

        g2.dispose();
        return img;
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private static int defaultCols(int count) {
        if (count <= 1)  return 1;
        if (count <= 6)  return 2;
        if (count <= 12) return 3;
        return 4;
    }

    private static int[] colOptions(int count) {
        if (count <= 1) return new int[]{1};
        List<Integer> opts = new ArrayList<>();
        if (count >= 2 && count <= 6)  opts.add(2);
        if (count >= 3 && count <= 12) opts.add(3);
        if (count >= 4)                opts.add(4);
        return opts.stream().mapToInt(i -> i).toArray();
    }
}

package com.bestiary.ui;

import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.MonsterRoster;
import com.bestiary.service.WikiImageService;
import com.bestiary.util.CardId;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Card export helpers. The interactive export view now lives as the first tab of
 * {@link CardDataDialog} (see {@link CardExportPanel}); {@link #open} redirects there so every
 * existing "Export Card" menu item and card left-click lands on that tab. This class still holds
 * the shared wiring (image service / collection / callbacks), the direct-copy path
 * ({@link #copyNow}) and the shared banner renderer ({@link #drawBanner}).
 */
public final class CardExportDialog {

    private static WikiImageService sharedImageService;
    private static Supplier<BestiaryCollection> collectionSupplier;
    private static Consumer<String> onCopyAction;
    private static Runnable onMutate;   // persist + refresh after favourite / album-cover changes

    private CardExportDialog() {}

    /** Wire a callback that persists and refreshes the panel after a right-click mutation. */
    public static void setOnMutate(Runnable callback) {
        onMutate = callback;
    }

    /** Close the open export view — now delegated to the Card data dialog that hosts it. */
    public static void disposeOpen() {
        CardDataDialog.disposeOpen();
    }

    public static void setShared(WikiImageService imgSvc, Supplier<BestiaryCollection> supplier) {
        sharedImageService = imgSvc;
        collectionSupplier = supplier;
    }

    public static void setOnCopy(Consumer<String> callback) {
        onCopyAction = callback;
    }

    // Package-private accessors so CardExportPanel can reuse the shared wiring.
    static WikiImageService sharedImageService()               { return sharedImageService; }
    static Supplier<BestiaryCollection> collectionSupplier()    { return collectionSupplier; }
    static Consumer<String> onCopyAction()                      { return onCopyAction; }
    static Runnable onMutate()                                  { return onMutate; }

    /** Open the export view for a single capture — the Card data dialog on its Export tab. */
    public static void open(Window owner, CapturedCreature capture) {
        if (sharedImageService == null || collectionSupplier == null) return;
        CardDataDialog.open(owner, capture, CardDataDialog.TAB_EXPORT);
    }

    /**
     * Renders a capture to a standalone card image (2× scale, with the export banner footer),
     * exactly as the clipboard/export paths do. Must be called on the EDT (it prints a Swing
     * component). Returns null if the shared wiring isn't set up yet.
     */
    public static BufferedImage renderCardImage(CapturedCreature capture) {
        if (sharedImageService == null || collectionSupplier == null) return null;
        int dex = MonsterRoster.getDexNumber(capture.npcName);
        String capturedBy = capture.playerName != null && !capture.playerName.isEmpty()
                ? capture.playerName : "Unknown";
        String cardId = CardId.encode(dex, capture);
        AlbumCard card = new AlbumCard(dex, capture.npcName, List.of(capture),
                collectionSupplier.get(), sharedImageService);
        card.setShowQuality(true);
        card.setSize(AlbumCard.CARD_W, AlbumCard.CARD_H);

        int scale   = 3;
        int bottomH = 42;
        BufferedImage img = new BufferedImage(AlbumCard.CARD_W * scale,
                (AlbumCard.CARD_H + bottomH) * scale, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.scale(scale, scale);
        card.print(g2);
        g2.setColor(new Color(12, 12, 12));
        g2.fillRect(0, AlbumCard.CARD_H, AlbumCard.CARD_W, bottomH);
        String ownerStr = "Captured by " + capturedBy;
        drawBanner(g2, 0, AlbumCard.CARD_H, AlbumCard.CARD_W, bottomH, cardId, ownerStr, capture.rerollCount());
        g2.dispose();
        card.removeNotify();
        return img;
    }

    /** Copy a capture card directly to clipboard without opening any view. */
    public static void copyNow(Window owner, CapturedCreature capture) {
        if (sharedImageService == null || collectionSupplier == null) return;
        int dex = MonsterRoster.getDexNumber(capture.npcName);
        String cardId = CardId.encode(dex, capture);
        BufferedImage img = renderCardImage(capture);
        if (img == null) return;

        BufferedImage exported = img;
        Transferable t = new Transferable() {
            @Override public DataFlavor[] getTransferDataFlavors() { return new DataFlavor[]{DataFlavor.imageFlavor}; }
            @Override public boolean isDataFlavorSupported(DataFlavor f) { return DataFlavor.imageFlavor.equals(f); }
            @Override public Object getTransferData(DataFlavor f) throws UnsupportedFlavorException {
                if (!DataFlavor.imageFlavor.equals(f)) throw new UnsupportedFlavorException(f);
                return exported;
            }
        };
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(t, null);
        if (onCopyAction != null) {
            onCopyAction.accept("Card copied: " + capture.npcName + " · " + cardId);
        }
    }

    static void drawBanner(Graphics2D g2, int bX, int bY, int bannerW, int bannerH, String cardId, String ownerStr) {
        drawBanner(g2, bX, bY, bannerW, bannerH, cardId, ownerStr, 0);
    }

    /** Draws the banner: UniqueID + Captured by (+ optional Rerolled N times) centred, brand pinned bottom. */
    static void drawBanner(Graphics2D g2, int bX, int bY, int bannerW, int bannerH,
                           String cardId, String ownerStr, int rerollCount) {
        // Shrink the ID font if the (now longer) ID would overflow the banner width.
        float idSize = 7f;
        while (idSize > 4f && FontManager.getRunescapeSmallFont().deriveFont(idSize)
                .getStringBounds(cardId, g2.getFontRenderContext()).getWidth() > bannerW - 6) {
            idSize -= 0.25f;
        }
        Font idFont     = FontManager.getRunescapeSmallFont().deriveFont(idSize);
        Font playerFont = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 10f);
        Font brandFont  = FontManager.getRunescapeSmallFont().deriveFont(8f);
        g2.setFont(idFont);     FontMetrics ifm = g2.getFontMetrics();
        g2.setFont(playerFont); FontMetrics pfm = g2.getFontMetrics();
        g2.setFont(brandFont);  FontMetrics bfm = g2.getFontMetrics();
        // OSRS | BESTIARY pinned 2px from bottom
        String brand = "OSRS | BESTIARY";
        int brandY = bY + bannerH - bfm.getDescent() - 2;
        g2.setFont(brandFont);
        g2.setColor(new Color(110, 110, 110));
        g2.drawString(brand, bX + (bannerW - bfm.stringWidth(brand)) / 2, brandY);
        // UniqueID + Captured by (+ optional Rerolled N times) centred above the brand line
        boolean rerolled = rerollCount > 0;
        Font reFont = FontManager.getRunescapeSmallFont().deriveFont(Font.ITALIC, 8f);
        g2.setFont(reFont); FontMetrics rfm = g2.getFontMetrics();
        int gap    = 2;
        int upperH = bannerH - bfm.getHeight() - 2;
        int blockH = ifm.getHeight() + gap + pfm.getHeight() + (rerolled ? gap + rfm.getHeight() : 0);
        int startY = bY + Math.max(2, (upperH - blockH) / 2);
        g2.setFont(idFont);
        g2.setColor(new Color(90, 90, 90));
        g2.drawString(cardId, bX + (bannerW - ifm.stringWidth(cardId)) / 2, startY + ifm.getAscent());
        g2.setFont(playerFont);
        g2.setColor(new Color(200, 155, 50));
        int y2 = startY + ifm.getHeight() + gap;
        g2.drawString(ownerStr, bX + (bannerW - pfm.stringWidth(ownerStr)) / 2, y2 + pfm.getAscent());
        if (rerolled) {
            String reStr = "Rerolled " + rerollCount + (rerollCount == 1 ? " time" : " times");
            g2.setFont(reFont);
            g2.setColor(new Color(150, 120, 200));
            int y3 = y2 + pfm.getHeight() + gap;
            g2.drawString(reStr, bX + (bannerW - rfm.stringWidth(reStr)) / 2, y3 + rfm.getAscent());
        }
    }
}

