        // Detail top bar
        // -------------------------------------------------------------------------
        JPanel detailBar = new JPanel();
        detailBar.setLayout(new BoxLayout(detailBar, BoxLayout.Y_AXIS));
        detailBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
