        dRow1.add(dRow1West,        BorderLayout.WEST);
        dRow1.add(detailTitleLabel, BorderLayout.CENTER);
        dRow1.add(dRow1East,        BorderLayout.EAST);

        // Detail row 2: Sort | ← Prev | page X / Y | Next →
