    private int diffOrdinal(String name, Map<String, List<CapturedCreature>> byNpc) {
        int combat = byNpc.containsKey(name) ? byNpc.get(name).get(0).npcCombatLevel : 0;
        return MonsterRoster.getDifficulty(name, combat).ordinal();
    }

    private int diffOrdinalAny(String name) {
        int combat = capturesByNpc.containsKey(name)
                ? capturesByNpc.get(name).get(0).npcCombatLevel : 0;
        return MonsterRoster.getDifficulty(name, combat).ordinal();
    }

    private static CreatureRarity maxRarity(List<CapturedCreature> captures) {
        return captures.stream().map(c -> c.rarity)
                .max(Comparator.comparingInt(Enum::ordinal)).orElse(CreatureRarity.COMMON);
    }

    private static int avgQuality(List<CapturedCreature> captures) {
        return (int) captures.stream().mapToInt(c -> c.powerLevel()).average().orElse(0);
    }

    /** Highest single-card Power Level among a monster's captures (drives "Power (high)"). */
    private static int maxQuality(List<CapturedCreature> captures) {
        return captures.stream().mapToInt(c -> c.powerLevel()).max().orElse(0);
    }

    private static Instant latestCapture(List<CapturedCreature> captures) {
        return captures.stream().map(c -> c.captureTime)
                .max(Comparator.naturalOrder()).orElse(Instant.EPOCH);
    }

    // -------------------------------------------------------------------------
    // Detail page grid export
    // -------------------------------------------------------------------------

    private void exportPageGrid(JButton btn) {
        List<CapturedCreature> page = detailCurrentPage;
        if (page == null || page.isEmpty()) return;

        int count = page.size();
        int cols  = count == 1 ? 1 : count <= 4 ? 2 : 4;
        int rows  = (count + cols - 1) / cols;
        final int GAP      = 6;
        final int PAD      = 8;
        final int SCALE    = 2;
        final int BANNER_H = 26;
        final int SLOT_H   = AlbumCard.CARD_H + 2 + BANNER_H;

        String playerName = page.stream()
                .map(c -> c.playerName).filter(n -> n != null && !n.isEmpty())
                .findFirst().orElse("Unknown");
        String headerText = detailMonsterName != null ? detailMonsterName + " · " + count + " card" + (count == 1 ? "" : "s") : count + " cards";

        final int HEADER_H = 34;
        int logW = cols * AlbumCard.CARD_W + (cols - 1) * GAP + PAD * 2;
        int logH = HEADER_H + PAD + rows * SLOT_H + (rows - 1) * GAP + PAD;

        BufferedImage img = new BufferedImage(logW * SCALE, logH * SCALE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,     RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING,         RenderingHints.VALUE_RENDER_QUALITY);
        g2.scale(SCALE, SCALE);

        g2.setColor(new Color(18, 18, 18));
        g2.fillRect(0, 0, logW, logH);
        g2.setColor(new Color(28, 28, 28));
        g2.fillRect(0, 0, logW, HEADER_H);
        g2.setFont(FontManager.getRunescapeBoldFont());
        FontMetrics hfm = g2.getFontMetrics();
        int hx = (logW - hfm.stringWidth(headerText)) / 2;
        int hy = (HEADER_H + hfm.getAscent() - hfm.getDescent()) / 2;
        g2.setColor(page.get(0).rarity.displayColor);
        g2.drawString(headerText, hx, hy);

        Font playerFont = FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD);
        Font idFont     = FontManager.getRunescapeSmallFont();

        for (int i = 0; i < page.size(); i++) {
            CapturedCreature cap = page.get(i);
            int dex = dexNumbers.getOrDefault(cap.npcName, 0);
            AlbumCard card = new AlbumCard(dex, cap.npcName, List.of(cap), collection, imageService);
            card.setShowQuality(true);
            card.setSize(AlbumCard.CARD_W, AlbumCard.CARD_H);

            int col = i % cols;
            int row = i / cols;
            int x   = PAD + col * (AlbumCard.CARD_W + GAP);
            int y   = HEADER_H + PAD + row * (SLOT_H + GAP);

            Graphics2D cardG2 = (Graphics2D) g2.create();
            cardG2.translate(x, y);
            card.print(cardG2);
            cardG2.dispose();

            int bY = y + AlbumCard.CARD_H + 2;
            g2.setColor(new Color(25, 25, 25));
            g2.fillRoundRect(x, bY, AlbumCard.CARD_W, BANNER_H, 4, 4);

            String cardId = CardId.encode(dex, cap);
            g2.setFont(idFont);
            FontMetrics ifm = g2.getFontMetrics();
            int idX = x + (AlbumCard.CARD_W - ifm.stringWidth(cardId)) / 2;
            g2.setColor(new Color(90, 90, 90));
            g2.drawString(cardId, idX, bY + ifm.getAscent() + 2);

            String capPlayer = (cap.playerName != null && !cap.playerName.isEmpty()) ? cap.playerName : playerName;
            g2.setFont(playerFont);
            FontMetrics pfm = g2.getFontMetrics();
            String capLine = "Captured by: " + capPlayer;
            int capX = x + (AlbumCard.CARD_W - pfm.stringWidth(capLine)) / 2;
            g2.setColor(new Color(200, 155, 50));
            g2.drawString(capLine, capX, bY + ifm.getHeight() + pfm.getAscent() + 1);
        }
        g2.dispose();

        BufferedImage exported = img;
        Transferable t = new Transferable() {
            @Override public DataFlavor[] getTransferDataFlavors() { return new DataFlavor[]{DataFlavor.imageFlavor}; }
            @Override public boolean isDataFlavorSupported(DataFlavor f) { return DataFlavor.imageFlavor.equals(f); }
            @Override public Object getTransferData(DataFlavor f) throws java.awt.datatransfer.UnsupportedFlavorException {
                if (!DataFlavor.imageFlavor.equals(f)) throw new java.awt.datatransfer.UnsupportedFlavorException(f);
                return exported;
            }
        };
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(t, null);

        String prev = btn.getText();
        btn.setText("Copied! (" + count + ")");
        btn.setForeground(new Color(120, 200, 120));
        javax.swing.Timer timer = new javax.swing.Timer(2500, ev -> {
            btn.setText(prev);
            btn.setForeground(Color.WHITE);
        });
        timer.setRepeats(false);
        timer.start();
    }

}

package com.bestiary.ui;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.service.SessionTracker;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.awt.datatransfer.StringSelection;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * MODELESS dialog showing all captures logged since the last login.
 * Only one instance can be open at a time.
 */
public class SessionRecapDialog extends JDialog {

    private static final DateTimeFormatter TIME_FMT =
            DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());

    private static final CreatureRarity[] RARITY_ORDER = {
        CreatureRarity.MYTHIC, CreatureRarity.LEGENDARY, CreatureRarity.EPIC,
        CreatureRarity.RARE,   CreatureRarity.UNCOMMON,  CreatureRarity.COMMON
    };

    private static SessionRecapDialog current;

    public static void open(Window owner, SessionTracker tracker) {
        if (current != null && current.isShowing()) {
            current.dispose();
        }
        current = new SessionRecapDialog(owner, tracker);
    }

    private SessionRecapDialog(Window owner, SessionTracker tracker) {
        super(owner, "Session Recap", ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setResizable(true);
        build(tracker);
    }

    private void build(SessionTracker tracker) {
        List<CapturedCreature> captures = new ArrayList<>(tracker.getCaptures());

        long speciesCount = captures.stream().map(c -> c.npcName).distinct().count();
        Map<CreatureRarity, Long> rarityCounts = captures.stream()
                .collect(Collectors.groupingBy(c -> c.rarity, Collectors.counting()));
        CapturedCreature best = captures.stream()
                .max(Comparator.comparingInt((CapturedCreature c) -> c.rarity.ordinal())
                        .thenComparingInt(c -> c.powerLevel()))
                .orElse(null);

        // --- Header ---
        JPanel header = new JPanel(new BorderLayout(0, 3));
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(BorderFactory.createCompoundBorder(
                new MatteBorder(0, 4, 0, 0, new Color(255, 165, 0)),
                new EmptyBorder(10, 12, 10, 12)));

        JLabel titleLabel = new JLabel("Session Recap");
        titleLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(16f));
        titleLabel.setForeground(new Color(255, 165, 0));

        String subText = captures.isEmpty()
                ? "No captures this session yet"
                : captures.size() + " capture" + (captures.size() == 1 ? "" : "s")
                  + "  ·  " + speciesCount + " species"
                  + (best != null ? "  ·  Best: " + best.npcName + " " + best.rarity.label : "");
        JLabel subLabel = new JLabel(subText);
        subLabel.setFont(FontManager.getRunescapeSmallFont());
        subLabel.setForeground(best != null ? best.rarity.displayColor : ColorScheme.LIGHT_GRAY_COLOR);

        java.text.NumberFormat numFmt = java.text.NumberFormat.getNumberInstance(java.util.Locale.UK);
        long xpGained      = tracker.getXpGained();
        long creditsGained = tracker.getCreditsGained();
        int  killCount     = tracker.getKillCount();
        String statsLine = killCount + " kill" + (killCount == 1 ? "" : "s")
                + "  ·  " + numFmt.format(xpGained) + " XP"
                + "  ·  " + numFmt.format(creditsGained) + " credits";
        JLabel statsLabel = new JLabel(statsLine);
        statsLabel.setFont(FontManager.getRunescapeSmallFont());
        statsLabel.setForeground(new Color(130, 180, 130));

        JPanel subPanel = new JPanel(new GridLayout(2, 1, 0, 1));
        subPanel.setOpaque(false);
        subPanel.add(subLabel);
        subPanel.add(statsLabel);

        header.add(titleLabel, BorderLayout.NORTH);
        header.add(subPanel,   BorderLayout.CENTER);

        // --- Rarity pills ---
        JPanel pillRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        pillRow.setBackground(new Color(28, 28, 28));
        pillRow.setBorder(new EmptyBorder(4, 8, 6, 8));

        if (captures.isEmpty()) {
            JLabel empty = new JLabel("Go capture something to see your stats here.");
            empty.setFont(FontManager.getRunescapeSmallFont());
            empty.setForeground(new Color(70, 70, 70));
            pillRow.add(empty);
        } else {
            for (CreatureRarity r : RARITY_ORDER) {
                long n = rarityCounts.getOrDefault(r, 0L);
                if (n == 0) continue;
                pillRow.add(new RarityPill(r, (int) n));
            }
        }

        // --- Capture list ---
        JPanel listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        if (captures.isEmpty()) {
            JLabel noCaptures = new JLabel("  No captures recorded this session.");
            noCaptures.setFont(FontManager.getRunescapeSmallFont());
            noCaptures.setForeground(new Color(70, 70, 70));
            noCaptures.setBorder(new EmptyBorder(16, 0, 16, 0));
            noCaptures.setAlignmentX(Component.LEFT_ALIGNMENT);
            listPanel.add(noCaptures);
        } else {
            for (int i = 0; i < captures.size(); i++) {
                listPanel.add(buildCaptureRow(captures.get(i), i + 1, i % 2 == 1));
            }
        }

        int listH = Math.min(captures.size() * 34 + 8, 400);
        JScrollPane scroll = new JScrollPane(listPanel);
        scroll.setBorder(null);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setPreferredSize(new Dimension(500, Math.max(60, listH)));

        // --- Footer ---
        JButton copyBtn = new JButton("Copy Summary");
        copyBtn.setFont(FontManager.getRunescapeSmallFont());
        copyBtn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        copyBtn.setForeground(Color.WHITE);
        copyBtn.setFocusPainted(false);
        copyBtn.setEnabled(!captures.isEmpty());
        copyBtn.addActionListener(e -> {
            copyTextSummary(captures, speciesCount, rarityCounts, killCount, xpGained, creditsGained);
            copyBtn.setText("Copied!");
            copyBtn.setForeground(new Color(120, 200, 120));
            javax.swing.Timer t = new javax.swing.Timer(2000, ev -> {
                copyBtn.setText("Copy Summary");
                copyBtn.setForeground(Color.WHITE);
            });
            t.setRepeats(false);
            t.start();
        });

        JButton clearBtn = new JButton("Clear Session");
