        rarLabel.setFont(FontManager.getRunescapeSmallFont());
        rarLabel.setForeground(new Color(
                c.rarity.displayColor.getRed(),
                c.rarity.displayColor.getGreen(),
                c.rarity.displayColor.getBlue(), 160));

        left.add(indexLabel);
        left.add(nameLabel);
        left.add(rarLabel);

