@Slf4j
@Singleton
public class WikiImageService {

    private static final String API_BASE   = "https://oldschool.runescape.wiki/api.php";
    /** The ONLY host this plugin downloads from. Image URLs arrive in the wiki API response,
     *  so each is validated against this fixed host before being requested, keeping the
     *  plugin's network destinations statically verifiable (plugin-hub requirement). */
    private static final String WIKI_HOST  = "oldschool.runescape.wiki";
    private static final String USER_AGENT = "RuneLite Bestiary Plugin 1.0";
    private static final int    THUMB_W    = 130;
    private static final int    TIMEOUT_MS = 8000;
    private static final int    BATCH_SIZE = 50;

    /**
     * Maps our in-game NPC name to the correct OSRS Wiki page title when they differ.
     * The wiki API is case-sensitive on non-first characters, so "Rock crab" won't find
     * "Rock Crab". Disambiguation pages ("Troll", "Wyvern") also need directing.
     */
    private static final java.util.Map<String, String> WIKI_IMAGE_NAMES;
    static {
        java.util.Map<String, String> m = new java.util.HashMap<>();
        // Capitalisation differences (second word capitalised on wiki)
        m.put("Rock crab",           "Rock Crab");
        m.put("Sand crab",           "Sand Crab");
        m.put("Swamp crab",          "Swamp Crab");
        m.put("Gemstone crab",       "Gemstone Crab");
        m.put("King scorpion",       "King Scorpion");
        m.put("Twisted banshee",     "Twisted Banshee");
        m.put("Mutated bloodveld",   "Mutated Bloodveld");
        m.put("Greater nechryael",   "Greater Nechryael");
        m.put("Warped jelly",        "Warped Jelly");
        m.put("Basilisk knight",     "Basilisk Knight");
        m.put("Black knight",        "Black Knight");
        m.put("White knight",        "White Knight");
        m.put("Desert lizard",       "Desert Lizard");
        m.put("Infernal mage",       "Infernal Mage");
        m.put("Skeletal wyvern",     "Skeletal Wyvern");
        m.put("Ancient wyvern",      "Ancient Wyvern");
        m.put("Warped tortoise",     "Warped Tortoise");
        m.put("Feral vampyre",       "Feral Vampyre");
        m.put("Kalphite soldier",    "Kalphite Soldier");
        m.put("Kalphite guardian",   "Kalphite Guardian");
        m.put("Kalphite worker",     "Kalphite Worker");
        m.put("Dark warrior",        "Dark Warrior");
        // NOTE: "Ice warrior"/"Ice spider" are already the canonical wiki titles (lowercase
        // second word) — no mapping needed; forcing "Ice Warrior"/"Ice Spider" was a redirect
        // that pageimages can't resolve, so those were left out on purpose.
        // Name/structure differences
        m.put("Vampyre",             "Feral Vampyre");      // race overview page, not a monster
        // "Warrior" (in-game) = the Fremennik warriors of Rellekka, NOT the Al Kharid warriors.
        // Al Kharid warriors are a separate roster monster ("Al Kharid warrior") whose page title
        // matches its name, so it needs no mapping here.
        m.put("Warrior",             "Warrior (Rellekka)"); // disambiguation
        m.put("Wyvern",              "Skeletal Wyvern");     // disambiguation
        m.put("Kalphite",            "Kalphite Worker");     // disambiguation
        m.put("Maiden of Sugadinti", "The Maiden of Sugadinti");
        // Redirect targets / case fixes — pageimages doesn't follow redirects, so map to canonical.
        m.put("Hill giant",          "Hill Giant");
        m.put("Crazy Archaeologist", "Crazy archaeologist");
        m.put("Deranged Archaeologist","Deranged archaeologist");
        m.put("Hueycoatl",           "The Hueycoatl");
        m.put("Guardian",            "Guardian (Chambers of Xeric)"); // disambiguation (CoX statue)
        // "Troll" has no usable representative page — omit so it gets no image gracefully
        WIKI_IMAGE_NAMES = java.util.Collections.unmodifiableMap(m);
    }

    /**
     * Maps an in-game NPC name to a specific wiki <b>File</b> when the page's lead image can't be
     * used. Some pages' lead art is served as WebP, which {@link ImageIO} can't decode (e.g. the
     * active Mad Angel image), so no art ever appears. These entries are resolved via the
     * {@code imageinfo} API — which returns a thumbnail for that exact file — instead of
     * {@code pageimages}, letting us point at a decodable PNG/JPG upload of the same monster.
     */
    private static final java.util.Map<String, String> WIKI_IMAGE_FILES;
    static {
        java.util.Map<String, String> m = new java.util.HashMap<>();
        // Active Mad Angel art is a WebP (undecodable); the dormant version is a PNG.
        m.put("Mad Angel", "File:Mad Angel (dormant).png");
        WIKI_IMAGE_FILES = java.util.Collections.unmodifiableMap(m);
    }

    private final Map<String, BufferedImage>  cache            = new ConcurrentHashMap<>();
    private final Set<String>                pending          = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private final Set<String>                failed           = Collections.newSetFromMap(new ConcurrentHashMap<>());
    /** Callbacks registered while an image is mid-download; fired when the image lands. */
    private final Map<String, List<Runnable>> pendingCallbacks = new ConcurrentHashMap<>();

    /** Disk cache directory: ~/.runelite/bestiary/images/ — shared across all profiles. */
    private final File imageCacheDir;

    /**
     * Bump this whenever a {@link #WIKI_IMAGE_NAMES} mapping changes so previously downloaded
     * (now-wrong) art is purged from disk and re-fetched. Without this, the disk cache — checked
     * before the network — keeps serving the old image forever.
     *   gen 2: "Warrior" repointed from the Al Kharid warrior to the Fremennik warrior (Rellekka).
     */
    private static final int CACHE_GENERATION = 2;
    /** Disk-cached images (by NPC name) to delete when {@link #CACHE_GENERATION} advances. */
    private static final List<String> STALE_ON_UPGRADE = Collections.singletonList("Warrior");

    private final OkHttpClient httpClient;
    private final BestiaryConfig config;
    /** RuneLite's shared executor — client-owned, so we submit tasks but never shut it down. */
    private final ScheduledExecutorService executor;

    @Inject
    public WikiImageService(OkHttpClient httpClient, BestiaryConfig config, ScheduledExecutorService executor) {
        // Reuse RuneLite's shared OkHttp client, with our shorter timeouts.
        this.httpClient = httpClient.newBuilder()
                .connectTimeout(TIMEOUT_MS, TimeUnit.MILLISECONDS)
                .readTimeout(TIMEOUT_MS, TimeUnit.MILLISECONDS)
                .build();
        this.config = config;
        this.executor = executor;
        // RuneLite.RUNELITE_DIR is the canonical ~/.runelite location and honours a relocated
        // RuneLite home (-Drunelite.home), unlike a hardcoded user.home/.runelite path.
        imageCacheDir = new File(net.runelite.client.RuneLite.RUNELITE_DIR,
                "bestiary" + File.separator + "images");
        purgeStaleImages();
    }

    /**
     * One-time-per-upgrade cleanup: if the stored cache generation is older than
     * {@link #CACHE_GENERATION}, delete the images whose wiki mapping has since changed so they
     * re-download with the correct art, then record the new generation. A tiny marker file in the
     * cache dir tracks the last-seen generation, so this runs at most once per user per bump.
     */
    private void purgeStaleImages() {
        File marker = new File(imageCacheDir, ".cache-generation");
        int stored = 0;
        try {
            if (marker.isFile()) {
                stored = Integer.parseInt(
                        new String(java.nio.file.Files.readAllBytes(marker.toPath()), StandardCharsets.UTF_8).trim());
            }
        } catch (Exception e) {
            stored = 0;   // unreadable/corrupt marker → treat as oldest, re-run the purge
        }
        if (stored >= CACHE_GENERATION) return;

        for (String name : STALE_ON_UPGRADE) {
            File f = diskFile(name);
            if (f.isFile() && !f.delete()) {
                log.debug("WikiImageService: could not delete stale cached image '{}'", f);
            }
        }
        try {
            imageCacheDir.mkdirs();
            java.nio.file.Files.write(marker.toPath(),
                    String.valueOf(CACHE_GENERATION).getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            log.debug("WikiImageService: could not write cache-generation marker: {}", e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /**
     * Batch-prefetches images for a list of NPC names. Loads from disk cache
     * first; only fetches from network what isn't on disk. {@code onEachLoad}
     * is called via invokeLater each time an image arrives.
     */
    public void prefetchBatch(List<String> names, Runnable onEachLoad) {
        // Load from disk synchronously (fast — just file I/O) before scheduling network
        List<String> diskMisses = new ArrayList<>();
        for (String name : names) {
            if (cache.containsKey(name) || failed.contains(name) || pending.contains(name)) continue;
            BufferedImage img = loadFromDisk(name);
            if (img != null) {
                cache.put(name, img);
                SwingUtilities.invokeLater(onEachLoad);
            } else {
                diskMisses.add(name);
            }
        }

        List<String> toFetch = diskMisses.stream()
                .filter(n -> !cache.containsKey(n) && !failed.contains(n) && pending.add(n))
                .collect(Collectors.toList());
        if (toFetch.isEmpty()) return;

        // Respect the user's wiki-fetch toggle — no network when disabled.
        if (!config.wikiImages()) {
            toFetch.forEach(pending::remove);
            return;
        }

        // One short background task on RuneLite's shared executor resolves the thumbnail URLs (a few
        // batched calls), then hands the actual image downloads to OkHttp's async dispatcher via
        // enqueue(). The dispatcher runs several downloads concurrently (capped per-host) on the
        // shared client's own threads — so we get parallelism back without owning any threads, using
        // the common ForkJoinPool, or blocking one of the shared executor's threads for the whole run.
        executor.execute(() -> {
            Map<String, String> urlsByName = new LinkedHashMap<>();
            for (int i = 0; i < toFetch.size(); i += BATCH_SIZE) {
                List<String> chunk = toFetch.subList(i, Math.min(i + BATCH_SIZE, toFetch.size()));
                try {
                    urlsByName.putAll(fetchThumbUrlBatch(chunk));
                } catch (Exception e) {
                    log.warn("WikiImageService: batch URL fetch failed (chunk {})", i / BATCH_SIZE, e);
                }
                for (String n : chunk) {
                    if (!urlsByName.containsKey(n)) {
                        failed.add(n);
                        pending.remove(n);
                    }
                }
            }

            for (Map.Entry<String, String> entry : urlsByName.entrySet()) {
                downloadImageAsync(entry.getKey(), entry.getValue(), onEachLoad);
            }
        });
    }

    /**
     * Downloads one image via OkHttp's async dispatcher (RuneLite's shared client). Concurrency and
     * per-host limits are managed by the dispatcher, so many of these can be in flight at once without
     * the plugin creating threads or holding a shared executor thread. The callback lands the image
     * into the cache and repaints as each one arrives; {@code pending} is always cleared.
     */
    private void downloadImageAsync(String npcName, String imageUrl, Runnable onEachLoad) {
        if (!isAllowedImageUrl(imageUrl)) {   // never call a host we didn't hardcode
            failed.add(npcName);
            pending.remove(npcName);
            return;
        }
        Request request = new Request.Builder().url(imageUrl).header("User-Agent", USER_AGENT).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                failed.add(npcName);
                pending.remove(npcName);
            }

            @Override
            public void onResponse(Call call, Response response) {
                try (Response resp = response) {
                    BufferedImage img = null;
                    if (resp.isSuccessful() && resp.body() != null) {
                        try (InputStream is = resp.body().byteStream()) {
                            img = ImageIO.read(is);
                        }
                    }
                    if (img != null) {
                        cache.put(npcName, img);
                        saveToDisk(npcName, img);
                        SwingUtilities.invokeLater(onEachLoad);
                        firePendingCallbacks(npcName);
                    } else {
                        failed.add(npcName);
                    }
                } catch (Exception e) {
                    failed.add(npcName);
                } finally {
                    pending.remove(npcName);
                }
            }
        });
    }

    /**
     * Asynchronously fetches a single NPC image. Checks memory cache, then disk
     * cache, then network. {@code onLoad} is called via invokeLater when ready.
     */
    /** Whether wiki images are enabled by config. When false, cards fall back to placeholders. */
    public boolean isEnabled() {
        return config.wikiImages();
    }

    public void requestImage(String npcName, Runnable onLoad) {
        if (cache.containsKey(npcName)) {
            onLoad.run();
            return;
        }
        if (failed.contains(npcName)) return;

        // Disk cache is always available — even when the fetch toggle is off — so previously
        // synced images keep showing after a player opts out.
        BufferedImage disk = loadFromDisk(npcName);
        if (disk != null) {
            cache.put(npcName, disk);
            onLoad.run();
            return;
        }

        // Anything not already on disk requires a network fetch — only when the user has opted in.
        if (!config.wikiImages()) return;

        if (!pending.add(npcName)) {
            pendingCallbacks.computeIfAbsent(npcName, k -> Collections.synchronizedList(new ArrayList<>())).add(onLoad);
            return;
        }

        executor.execute(() -> {
            try {
                String thumbUrl = fetchThumbUrlSingle(npcName);
                if (thumbUrl == null) { failed.add(npcName); return; }
                BufferedImage img = downloadImage(thumbUrl);
                if (img == null) { failed.add(npcName); return; }
                cache.put(npcName, img);
                saveToDisk(npcName, img);
                SwingUtilities.invokeLater(onLoad);
                firePendingCallbacks(npcName);
            } catch (Exception e) {
                log.warn("WikiImageService: failed to fetch image for '{}'", npcName, e);
                failed.add(npcName);
            } finally {
                pending.remove(npcName);
            }
        });
    }

    @Nullable
    public BufferedImage getImage(String npcName) {
        // Always show images we already have — the fetch toggle governs NETWORK access, not display.
        // Disk-cached art is local data, so a player can sync once, opt out, and keep their images
        // (and opt back in later to fetch newly added monsters).
        return cache.get(npcName);
    }

    // -------------------------------------------------------------------------
    // Disk cache helpers
    // -------------------------------------------------------------------------

    private File diskFile(String npcName) {
        // Sanitize name to a safe filename; spaces → underscores, drop non-safe chars
        String safe = npcName.replaceAll("[^a-zA-Z0-9_\\-]", "_");
        return new File(imageCacheDir, safe + ".png");
    }

    @Nullable
    private BufferedImage loadFromDisk(String npcName) {
        File f = diskFile(npcName);
        if (!f.exists()) return null;
        try {
            return ImageIO.read(f);
        } catch (Exception e) {
            log.debug("WikiImageService: disk cache read failed for '{}': {}", npcName, e.getMessage());
            return null;
        }
    }

    private void saveToDisk(String npcName, BufferedImage img) {
        try {
            imageCacheDir.mkdirs();
            ImageIO.write(img, "PNG", diskFile(npcName));
        } catch (Exception e) {
            log.debug("WikiImageService: disk cache write failed for '{}': {}", npcName, e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Internals
    // -------------------------------------------------------------------------

    /**
     * True only for https URLs on the hardcoded wiki host. Thumbnail URLs are read from the
     * wiki API response, so every one passes through here before any request is made — the
     * plugin can therefore only ever contact {@link #WIKI_HOST}, verifiable by static review.
     */
    private static boolean isAllowedImageUrl(String url) {
        HttpUrl parsed = url == null ? null : HttpUrl.parse(url);
        return parsed != null && "https".equals(parsed.scheme()) && WIKI_HOST.equals(parsed.host());
    }

    private Map<String, String> fetchThumbUrlBatch(List<String> names) throws Exception {
        // Names with a specific-file override resolve via imageinfo, not pageimages.
        Map<String, String> result = new LinkedHashMap<>();
        List<String> pageImageNames = new ArrayList<>();
        List<String> fileOverrideNames = new ArrayList<>();
        for (String n : names) {
            (WIKI_IMAGE_FILES.containsKey(n) ? fileOverrideNames : pageImageNames).add(n);
        }
        if (!fileOverrideNames.isEmpty()) result.putAll(fetchFileThumbUrls(fileOverrideNames));
        if (pageImageNames.isEmpty()) return result;

        // Translate NPC names to wiki page titles; keep a reverse map for results
        Map<String, String> lowerToName = new LinkedHashMap<>();
        List<String> queryTitles = new ArrayList<>();
        for (String n : pageImageNames) {
            String wikiTitle = WIKI_IMAGE_NAMES.getOrDefault(n, n);
            queryTitles.add(wikiTitle);
            lowerToName.put(wikiTitle.toLowerCase(), n);
            lowerToName.put(n.toLowerCase(), n); // keep original as fallback
        }

        StringBuilder titlesParam = new StringBuilder();
        for (int i = 0; i < queryTitles.size(); i++) {
            if (i > 0) titlesParam.append("%7C");
            titlesParam.append(URLEncoder.encode(queryTitles.get(i), StandardCharsets.UTF_8.name()));
        }

        String urlStr = API_BASE + "?action=query&titles=" + titlesParam
                + "&prop=pageimages&piprop=thumbnail&pithumbsize=" + THUMB_W + "&format=json";

        String json;
        Request request = new Request.Builder().url(urlStr).header("User-Agent", USER_AGENT).build();
        try (Response resp = httpClient.newCall(request).execute()) {
            if (!resp.isSuccessful() || resp.body() == null) return result;
            json = resp.body().string();
        }

        JsonObject root  = new JsonParser().parse(json).getAsJsonObject();
        JsonObject query = root.has("query") ? root.getAsJsonObject("query") : null;
        if (query == null) return result;

        if (query.has("normalized")) {
            JsonArray normalised = query.getAsJsonArray("normalized");
            for (JsonElement el : normalised) {
                JsonObject norm = el.getAsJsonObject();
                String from = norm.get("from").getAsString().toLowerCase();
                String to   = norm.get("to").getAsString().toLowerCase();
                String originalName = lowerToName.get(from);
                if (originalName != null) {
                    lowerToName.put(to, originalName);
                }
            }
        }

        JsonObject pages = query.has("pages") ? query.getAsJsonObject("pages") : null;
        if (pages == null) return result;

        for (Map.Entry<String, JsonElement> entry : pages.entrySet()) {
            JsonObject page = entry.getValue().getAsJsonObject();
            if (page.has("missing")) continue;
            String pageTitle = page.get("title").getAsString();
            String origName  = lowerToName.get(pageTitle.toLowerCase());
            if (origName != null && page.has("thumbnail")) {
                String source = page.getAsJsonObject("thumbnail").get("source").getAsString();
                if (isAllowedImageUrl(source)) {
                    result.put(origName, source);
                } else {
                    log.warn("WikiImageService: ignoring off-host image URL for '{}': {}", origName, source);
                }
            }
        }
        return result;
    }

    /**
     * Resolves NPC names that use a specific wiki File (see {@link #WIKI_IMAGE_FILES}) via the
     * {@code imageinfo} API, which returns a thumbnail URL for that exact file — unlike
     * {@code pageimages}, which only ever returns a page's lead image.
     */
    private Map<String, String> fetchFileThumbUrls(List<String> names) throws Exception {
        Map<String, String> fileToName = new LinkedHashMap<>();
        List<String> titles = new ArrayList<>();
        for (String n : names) {
            String file = WIKI_IMAGE_FILES.get(n);
            titles.add(file);
            fileToName.put(file.toLowerCase(), n);
        }

        StringBuilder titlesParam = new StringBuilder();
        for (int i = 0; i < titles.size(); i++) {
            if (i > 0) titlesParam.append("%7C");
            titlesParam.append(URLEncoder.encode(titles.get(i), StandardCharsets.UTF_8.name()));
        }

        String urlStr = API_BASE + "?action=query&titles=" + titlesParam
                + "&prop=imageinfo&iiprop=url&iiurlwidth=" + THUMB_W + "&format=json";

        String json;
        Request request = new Request.Builder().url(urlStr).header("User-Agent", USER_AGENT).build();
        try (Response resp = httpClient.newCall(request).execute()) {
            if (!resp.isSuccessful() || resp.body() == null) return Collections.emptyMap();
            json = resp.body().string();
        }

        JsonObject root  = new JsonParser().parse(json).getAsJsonObject();
        JsonObject query = root.has("query") ? root.getAsJsonObject("query") : null;
        if (query == null) return Collections.emptyMap();

        if (query.has("normalized")) {
            for (JsonElement el : query.getAsJsonArray("normalized")) {
                JsonObject norm = el.getAsJsonObject();
                String from = norm.get("from").getAsString().toLowerCase();
                String to   = norm.get("to").getAsString().toLowerCase();
                String originalName = fileToName.get(from);
                if (originalName != null) fileToName.put(to, originalName);
            }
        }

        Map<String, String> result = new LinkedHashMap<>();
        JsonObject pages = query.has("pages") ? query.getAsJsonObject("pages") : null;
        if (pages == null) return result;

        for (Map.Entry<String, JsonElement> entry : pages.entrySet()) {
            JsonObject page = entry.getValue().getAsJsonObject();
            if (page.has("missing") || !page.has("imageinfo")) continue;
            String pageTitle = page.get("title").getAsString();
            String origName  = fileToName.get(pageTitle.toLowerCase());
            if (origName == null) continue;
            JsonArray info = page.getAsJsonArray("imageinfo");
            if (info.size() == 0) continue;
            JsonObject ii = info.get(0).getAsJsonObject();
            // iiurlwidth yields a scaled "thumburl"; fall back to the full-size "url".
            String source = ii.has("thumburl") ? ii.get("thumburl").getAsString()
                          : ii.has("url")      ? ii.get("url").getAsString() : null;
            if (source == null) continue;
            if (isAllowedImageUrl(source)) {
                result.put(origName, source);
            } else {
                log.warn("WikiImageService: ignoring off-host image URL for '{}': {}", origName, source);
            }
        }
        return result;
    }

    @Nullable
    private String fetchThumbUrlSingle(String npcName) throws Exception {
        Map<String, String> result = fetchThumbUrlBatch(Collections.singletonList(npcName));
        return result.get(npcName);
    }

    @Nullable
    private BufferedImage downloadImage(String imageUrl) throws Exception {
        if (!isAllowedImageUrl(imageUrl)) return null;   // never call a host we didn't hardcode
        Request request = new Request.Builder().url(imageUrl).header("User-Agent", USER_AGENT).build();
        try (Response resp = httpClient.newCall(request).execute()) {
            if (!resp.isSuccessful() || resp.body() == null) return null;
            try (InputStream is = resp.body().byteStream()) {
                return ImageIO.read(is);
            }
        }
    }

    private void firePendingCallbacks(String npcName) {
        List<Runnable> callbacks = pendingCallbacks.remove(npcName);
        if (callbacks != null) {
            for (Runnable cb : callbacks) SwingUtilities.invokeLater(cb);
        }
    }
}

package com.bestiary.service;

import com.google.gson.Gson;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import com.bestiary.model.CapturedCreature;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Pure-Java JSON persistence for the bestiary (no native dependencies — Plugin Hub safe).
 *
 * <p>Collections are keyed <b>per account</b> (#47): each account has its own file at
 * {@code ~/.runelite/bestiary/accounts/<accountHash>.json} (+ a {@code .bak}), keyed by
 * RuneLite's stable {@code accountHash} (survives name changes). No account is active until
 * {@link #setActiveAccount} is called on login — before that, loads return empty and saves
 * are dropped, so no account's data is ever touched while logged out.
 *
 * <p>The whole collection lives in memory in {@link BestiaryDataService}; this store just
 * loads and saves a single JSON snapshot for the active account. Writes are debounced onto a
 * background thread (bursts of kills/credits coalesce into one write ~1s later) and are
 * crash-safe: each write goes to a temp file, the previous good file is copied to a
 * {@code .bak}, then the temp is atomically renamed into place. Load falls back to the backup
 * if the main file is missing or corrupt.
 */
@Slf4j
@Singleton
public class BestiaryStore {

    /**
     * Bump when the on-disk shape changes incompatibly. A file whose {@code version} doesn't match
     * is discarded on load (clean-slate reset) rather than migrated.
     * v2: Prayer folded into {@link com.bestiary.model.CreatureQuality} as the 7th stat.
     */
    public static final int VERSION = 2;

    private static final long DEBOUNCE_MS = 1000;

    /** Serialized snapshot of everything we persist. */
    public static class StoreData {
        public int version = VERSION;
        public List<CapturedCreature> captures = new ArrayList<>();
        public Map<String, Integer> killCounts = new LinkedHashMap<>();
        public long credits;
        public long lifetimeCreditsEarned;
        public long lifetimeCreditsSpent;
        /** Lifetime captures this account personally made — never decremented by discard/transfer. */
        public long lifetimeCaptures;
        /** Per-species lifetime captures (npcName -> count), same monotonic semantics. */
        public Map<String, Integer> lifetimeCapturesByNpc = new LinkedHashMap<>();
        /** Total cards this account has sent away via transfer. */
        public long lifetimeCardsSent;

        /** Total cards this account has discarded for credits. */
        public long lifetimeCardsDiscarded;
        /** True once a shiny / a Legendary+ / a Mythic has ever been discarded (discard achievements can't backfill). */
        public boolean discardedShiny;
        public boolean discardedLegendary;
        public boolean discardedMythic;
        /** Largest credit haul from a single discard action. */
        public long largestDiscardBatch;
        public long totalXp;
        public List<String> achievements = new ArrayList<>();
        public Map<String, Integer> shopUpgrades = new LinkedHashMap<>();
    }

    /** One row of the account registry ({@code index.json}) — drives the future account switcher (#48). */
    static class AccountEntry {
        public String rsn;
        public long lastActive;
    }

    private final File dir;
    private final File accountsDir;
    private final File indexFile;
    private final Gson gson;

    /** Active account's target files — null until {@link #setActiveAccount} is called on login. */
    private volatile File file;
    private volatile File backup;
    private volatile Long activeHash;

    /** RuneLite's shared executor — the client owns its lifecycle, so we never shut it down. */
    private final ScheduledExecutorService executor;
    private final Object lock = new Object();
    private StoreData pending;              // guarded by lock
    // The write target is captured alongside the buffered data at save() time, so a debounced write
    // always lands in the file that was active when the data was buffered — even if the active
    // account is repointed (setActiveAccount) before the background writer runs.
    private File pendingFile;               // guarded by lock
    private File pendingBackup;             // guarded by lock
    private ScheduledFuture<?> scheduled;   // guarded by lock

    @Inject
    public BestiaryStore(Gson gson, ScheduledExecutorService executor) {
        // RuneLite.RUNELITE_DIR is the canonical ~/.runelite location; prefer it over a hand-rolled
        // user.home/.runelite path so we follow the client if it ever relocates the home dir.
        this(gson, executor, net.runelite.client.RuneLite.RUNELITE_DIR);
    }

    /**
     * Visible for testing: lets tests point storage at a temp directory. RUNELITE_DIR is resolved
     * once at class load, so a runtime {@code user.home} override can't redirect it.
     */
    BestiaryStore(Gson gson, ScheduledExecutorService executor, File runeliteDir) {
        this.executor    = executor;
        this.dir         = new File(runeliteDir, "bestiary");
        this.accountsDir = new File(dir, "accounts");
        this.indexFile   = new File(accountsDir, "index.json");
        // Reuse RuneLite's Gson config, adding an Instant<->epoch-second adapter.
        this.gson = gson.newBuilder()
                .registerTypeAdapter(Instant.class, new InstantEpochAdapter())
                .setPrettyPrinting()
                .create();
        archiveLegacyGlobalFile();
    }

    // -------------------------------------------------------------------------
    // Account selection
    // -------------------------------------------------------------------------

    /**
     * Points the store at {@code accountHash}'s file for all subsequent loads/saves. Flushes any
     * pending write for the previously active account to its own file first, so a switch can never
     * spill one account's buffered data into another's file. Records the account in the registry.
     */
    public void setActiveAccount(long accountHash, String rsn) {
        flushPending();                 // write buffered data to the OLD file before repointing
        this.activeHash = accountHash;
        this.file   = new File(accountsDir, accountHash + ".json");
        this.backup = new File(accountsDir, accountHash + ".json.bak");
        recordAccount(accountHash, rsn);
    }

    /** True once an account has been selected (i.e. the player has logged in this session). */
    public boolean hasActiveAccount() {
        return activeHash != null;
    }

    /**
     * Deactivates the current account on logout: flushes any buffered write to its file, then stops
     * targeting any file so subsequent saves are dropped until the next login. Prevents a logged-out
     * client from ever writing to (or being loaded from) an account's file.
     */
    public void clearActiveAccount() {
        flushPending();
        this.activeHash = null;
        this.file = null;
        this.backup = null;
    }

    // -------------------------------------------------------------------------
    // Load
    // -------------------------------------------------------------------------

    /** Reads the active account's collection (main file then backup); empty if none active/usable. */
    public StoreData load() {
        if (file == null) return new StoreData();
        StoreData d = tryRead(file);
        if (d == null) {
            d = tryRead(backup);
            if (d != null) log.warn("Bestiary main file unreadable; recovered from backup");
        }
        if (d == null) return new StoreData();
        if (d.version != VERSION) {
            log.info("Bestiary store version {} != {}; starting this account fresh (data reset)",
                    d.version, VERSION);
            return new StoreData();
        }
        if (d.captures == null)    d.captures = new ArrayList<>();
        if (d.killCounts == null)  d.killCounts = new LinkedHashMap<>();
        if (d.achievements == null) d.achievements = new ArrayList<>();
        if (d.shopUpgrades == null) d.shopUpgrades = new LinkedHashMap<>();
        if (d.lifetimeCapturesByNpc == null) d.lifetimeCapturesByNpc = new LinkedHashMap<>();
        return d;
    }

    private StoreData tryRead(File f) {
        if (f == null || !f.exists()) return null;
        try {
            String json = new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
            return gson.fromJson(json, StoreData.class);
        } catch (Exception e) {
            log.error("Failed to read bestiary store {}", f, e);
            return null;
        }
    }

    // -------------------------------------------------------------------------
    // Save
    // -------------------------------------------------------------------------

    /** Debounced save — coalesces bursts and writes ~1s after the last change on a background thread. */
    public void save(StoreData data) {
        File f = file, b = backup;   // snapshot the active target as of this call
        if (f == null) return;       // no active account — nothing to persist
        synchronized (lock) {
            pending = data;
            pendingFile = f;
            pendingBackup = b;
            if (scheduled == null || scheduled.isDone()) {
                scheduled = executor.schedule(this::flush, DEBOUNCE_MS, TimeUnit.MILLISECONDS);
            }
        }
    }

    /** Immediate synchronous save (shutdown / wipe / user-initiated). Cancels any pending debounce. */
    public void saveNow(StoreData data) {
        File f = file, b = backup;   // snapshot the active target as of this call
        if (f == null) return;       // no active account — nothing to persist
        synchronized (lock) {
            if (scheduled != null) scheduled.cancel(false);
            pending = null;
            pendingFile = null;
            pendingBackup = null;
        }
        writeTo(f, b, data);
    }

    private void flush() {
        StoreData d; File f, b;
        synchronized (lock) {
            d = pending; f = pendingFile; b = pendingBackup;
            pending = null; pendingFile = null; pendingBackup = null;
        }
        if (d != null && f != null) writeTo(f, b, d);
    }

    /**
     * Writes any debounced-but-unwritten snapshot to the file it was buffered for, synchronously.
     * Called before an account repoint (setActiveAccount) and on logout, so the previous account's
     * buffered data is committed to its own file first.
     */
    private void flushPending() {
        StoreData d; File f, b;
        synchronized (lock) {
            if (scheduled != null) scheduled.cancel(false);
            d = pending; f = pendingFile; b = pendingBackup;
            pending = null; pendingFile = null; pendingBackup = null;
        }
        if (d != null && f != null) writeTo(f, b, d);
    }

    /** Crash-safe write of {@code d} to {@code target} (temp file → back up previous → atomic rename). */
    private synchronized boolean writeTo(File target, File bak, StoreData d) {
        try {
            Files.createDirectories(accountsDir.toPath());
            Path tmp = target.toPath().resolveSibling(target.getName() + ".tmp");
            Files.write(tmp, gson.toJson(d).getBytes(StandardCharsets.UTF_8));
            if (target.exists()) {
                Files.copy(target.toPath(), bak.toPath(), StandardCopyOption.REPLACE_EXISTING);
            }
            try {
                Files.move(tmp, target.toPath(),
                        StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            } catch (IOException atomicUnsupported) {
                Files.move(tmp, target.toPath(), StandardCopyOption.REPLACE_EXISTING);
            }
            return true;
        } catch (IOException e) {
            log.error("Failed to write bestiary store {}", target, e);
            return false;
        }
    }

    // -------------------------------------------------------------------------
    // Arbitrary-account access (for card transfer, #50)
    // -------------------------------------------------------------------------

    /** Reads another account's collection read-only (never the active file's in-memory state). */
    public StoreData readAccount(long accountHash) {
        StoreData d = tryRead(new File(accountsDir, accountHash + ".json"));
        if (d == null) d = tryRead(new File(accountsDir, accountHash + ".json.bak"));
        if (d == null) return new StoreData();
        if (d.captures == null)     d.captures = new ArrayList<>();
        if (d.killCounts == null)   d.killCounts = new LinkedHashMap<>();
        if (d.achievements == null) d.achievements = new ArrayList<>();
        if (d.shopUpgrades == null) d.shopUpgrades = new LinkedHashMap<>();
        if (d.lifetimeCapturesByNpc == null) d.lifetimeCapturesByNpc = new LinkedHashMap<>();
        return d;
    }

    /**
     * Synchronously writes a specific account's file (used to deposit transferred cards, #50). Must
     * only be used for a NON-active account so it can't race the debounced writer for the active file.
     */
    public boolean writeAccountNow(long accountHash, StoreData data) {
        return writeTo(new File(accountsDir, accountHash + ".json"),
                new File(accountsDir, accountHash + ".json.bak"), data);
    }

    /** A known account from the registry — accountHash + last-known RSN + last-active epoch. */
    public static final class AccountRef {
        public final long   hash;
        public final String rsn;
        public final long   lastActive;
        AccountRef(long hash, String rsn, long lastActive) {
            this.hash = hash; this.rsn = rsn; this.lastActive = lastActive;
        }
    }

    /** All accounts recorded in the registry (index.json), most-recently-active first. */
    public List<AccountRef> listAccounts() {
        List<AccountRef> out = new ArrayList<>();
        for (Map.Entry<String, AccountEntry> e : readIndex().entrySet()) {
            try {
                long h = Long.parseLong(e.getKey());
                AccountEntry v = e.getValue();
                out.add(new AccountRef(h, v != null ? v.rsn : null, v != null ? v.lastActive : 0));
            } catch (NumberFormatException ignored) { /* skip malformed key */ }
        }
        out.sort((a, b) -> Long.compare(b.lastActive, a.lastActive));
        return out;
    }

    /**
     * Commit any debounced-but-unwritten snapshot synchronously. Call from plugin shutDown.
     * The executor is RuneLite's shared one, so we cancel our pending task but never shut it down.
     */
    public void close() {
        flushPending();
    }

    // -------------------------------------------------------------------------
    // Migration + registry
    // -------------------------------------------------------------------------

    /**
     * One-time clean-slate migration: the pre-#47 build kept a single global {@code bestiary.json}
     * shared by every account. Rename it (and its backup) to a dated {@code bestiary.legacy-*} file
     * so it is never loaded again but stays recoverable. Because we move it, this runs only once.
     */
    private void archiveLegacyGlobalFile() {
        File legacy = new File(dir, "bestiary.json");
        if (!legacy.exists()) return;
        try {
            String stamp = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
            File archived = new File(dir, "bestiary.legacy-" + stamp + ".json");
            for (int n = 1; archived.exists(); n++) {
                archived = new File(dir, "bestiary.legacy-" + stamp + "-" + n + ".json");
            }
            Files.move(legacy.toPath(), archived.toPath());
            File legacyBak = new File(dir, "bestiary.json.bak");
            if (legacyBak.exists()) {
                Files.move(legacyBak.toPath(), new File(dir, archived.getName() + ".bak").toPath(),
                        StandardCopyOption.REPLACE_EXISTING);
            }
            log.info("Archived legacy global collection to {} (per-account storage is now active)",
                    archived.getName());
        } catch (IOException e) {
            log.error("Failed to archive legacy global bestiary file", e);
        }
    }

    /** Upserts an account into the registry with a fresh {@code lastActive} timestamp. */
    private synchronized void recordAccount(long accountHash, String rsn) {
        try {
            Files.createDirectories(accountsDir.toPath());
            Map<String, AccountEntry> index = readIndex();
            AccountEntry e = index.computeIfAbsent(String.valueOf(accountHash), k -> new AccountEntry());
            if (rsn != null && !rsn.isEmpty()) e.rsn = rsn;
            e.lastActive = Instant.now().getEpochSecond();
            Files.write(indexFile.toPath(), gson.toJson(index).getBytes(StandardCharsets.UTF_8));
        } catch (Exception ex) {
            log.warn("Failed to update account registry", ex);
        }
    }

    private Map<String, AccountEntry> readIndex() {
        if (!indexFile.exists()) return new LinkedHashMap<>();
        try {
            String json = new String(Files.readAllBytes(indexFile.toPath()), StandardCharsets.UTF_8);
            Type t = new TypeToken<LinkedHashMap<String, AccountEntry>>() {}.getType();
            Map<String, AccountEntry> m = gson.fromJson(json, t);
            return m != null ? m : new LinkedHashMap<>();
        } catch (Exception e) {
            log.warn("Failed to read account registry; starting fresh", e);
            return new LinkedHashMap<>();
        }
    }

    // -------------------------------------------------------------------------

    /** Stores/reads {@link Instant} as an epoch-second number (compact + matches the old DB). */
    private static final class InstantEpochAdapter
            implements JsonSerializer<Instant>, JsonDeserializer<Instant> {
        @Override
        public JsonElement serialize(Instant src, Type type, JsonSerializationContext ctx) {
            return new JsonPrimitive(src.getEpochSecond());
        }
        @Override
        public Instant deserialize(JsonElement json, Type type, JsonDeserializationContext ctx) {
            return Instant.ofEpochSecond(json.getAsLong());
        }
    }
}

package com.bestiary.service;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.game.NpcUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Tracks which NPCs the local player is fighting and confirms kills.
 *
 * Kill signal:     {@link ActorDeath} fires when any actor's health hits 0.
 * Combat tracking: {@link HitsplatApplied} with {@code hitsplat.isMine()} — only NPCs the
 *                  local player has dealt at least 1 damage to are eligible for a kill credit.
 *                  InteractingChanged is intentionally NOT used: clicking a monster in
 *                  single combat (0 damage dealt) must not award a kill.
 *
 * Event order: the game decides whether the killing blow's hitsplat or the health bar hitting 0
 * (→ ActorDeath) is processed first within a tick, and it flipped in RuneLite 1.13.0 (death now
 * arrives BEFORE the killing hitsplat). So a death is only noted when it arrives and settled on
 * {@link #onGameTick()}, once every hitsplat of that tick has landed — correct in either order.
 */
@Slf4j
@Singleton
public class KillTracker {

    /** A confirmed player kill and the total damage the player dealt to it ("observed HP"). */
    public static final class Kill {
        public final NPC npc;
        public final int damage;

        Kill(NPC npc, int damage) {
            this.npc = npc;
            this.damage = damage;
        }
    }

    private final Client client;
    private final NpcUtil npcUtil;

    /**
     * NPCs the local player has dealt damage to, keyed by NPC index.
     * An NPC present here when its death settles is attributed as a player kill.
     */
    private final Map<Integer, NPC> attackedNpcs = new HashMap<>();

    /** Total damage the local player has dealt to each NPC (by index) — the "observed HP". */
    private final Map<Integer, Integer> damageDealt = new HashMap<>();

    /** NPCs whose ActorDeath arrived this tick, waiting for the tick's remaining hitsplats. */
    private final Map<Integer, NPC> pendingDeaths = new LinkedHashMap<>();

    /**
     * NPCs whose death has settled but that haven't despawned yet (by index). A hit landing during
     * the death animation (next attack, cannon ball) must NOT re-track the corpse — otherwise the
     * finisher path in {@link #onNpcDespawned} sees a tracked, dying NPC and credits it again.
     */
    private final Set<Integer> settledDeaths = new HashSet<>();

    @Inject
    public KillTracker(Client client, NpcUtil npcUtil) {
        this.client = client;
        this.npcUtil = npcUtil;
    }

    /**
     * Tracks NPCs the player damages. {@code isMine()} is true only for hitsplats
     * generated by the local player's attacks.
     */
    public void onHitsplatApplied(HitsplatApplied event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC)) {
            return;
        }
        if (!event.getHitsplat().isMine()) {
            return;
        }
        NPC npc = (NPC) actor;
        if (settledDeaths.contains(npc.getIndex())) {
            if (npc.isDead()) {
                return; // corpse of a kill already settled — ignore post-death hits
            }
            // Health bar refilled without a despawn (e.g. Kalphite Queen phase 2, Phantom Muspah):
            // RuneLite clears isDead(), so treat it as a new life that can be killed again.
            settledDeaths.remove(npc.getIndex());
        }
        attackedNpcs.put(npc.getIndex(), npc);
        damageDealt.merge(npc.getIndex(), event.getHitsplat().getAmount(), Integer::sum);
        log.debug("Hitsplat on {} (index {})", npc.getName(), npc.getIndex());
    }

    /**
     * Notes an NPC death. Not credited yet — the killing blow's hitsplat may still arrive later
     * in this same tick. {@link #onGameTick()} settles it.
     */
    public void onActorDeath(ActorDeath event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC)) {
            return;
        }
        NPC npc = (NPC) actor;
        if (!settledDeaths.contains(npc.getIndex())) {
            pendingDeaths.put(npc.getIndex(), npc);
        }
    }

    /**
     * Settles this tick's deaths, by which point all of the tick's hitsplats have landed.
     * Returns the ones the local player caused.
     */
    public List<Kill> onGameTick() {
        if (pendingDeaths.isEmpty()) {
            return java.util.Collections.emptyList();
        }
        List<Kill> kills = new ArrayList<>();
        for (Map.Entry<Integer, NPC> e : pendingDeaths.entrySet()) {
            Kill kill = settle(e.getKey(), e.getValue());
            if (kill != null) {
                kills.add(kill);
            }
        }
        pendingDeaths.clear();
        return kills;
    }

    /** Marks a death as settled and returns it as a kill if the player had damaged it. */
    private Kill settle(int index, NPC npc) {
        settledDeaths.add(index);
        NPC tracked = attackedNpcs.remove(index);
        Integer dmg = damageDealt.remove(index);
        if (tracked == null) {
            return null;
        }
        int damage = dmg != null ? dmg : 0;
        log.debug("Kill confirmed via ActorDeath: {} (ID {}), player damage {}",
                npc.getName(), npc.getId(), damage);
        return new Kill(npc, damage);
    }

    /**
     * Secondary kill confirmation for NPCs that reach 0 HP <em>without</em> a normal death —
     * gargoyles, rockslugs, lizards, zygomites, Grotesque Guardians (Dusk/Dawn) etc. are only
     * "finished" with a special item and never fire {@link ActorDeath}. Instead they linger in a
     * dying state and then despawn. {@link NpcUtil#isDying(NPC)} knows every such NPC, so if a
     * tracked (player-damaged) NPC is dying when it despawns, credit the kill here.
     *
     * <p>Normal kills are settled on the tick after their ActorDeath and remembered in
     * {@link #settledDeaths}, so their later despawn is never credited again. Otherwise this is
     * pure cleanup.
     */
    public Optional<Kill> onNpcDespawned(NpcDespawned event) {
        NPC npc = event.getNpc();
        int index = npc.getIndex();

        // Died and despawned within the same tick: settle it now, before the index is reused.
        NPC pending = pendingDeaths.remove(index);
        if (pending != null) {
            Kill kill = settle(index, pending);
            settledDeaths.remove(index);
            return Optional.ofNullable(kill);
        }

        boolean tracked = attackedNpcs.containsKey(index);
        // Always clear tracking for this NPC — whether or not it counts as a kill.
        // The index is free for reuse after despawn, so the settled-death guard ends here too.
        attackedNpcs.remove(index);
        Integer dmg = damageDealt.remove(index);
        boolean alreadySettled = settledDeaths.remove(index);

        if (tracked && !alreadySettled && npcUtil.isDying(npc)) {
            int damage = dmg != null ? dmg : 0;
            log.debug("Kill confirmed via NpcDespawned (finisher item): {} (ID {}), player damage {}",
                    npc.getName(), npc.getId(), damage);
            return Optional.of(new Kill(npc, damage));
        }
        return Optional.empty();
    }

    /** Clears all state on logout or world hop. */
    public void onGameStateChanged(GameStateChanged event) {
        GameState state = event.getGameState();
        if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING) {
            attackedNpcs.clear();
            damageDealt.clear();
            pendingDeaths.clear();
            settledDeaths.clear();
        }
    }
}

package com.bestiary.service;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureQuality;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;
import com.bestiary.model.MonsterRoster;
import com.bestiary.model.CombatClass;
import com.bestiary.util.RarityRoller;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.Optional;
import java.util.Random;

/**
 * Pure capture logic \u00e2\u20ac" no RuneLite event handling, no UI, no I/O.
 * Depends only on a Random instance, so it is easy to unit test.
 */
@Slf4j
@Singleton
public class CaptureService {

    private final Random rng;

    @Inject
    public CaptureService() {
        this.rng = new Random();
    }

    /** Constructor for tests where a seeded RNG is required. */
    CaptureService(Random rng) {
        this.rng = rng;
    }

    /**
     * Attempt to capture an NPC after a confirmed kill.
     *
     * @param npc           the NPC that was killed
     * @param location      where the kill happened
     * @param captureLevel  the player's current Capture Level
     * @param killCount     how many times this species has been killed before (used as metadata)
     * @param regionName    human-readable area name
     * @param playerName    the logged-in player's name
     * @return a populated {@link CapturedCreature} on success, or empty on failure
     */
    public Optional<CapturedCreature> attemptCapture(NPC npc, WorldPoint location,
                                                     int captureLevel, int killCount,
                                                     String regionName, String playerName,
                                                     int observedDamage, double shinyBonus,
                                                     double rarityUpChance, double doubleRollChance,
                                                     double[] catchRateBonusByTier) {
        // First full capture attempt (catch/miss roll + rarity + shiny + quality).
        Optional<CapturedCreature> first = singleAttempt(npc, location, captureLevel, killCount,
                regionName, playerName, observedDamage, shinyBonus, rarityUpChance, catchRateBonusByTier);

        // Keen Instinct (shop): a chance to run the WHOLE attempt a second time — including the
        // catch/miss roll — and keep the better outcome (a capture beats a miss; between two captures
        // the higher rarity, then Power Level, wins). Only when owned (doubleRollChance > 0); the
        // short-circuit means an unowned upgrade consumes no RNG, so the roll sequence stays stable.
        if (doubleRollChance > 0 && rng.nextDouble() < doubleRollChance) {
            Optional<CapturedCreature> second = singleAttempt(npc, location, captureLevel, killCount,
                    regionName, playerName, observedDamage, shinyBonus, rarityUpChance, catchRateBonusByTier);
            return keenKeepBetter(first, second);
        }
        return first;
    }

    /** One independent capture attempt: rolls catch/miss, then rarity + Fortune's Favour, shiny, quality. */
    private Optional<CapturedCreature> singleAttempt(NPC npc, WorldPoint location,
                                                     int captureLevel, int killCount,
                                                     String regionName, String playerName,
                                                     int observedDamage, double shinyBonus,
                                                     double rarityUpChance, double[] catchRateBonusByTier) {
        String npcName = npc.getName() != null ? npc.getName() : "Unknown";
        DifficultyTier difficulty = MonsterRoster.getDifficulty(npcName, npc.getCombatLevel());

        double catchBonus = (catchRateBonusByTier != null && difficulty.ordinal() < catchRateBonusByTier.length)
                ? catchRateBonusByTier[difficulty.ordinal()] : 0.0;
        double catchRate = calculateCatchRate(captureLevel, difficulty, catchBonus);
        double roll = rng.nextDouble();

        log.debug("Capture roll for {} [{}]: roll={} catchRate={}", npcName, difficulty.label,
                String.format("%.3f", roll), String.format("%.3f", catchRate));

        if (roll >= catchRate) {
            return Optional.empty();
        }

        CreatureRarity rarity = RarityRoller.roll(rng, captureLevel);
        // Fortune's Favour (shop): a chance to climb one rarity higher than the roll landed. Only
        // happens if the player owns the upgrade (rarityUpChance > 0); Mythic can't climb further.
        boolean fortuneBumped = false;
        CreatureRarity fortuneFrom = null;
        if (rarity != CreatureRarity.MYTHIC && rarityUpChance > 0
                && rng.nextDouble() < rarityUpChance) {
            fortuneFrom = rarity;
            rarity = CreatureRarity.values()[rarity.ordinal() + 1];
            fortuneBumped = true;
        }
        // Independent shiny roll — orthogonal to rarity. Base 0.2% at Bestiary level 1,
        // scaling linearly to 2% at level 99. Future shop unlocks / passives can multiply this.
        boolean shiny = rng.nextDouble() < shinyChance(captureLevel) + shinyBonus;

        CombatClass combatClass = MonsterRoster.getCombatClass(npcName, npc.getCombatLevel());
        int[] statBases = MonsterRoster.getStatBases(npcName, npc.getCombatLevel());
        int prayerBase  = MonsterRoster.getPrayer(npcName);
        CreatureQuality quality = RarityRoller.generateQuality(combatClass, rarity, statBases, prayerBase, rng, shiny);

        CapturedCreature creature = CapturedCreature.builder()
                .shiny(shiny)
                .shinyBonus(shinyBonus)
                .observedHp(observedDamage)
                .npcId(npc.getId())
                .npcName(npcName)
                .npcCombatLevel(npc.getCombatLevel())
                .rarity(rarity)
                .quality(quality)
                .captureTime(Instant.now())
                .regionName(regionName)
                .captureLevel(captureLevel)
                .killsBeforeCapture(killCount)
                .playerName(playerName != null ? playerName : "")
                .build();
        creature.fortuneBumped = fortuneBumped;
        creature.fortuneFrom = fortuneFrom;

        log.info("Captured {} [{}] difficulty={}{}", creature.npcName, creature.rarity.label,
                difficulty.label, fortuneBumped ? " (Fortune's Favour bumped)" : "");
        return Optional.of(creature);
    }

    /**
     * Keeps the better of two Keen Instinct capture attempts. Ranking: a capture beats a miss; between
     * two captures the higher rarity wins, then the higher Power Level. When the SECOND attempt is the
     * one kept (i.e. Keen Instinct actually improved on the first roll) and it either rescued a would-be
     * miss or landed a strictly higher rarity, the kept card is tagged so the plugin announces the proc.
     */
    private Optional<CapturedCreature> keenKeepBetter(Optional<CapturedCreature> first,
                                                      Optional<CapturedCreature> second) {
        boolean secondBetter;
        if (!second.isPresent()) {
            secondBetter = false;
        } else if (!first.isPresent()) {
            secondBetter = true;
        } else {
            int cmp = Integer.compare(second.get().rarity.ordinal(), first.get().rarity.ordinal());
            if (cmp == 0) cmp = Integer.compare(second.get().powerLevel(), first.get().powerLevel());
            secondBetter = cmp > 0;
        }

        if (secondBetter) {
            CapturedCreature kept = second.get();
            boolean firstMiss = !first.isPresent();
            // Only a rescued miss or a genuine rarity upgrade is worth a chat shout (a mere Power Level
            // tiebreak win is kept silently).
            if (firstMiss || kept.rarity.ordinal() > first.get().rarity.ordinal()) {
                kept.keenInstinctKept = kept.rarity;
                kept.keenInstinctFrom = firstMiss ? null : first.get().rarity;   // null = rescued a miss
            }
            return second;
        }
        return first;
    }

    /**
     * Catch rate by difficulty tier and capture level. Scales linearly from the level-1 base to the
     * level-99 max (base → max):
     *   BEGINNER: 25% → 70%
     *   EASY:     20% → 65%
     *   MEDIUM:   15% → 55%
     *   HARD:     10% → 50%
     *   ELITE:     5% → 35%
     *   BOSS:      3% → 25%
     */
    public static double calculateCatchRate(int captureLevel, DifficultyTier difficulty) {
        return calculateCatchRate(captureLevel, difficulty, 0.0);
    }

    /**
     * Catch rate as above, plus a flat shop catch-rate {@code bonus} (the Level 99 Elite/Boss Tracker
     * upgrades). The bonus is added after the level scaling and the whole thing is clamped below 100%
     * so a catch is never guaranteed.
     */
    public static double calculateCatchRate(int captureLevel, DifficultyTier difficulty, double bonus) {
        double base, max;
        switch (difficulty) {
            case BEGINNER: base = 0.25; max = 0.70; break;
            case EASY:     base = 0.20; max = 0.65; break;
            case MEDIUM:   base = 0.15; max = 0.55; break;
            case HARD:     base = 0.10; max = 0.50; break;
            case ELITE:    base = 0.05; max = 0.35; break;
            case BOSS:     base = 0.03; max = 0.25; break;
            default:       base = 0.15; max = 0.55; break;
        }
        double perLevel = (max - base) / 98.0;   // reaches the max exactly at level 99
        double rate = Math.min(base + (captureLevel - 1) * perLevel, max);
        return Math.min(rate + Math.max(0.0, bonus), 0.95);
    }

    /**
     * Independent shiny chance, scaled by Bestiary level.
     * 0.2% at level 1 → 2% at level 99 (linear). Rarity does not affect this.
     * Static so the dev seed can roll shinies the same way as live captures.
     */
    public static double shinyChance(int captureLevel) {
        double t = Math.max(0, Math.min(98, captureLevel - 1)) / 98.0;
        return 0.002 + t * (0.02 - 0.002);
    }
}

package com.bestiary.service;

import com.bestiary.model.Achievement;
import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;
import com.bestiary.model.MonsterRoster;
import com.bestiary.util.XpTable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Manages the Capture Level (1\u00e2\u20ac"100), XP accumulation, and achievement unlocks.
 * State is held in {@link ProgressionState} and persisted by {@link BestiaryDataService}.
 */
@Slf4j
@Singleton
public class ProgressionService {

    /** Mutable progression state \u00e2\u20ac" serialised independently of the collection. */
    public static class ProgressionState {
        public long totalXp = 0;
        public Set<Achievement> unlockedAchievements = EnumSet.noneOf(Achievement.class);
    }

    private ProgressionState state;
    private BestiaryCollection collection;

    /** Grants Bestiary Credits (level-up bounties + achievement rewards). Wired by BestiaryDataService. */
    private java.util.function.LongConsumer creditAwarder = amount -> {};

    /** Credits granted per level gained: {@code level * 10} (reach Lv2 -> 20, Lv99 -> 990). */
    public static long levelUpCredits(int level) {
        return level * 10L;
    }

    @Inject
    public ProgressionService() {
        this.state      = new ProgressionState();
        this.collection = new BestiaryCollection();
    }

    /** Sets the sink used to grant credits for level-ups and achievement unlocks. */
    public void setCreditAwarder(java.util.function.LongConsumer awarder) {
        this.creditAwarder = awarder != null ? awarder : amount -> {};
    }

    /** Called by BestiaryDataService after loading persisted data. */
    public void init(ProgressionState state, BestiaryCollection collection) {
        this.state      = state;
        this.collection = collection;
    }

    // --- XP ---

    /**
     * Awards Bestiary XP for a kill, scaled by the monster's difficulty tier
     * (Beginner 5 → Boss 30). Returns the newly unlocked level if a level-up occurred, or 0.
     */
    public int recordKill(NPC npc) {
        String name = npc.getName() != null ? npc.getName() : "";
        DifficultyTier tier = MonsterRoster.getDifficulty(name, npc.getCombatLevel());
        return addXp(killXp(tier));
    }

    /** Bestiary kill XP by difficulty tier: Beginner 5, Easy 10, Medium 15, Hard 20, Elite 25, Boss 30. */
    public static long killXp(DifficultyTier tier) {
        switch (tier) {
            case BEGINNER: return 5;
            case EASY:     return 10;
            case MEDIUM:   return 15;
            case HARD:     return 20;
            case ELITE:    return 25;
            case BOSS:     return 30;
            default:       return 10;
        }
    }

    /**
     * Awards capture XP: kill XP \u00c3\u2014 rarity multiplier.
     * Returns any newly unlocked achievements (may be empty).
     */
    public List<Achievement> recordCapture(CapturedCreature creature, boolean awardXp) {
        if (awardXp) {
            addXp(captureXp(creature.npcCombatLevel, creature.rarity));
        }
        return checkNewAchievements(creature);
    }

    /**
     * Capture XP = base × rarity multiplier, where base = max(10, combatLevel × 10) with the
     * combat level CAPPED at 100. The cap stops very-high-level monsters (which exist in droves)
     * from awarding runaway XP: nothing exceeds the combat-100 scale
     * (Common 1,000 → Mythic 50,000).
     */
    public static long captureXp(int npcCombatLevel, CreatureRarity rarity) {
        int combatLevel = Math.max(1, Math.min(100, npcCombatLevel));
        long base       = Math.max(10L, (long) combatLevel * 10);
        return Math.round(base * rarity.xpMultiplier);
    }

    /**
     * Awards arbitrary XP (kill or capture XP, including shop boosts already applied by the
     * caller) and returns the new level if a level-up occurred, otherwise 0.
     */
    public int awardXp(long xp) {
        return addXp(xp);
    }

    /** Current Capture Level (1\u00e2\u20ac"100). */
    public int getLevel() {
        return XpTable.levelForXp(state.totalXp);
    }

    /** Total accumulated XP. */
    public long getTotalXp() {
        return state.totalXp;
    }

    /** XP needed to advance from current total to the next level (0 at level 100). */
    public long getXpToNextLevel() {
        return XpTable.xpToNextLevel(state.totalXp);
    }

    public ProgressionState getState() {
        return state;
    }

    // --- Achievements ---

    /**
     * Checks all achievements against the current state and collection.
     * Returns newly unlocked achievements so the plugin can notify the player.
     */
    public List<Achievement> checkNewAchievements(CapturedCreature latestCapture) {
        List<Achievement> newly = new ArrayList<>();
        int level      = getLevel();
        // Catch-count achievements track LIFETIME captures (monotonic) — a discarded or transferred-away
        // card still counts, and a received card does not, so use lifetimeCaptures not the held-card count.
        int lifetimeCaps = (int) collection.lifetimeCaptures;
        int species      = (int) collection.uniqueSpeciesCount();

        for (Achievement a : Achievement.values()) {
            if (state.unlockedAchievements.contains(a)) {
                continue;
            }
            if (isUnlocked(a, latestCapture, lifetimeCaps, species, level)) {
                unlock(a, newly);
            }
        }
        return newly;
    }

    /** Marks an achievement unlocked, grants its credit reward, and records it for notification. */
    private void unlock(Achievement a, List<Achievement> newly) {
        state.unlockedAchievements.add(a);
        newly.add(a);
        if (a.creditReward > 0) creditAwarder.accept(a.creditReward);
        log.info("Achievement unlocked: {} (+{} credits)", a.title, a.creditReward);
    }

    /** Check kill-count achievements after incrementing kill count. Call on client thread. */
    /** Kill-count milestones, checked against the persisted total-kills counter. */
    private static final Achievement[] KILL_ACHIEVEMENTS = {
        Achievement.FIVE_HUNDRED_KILLS, Achievement.ONE_K_KILLS, Achievement.TWOFIVE_HUNDRED_KILLS,
        Achievement.FIVE_K_KILLS, Achievement.TEN_K_KILLS,
        Achievement.TWENTYFIVE_K_KILLS, Achievement.FIFTY_K_KILLS, Achievement.HUNDRED_K_KILLS
    };

    public List<Achievement> checkKillAchievements() {
        int totalKills = collection.totalKills();
        List<Achievement> newly = new ArrayList<>();
        for (Achievement a : KILL_ACHIEVEMENTS) {
            if (state.unlockedAchievements.contains(a)) continue;
            if (totalKills >= a.countThreshold) {
                unlock(a, newly);
            }
        }
        return newly;
    }

    private boolean isUnlocked(Achievement a, CapturedCreature capture,
                                int lifetimeCaps, int species, int level) {
        switch (a) {
            case FIRST_CATCH:
            case TEN_CATCHES:
            case FIFTY_CATCHES:
            case HUNDRED_CATCHES:
            case TWO_FIFTY_CATCHES:
            case FIVE_HUNDRED_CATCHES:
            case THOUSAND_CATCHES:
            case TWENTYFIVE_HUNDRED_CATCHES:
            case FIVE_K_CATCHES:
            case TEN_K_CATCHES:
                return !a.isSpeciesBased && lifetimeCaps >= a.countThreshold;

            case FIVE_SPECIES:
            case TWENTY_SPECIES:
            case FIFTY_SPECIES:
                return species >= a.countThreshold;

            case UNCOMMON_CATCH:
                return capture != null && capture.rarity.ordinal() >= CreatureRarity.UNCOMMON.ordinal();
            case RARE_CATCH:
                return capture != null && capture.rarity.ordinal() >= CreatureRarity.RARE.ordinal();
            case EPIC_CATCH:
                return capture != null && capture.rarity.ordinal() >= CreatureRarity.EPIC.ordinal();
            case LEGENDARY_CATCH:
                return capture != null && (capture.rarity == CreatureRarity.LEGENDARY
                        || capture.rarity == CreatureRarity.MYTHIC);
            case MYTHIC_CATCH:
                return capture != null && capture.rarity == CreatureRarity.MYTHIC;
            case SHINY_CATCH:
                return capture != null && capture.isShiny();

            case FIVE_HUNDRED_KILLS:
            case ONE_K_KILLS:
            case TWOFIVE_HUNDRED_KILLS:
            case FIVE_K_KILLS:
            case TEN_K_KILLS:
            case TWENTYFIVE_K_KILLS:
            case FIFTY_K_KILLS:
            case HUNDRED_K_KILLS:
                return false; // handled by checkKillAchievements()

            case LEVEL_5:   return level >= 5;
            case LEVEL_10:  return level >= 10;
            case LEVEL_25:  return level >= 25;
            case LEVEL_30:  return level >= 30;
            case LEVEL_40:  return level >= 40;
            case LEVEL_50:  return level >= 50;
            case LEVEL_60:  return level >= 60;
            case LEVEL_70:  return level >= 70;
            case LEVEL_75:  return level >= 75;
            case LEVEL_80:  return level >= 80;
            case LEVEL_85:  return level >= 85;
            case LEVEL_90:  return level >= 90;
            case LEVEL_92:  return level >= 92;
            case LEVEL_95:  return level >= 95;
            case LEVEL_99:  return level >= 99;
            case LEVEL_120: return level >= 120;

            // Total XP milestones (post-99 grind) — read from the persisted XP counter.
            case XP_25M: case XP_35M: case XP_50M: case XP_100M: case XP_150M: case XP_200M:
                return getTotalXp() >= a.countThreshold;

            // Credits earned / spent (lifetime)
            case EARN_1K: case EARN_5K: case EARN_10K: case EARN_50K: case EARN_100K:
                return collection.lifetimeCreditsEarned >= a.countThreshold;
            case SPEND_1K: case SPEND_5K: case SPEND_10K: case SPEND_50K: case SPEND_100K:
                return collection.lifetimeCreditsSpent >= a.countThreshold;

            // Rerolls
            case REROLL_FIRST: case REROLL_5: case REROLL_10: case REROLL_25: case REROLL_50:
                return collection.totalRerolls() >= a.countThreshold;
            case REROLL_RANK_UP:
                return collection.hasRerollRankUp();
            case REROLL_SHINY:
                return collection.hasRerolledShiny();
            case REROLL_NATTY_LEG:
                return collection.hasRerolledNatural(CreatureRarity.LEGENDARY);
            case REROLL_NATTY_MYTH:
                return collection.hasRerolledNatural(CreatureRarity.MYTHIC);

            // Collection milestones
            case POWERHOUSE:
                return collection.maxPowerLevel() >= 150;
            case PWR_300:  return collection.maxPowerLevel() >= 300;
            case PWR_500:  return collection.maxPowerLevel() >= 500;
            case PWR_700:  return collection.maxPowerLevel() >= 700;
            case PWR_800:  return collection.maxPowerLevel() >= 800;
            case PWR_1000: return collection.maxPowerLevel() >= 1000;
            case FULL_HOUSE:
                return collection.hasFullRaritySet();
            case CHROMATIC:
                return collection.shinyCount() >= a.countThreshold;
            case COMPLETIONIST:
                return collection.isAlbumComplete();
            case CURATED:
                return collection.hasFavourite();
            case NAME_A_CARD:
                return collection.hasNamedCard();

            // Discard milestones (recorded going-forward at discard time)
            case DISCARD_SHINY:     return collection.discardedShiny;
            case DISCARD_LEGENDARY: return collection.discardedLegendary;
            case DISCARD_MYTHIC:    return collection.discardedMythic;
            case DISCARD_1K: case DISCARD_5K: case DISCARD_10K:
                return collection.largestDiscardBatch >= a.countThreshold;

            // Per-rarity dex completion
            case DEX_COMMON:     return collection.hasFullRarityDex(CreatureRarity.COMMON);
            case DEX_UNCOMMON:   return collection.hasFullRarityDex(CreatureRarity.UNCOMMON);
            case DEX_RARE:       return collection.hasFullRarityDex(CreatureRarity.RARE);
            case DEX_EPIC:       return collection.hasFullRarityDex(CreatureRarity.EPIC);
            case DEX_LEGENDARY:  return collection.hasFullRarityDex(CreatureRarity.LEGENDARY);
            case DEX_MYTHIC:     return collection.hasFullRarityDex(CreatureRarity.MYTHIC);

            default: return false;
        }
    }

    /** Adds XP (capped at the 200M max) and returns the new level if a level-up occurred, otherwise 0. */
    private int addXp(long xp) {
        int before       = getLevel();
        state.totalXp    = Math.min(XpTable.maxXp(), state.totalXp + xp);
        int after        = getLevel();
        // Grant a per-level credit bounty for every level gained (handles multi-level jumps).
        for (int lvl = before + 1; lvl <= after; lvl++) {
            creditAwarder.accept(levelUpCredits(lvl));
        }
        return after > before ? after : 0;
    }
}

package com.bestiary.service;

import com.bestiary.model.Achievement;
import com.bestiary.model.BestiaryCollection;
import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureQuality;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.MonsterRoster;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Random;
import java.util.stream.Collectors;

/**
 * Loads and saves the bestiary collection and progression state as JSON (via
 * {@link BestiaryStore}). The whole collection lives in memory here; mutations update it
 * and then persist a snapshot — debounced for high-frequency events (kills, credits),
 * immediate for valuable/rare ones (captures, rerolls, discards) and lifecycle events.
 */
@Slf4j
@Singleton
public class BestiaryDataService {

    private final ProgressionService progressionService;
    private final BestiaryStore store;

    /** The "played" collection — the logged-in character. All mutators write here. */
    private BestiaryCollection collection = new BestiaryCollection();
    private ProgressionService.ProgressionState progressionState = new ProgressionService.ProgressionState();

    /** The active account (RuneLite accountHash), or null while logged out. */
    private Long activeAccountHash;
    /** Display name (RSN) of the active account, for dialog headers. */
    private String activeAccountName = "";

    // --- View-any-account (#48): a read-only overlay of another account's collection. ---
    /** Non-null while viewing another account; the UI reads this instead of the played collection. */
    private BestiaryCollection viewedCollection;
    /** RSN of the account being viewed (for the read-only banner + dialog headers). */
    private String viewedAccountName = "";
    /** accountHash of the account being viewed (so the dropdown can mark the selection). */
    private Long viewedAccountHash;
    /** The viewed account's stored lifetime XP, so its level can be shown without touching progression. */
    private long viewedTotalXp;
    /** The viewed account's unlocked achievements, for read-only dashboards while viewing. */
    private EnumSet<Achievement> viewedAchievements;

    @Inject
    public BestiaryDataService(ProgressionService progressionService, BestiaryStore store) {
        this.progressionService = progressionService;
        this.store = store;
        // Let progression grant credits for level-ups and achievement unlocks.
        progressionService.setCreditAwarder(this::awardCredits);
        // Wire progression to the (empty) logged-out state so nothing NPEs before an account loads.
        progressionService.init(progressionState, collection);
    }

    // -------------------------------------------------------------------------
    // Lifecycle
    // -------------------------------------------------------------------------

    /**
     * Switches to {@code accountHash}'s collection: flushes the current account, repoints the store,
     * and loads that account's data (or an empty collection for a first-seen account). Called on
     * {@code LOGGED_IN} from the client thread. No-ops on a repeated hash (e.g. world hops) so an
     * in-progress session's unsaved state isn't reloaded away.
     */
    public boolean switchAccount(long accountHash, String rsn) {
        if (activeAccountHash != null && activeAccountHash == accountHash) {
            // Same account (e.g. a later tick once the RSN is available, or a world hop): just
            // fill in / refresh the display name and registry entry. No reload.
            if (rsn != null && !rsn.isEmpty() && !rsn.equals(activeAccountName)) {
                activeAccountName = rsn;
                store.setActiveAccount(accountHash, rsn);
            }
            return false;
        }
        clearView();                                   // a real account change drops any read-only view
        if (activeAccountHash != null) persistNow();   // flush the previously active account
        activeAccountHash = accountHash;
        activeAccountName = rsn != null ? rsn : "";
        store.setActiveAccount(accountHash, activeAccountName);
        load();
        return true;
    }

    /**
     * Handles logout (return to the login screen): flushes the active account to disk, deactivates
     * the store, and clears the in-memory collection/progression so no account's data lingers in the
     * (logged-out) UI. The next login reloads that account's data fresh from disk.
     */
    public void handleLogout() {
        clearView();                  // drop any read-only view — nothing is browsable while logged out
        if (activeAccountHash == null) return;
        persistNow();                 // flush the active account to its own file first
        store.clearActiveAccount();
        activeAccountHash = null;
        activeAccountName = "";
        collection       = new BestiaryCollection();
        progressionState = new ProgressionService.ProgressionState();
        progressionService.init(progressionState, collection);
    }

    /** True once a character has logged in and its collection is loaded. */
    public boolean hasActiveAccount() {
        return activeAccountHash != null;
    }

    /** Builds an in-memory collection from a stored snapshot (shared by played load + viewed load). */
    private static BestiaryCollection hydrateCollection(BestiaryStore.StoreData d) {
        BestiaryCollection col = new BestiaryCollection();
        for (CapturedCreature c : d.captures) {
            // Migration: pre-#49 saves have no owner fields — seed them from the capturer.
            if (c.originalOwner == null || c.originalOwner.isEmpty()) c.originalOwner = c.playerName;
            if (c.currentOwner == null || c.currentOwner.isEmpty()) {
                c.currentOwner = c.originalOwner != null && !c.originalOwner.isEmpty()
                        ? c.originalOwner : c.playerName;
            }
            col.creatures.add(c);
            col.captureCountByNpc.merge(c.npcName, 1, Integer::sum);
        }
        col.killCounts   = new HashMap<>(d.killCounts);
        col.credits      = d.credits;
        col.lifetimeCreditsEarned = d.lifetimeCreditsEarned;
        col.lifetimeCreditsSpent  = d.lifetimeCreditsSpent;
        // Legacy saves predate lifetime tracking — baseline "earned" from the current balance
        // so the economy dashboard/achievements aren't zeroed for existing players.
        if (col.lifetimeCreditsEarned == 0 && col.credits > 0) {
            col.lifetimeCreditsEarned = col.credits;
        }
        col.shopUpgrades = new HashMap<>(d.shopUpgrades);
        col.lifetimeCardsSent = d.lifetimeCardsSent;
        col.lifetimeCardsDiscarded = d.lifetimeCardsDiscarded;
        col.discardedShiny = d.discardedShiny;
        col.discardedLegendary = d.discardedLegendary;
        col.discardedMythic = d.discardedMythic;
        col.largestDiscardBatch = d.largestDiscardBatch;

        // Lifetime captures: prefer the stored counter, but baseline it from the cards this account
        // actually caught (not traded-in) so pre-#N accounts don't read 0. Because own-caught-held can
        // never exceed true lifetime captures, the max() is a safe one-time floor, self-correcting once
        // the counter is tracked live (received cards are excluded, so they never inflate "Caught").
        col.lifetimeCaptures = Math.max(d.lifetimeCaptures, col.ownCaughtHeldCount());
        col.lifetimeCapturesByNpc = new HashMap<>(d.lifetimeCapturesByNpc);
        // Per-species baseline = max(stored, own-caught-held for that species).
        java.util.Map<String, Integer> ownHeldByNpc = new HashMap<>();
        for (CapturedCreature c : col.creatures) {
            if (!BestiaryCollection.isTradedIn(c)) ownHeldByNpc.merge(c.npcName, 1, Integer::sum);
        }
        for (java.util.Map.Entry<String, Integer> e : ownHeldByNpc.entrySet()) {
            col.lifetimeCapturesByNpc.merge(e.getKey(), e.getValue(), Math::max);
        }
        return col;
    }

    // -------------------------------------------------------------------------
    // View any account (read-only, #48)
    // -------------------------------------------------------------------------

    /**
     * The collection the UI should display: the read-only viewed account if one is selected (#48),
     * otherwise the played account. Every panel/dialog reads through here, so switching the view
     * updates the whole UI. Mutators deliberately do NOT go through this — they write the played
     * collection directly, so captures always land on the logged-in character even while viewing.
     */
    public BestiaryCollection getCollection() {
        return viewedCollection != null ? viewedCollection : collection;
    }

    /** The played (logged-in) collection, regardless of any active view. */
    public BestiaryCollection getPlayedCollection() {
        return collection;
    }

    /** True while a read-only view of another account is active. */
    public boolean isViewing() {
        return viewedCollection != null;
    }

    /** RSN of the account currently being viewed (empty when not viewing). */
    public String getViewedAccountName() {
        return viewedAccountName;
    }

    /** accountHash of the account currently being viewed, or null when not viewing. */
    public Long getViewedAccountHash() {
        return viewedAccountHash;
    }

    /**
     * Loads {@code accountHash}'s collection read-only for display (#48). Never writes it back.
     * No-ops (and clears any view) if the target is the played account. Returns true if a view
     * is now active.
     */
    public boolean viewAccount(long accountHash, String rsn) {
        if (activeAccountHash != null && activeAccountHash == accountHash) {
            clearView();   // "viewing" your own account just means the normal played view
            return false;
        }
        BestiaryStore.StoreData d = store.readAccount(accountHash);
        viewedCollection    = hydrateCollection(d);
        viewedTotalXp       = d.totalXp;
        viewedAchievements  = parseAchievements(d.achievements);
        viewedAccountHash   = accountHash;
        viewedAccountName   = rsn != null ? rsn : "";
        return true;
    }

    /** Drops the read-only view and returns the UI to the played account. */
    public void clearView() {
        viewedCollection    = null;
        viewedAchievements  = null;
        viewedAccountHash   = null;
        viewedAccountName   = "";
        viewedTotalXp       = 0;
    }

    /** All known accounts from the registry (for the switcher dropdown), most-recently-active first. */
    public java.util.List<BestiaryStore.AccountRef> listAllAccounts() {
        return store.listAccounts();
    }

    /** accountHash of the played (logged-in) account, or null while logged out. */
    public Long getActiveAccountHash() {
        return activeAccountHash;
    }

    /**
     * Bestiary level to DISPLAY: the viewed account's level (from its stored XP via {@link XpTable})
     * when viewing, else the live played level. Keeps view mode collection-only (no dual progression).
     */
    public int getDisplayLevel() {
        return viewedCollection != null
                ? com.bestiary.util.XpTable.levelForXp(viewedTotalXp)
                : progressionService.getLevel();
    }

    /** Lifetime XP to DISPLAY — the viewed account's stored XP when viewing, else the played total. */
    public long getDisplayTotalXp() {
        return viewedCollection != null ? viewedTotalXp : progressionState.totalXp;
    }

    /** XP remaining to the next level for the DISPLAYED account (viewed or played). */
    public long getDisplayXpToNextLevel() {
        if (viewedCollection == null) return progressionService.getXpToNextLevel();
        int lvl = com.bestiary.util.XpTable.levelForXp(viewedTotalXp);
        long nextStart = com.bestiary.util.XpTable.xpForLevel(
                Math.min(lvl + 1, com.bestiary.util.XpTable.MAX_VIRTUAL_LEVEL));
        return Math.max(0, nextStart - viewedTotalXp);
    }

    /** Unlocked achievements to DISPLAY — the viewed account's set when viewing, else the played set. */
    public java.util.Set<Achievement> getDisplayAchievements() {
        return viewedCollection != null && viewedAchievements != null
                ? viewedAchievements : progressionState.unlockedAchievements;
    }

    // -------------------------------------------------------------------------
    // Intra-profile card transfer (#50)
    // -------------------------------------------------------------------------

    /** Known accounts other than the active one — candidate targets for a card transfer. */
    public java.util.List<BestiaryStore.AccountRef> listOtherAccounts() {
        java.util.List<BestiaryStore.AccountRef> all = store.listAccounts();
        all.removeIf(a -> activeAccountHash != null && a.hash == activeAccountHash);
        return all;
    }

    /**
     * Moves {@code cards} from the active account to another of the player's accounts (#50). Writes
     * the target file FIRST (append), then removes the cards from the active collection and persists,
     * so a failed target write can never lose a card. Updates {@code currentOwner} (originalOwner is
     * preserved). Returns the number actually transferred.
     */
    public int transferCards(java.util.Collection<CapturedCreature> cards, long targetHash, String targetRsn) {
        if (isViewing()) return 0;   // read-only while viewing another account
        if (activeAccountHash != null && targetHash == activeAccountHash) return 0;  // can't send to self
        java.util.List<CapturedCreature> moving = new ArrayList<>();
        for (CapturedCreature c : cards) {
            if (collection.creatures.contains(c)) moving.add(c);
        }
        if (moving.isEmpty()) return 0;

        // Update owners and append to the target file first; roll back the owner change if it fails.
        java.util.Map<CapturedCreature, String> priorOwner = new HashMap<>();
        BestiaryStore.StoreData target = store.readAccount(targetHash);
        for (CapturedCreature c : moving) {
            priorOwner.put(c, c.currentOwner);
            c.transferTo(targetRsn);
            target.captures.add(c);
        }
        if (!store.writeAccountNow(targetHash, target)) {
            for (CapturedCreature c : moving) c.currentOwner = priorOwner.get(c);
            log.warn("Card transfer aborted: could not write target account {}", targetHash);
            return 0;
        }

        for (CapturedCreature c : moving) collection.removeCapture(c);
        collection.lifetimeCardsSent += moving.size();   // lifetime "sent" tally (not a capture change)
        persistNow();
        log.info("Transferred {} card(s) to {}", moving.size(), targetRsn);
        return moving.size();
    }

    /** RSN of the active account (empty while logged out). */
    public String getActiveAccountName() {
        return activeAccountName;
    }

    /** Loads the active account's data into memory. Must be called from the client thread. */
    public void load() {
        BestiaryStore.StoreData d = store.load();
        collection = hydrateCollection(d);

        progressionState = new ProgressionService.ProgressionState();
        progressionState.totalXp = d.totalXp;
        progressionState.unlockedAchievements = parseAchievements(d.achievements);

        progressionService.init(progressionState, collection);
        log.info("Bestiary loaded: {} captures", collection.totalCaptures());
    }

    /** Flushes the current state to disk immediately. Called from UI callbacks after edits. */
    public void saveNow() {
        persistNow();
    }

    /** Debounced save. Kept for API compatibility with callers that don't need an immediate flush. */
    public void scheduleSave() {
        persist();
    }

    /** Permanently deletes all data and resets in-memory state. */
    public void wipeCollection() {
        clearView();     // reset acts on the played account — leave any view behind
        collection       = new BestiaryCollection();
        progressionState = new ProgressionService.ProgressionState();
        progressionService.init(progressionState, collection);
        persistNow();
        log.info("Bestiary collection wiped");
    }

    /** Flushes and stops the store writer. Call from plugin shutDown. */
    public void shutdown() {
        persistNow();
        store.close();
    }

