        NAMES.put(13362, "Varrock Southeast");
        NAMES.put(12599, "Varrock North");
        NAMES.put(11576, "Death Plateau");
        NAMES.put(11577, "Trollheim");
        NAMES.put(11833, "Skull");
        NAMES.put(11834, "North of Edgeville");
        NAMES.put(12086, "Monastery");
        NAMES.put(12087, "South Wilderness");
    }

    private RegionNames() {}

    public static String get(int regionId) {
        String name = NAMES.get(regionId);
        return name != null ? name : approximateZone(regionId);
    }

    /**
     * Decodes rx/ry from the region ID (rx = worldX/64, ry = worldY/64) and maps
     * to a broad zone name. Used as a fallback when the exact region isn't in NAMES.
     * Surface y tops out near 4160 (ry ≈ 65); anything above is underground/instanced.
     */
    private static String approximateZone(int regionId) {
        int rx = regionId >> 8;    // worldX / 64
        int ry = regionId & 0xFF;  // worldY / 64

        if (ry > 65) return "Underground";

        // Wilderness: north of Edgeville latitude
        if (ry >= 55 && rx >= 43 && rx <= 53) return "Wilderness";

        // Morytania: east of the River Salve. Real Morytania surface starts at rx >= 54
        // (Canifis, Mort Myre, Burgh de Rott…); the rx == 53 column is eastern Misthalin
        // (its only genuine Morytania spot, the Slayer Tower, is in the explicit name map).
        if (rx >= 54 && ry >= 48) return "Morytania";

        // Great Kourend / Zeah: far west
        if (rx <= 28) return "Great Kourend";

        // Fremennik: north, central
        if (rx >= 36 && rx <= 43 && ry >= 56) return "Fremennik";

        // Tirannwn: west of Kandarin
        if (rx >= 32 && rx <= 38 && ry >= 47 && ry <= 54) return "Tirannwn";

        // Karamja: south, central
        if (rx >= 42 && rx <= 48 && ry >= 42 && ry <= 48) return "Karamja";

        // Desert: south-east. The desert proper sits at ry <= 47 (Pollnivneach, Sophanem…);
        // ry 48-50 at this longitude is the Al Kharid / eastern-Misthalin gateway, not desert.
        if (ry <= 47 && rx >= 49) return "Desert";

        // Kandarin: west-central
        if (rx >= 39 && rx <= 46 && ry >= 48 && ry <= 57) return "Kandarin";

        // Asgarnia: central-west
        if (rx >= 43 && rx <= 49 && ry >= 48 && ry <= 55) return "Asgarnia";

        // Misthalin: central (default for known surface coords)
        if (rx >= 48 && ry >= 48) return "Misthalin";

        return "Unknown";
    }
}

package com.bestiary.util;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.InputStream;

import javax.imageio.ImageIO;

/**
 * The Bestiary panel / Plugin Hub icon: the golden "B" crest, bundled as a resource
 * ({@code /com/bestiary/logo.png}) and scaled on demand. This is the single source of truth for
 * both the in-client sidebar button ({@link #render}) and the repo-root {@code icon.png} the
 * Plugin Hub lists ({@link #main}). Replace the bundled PNG and regenerate the file — see {@link #main}.
 *
 * <p>Intentionally free of external dependencies (no logging framework) so {@link #main} can be run
 * standalone from the compiled classes without a runtime classpath.
 */
public final class PanelIcon {

    /** Bundled logo art, loaded once. */
    private static final String RESOURCE = "/com/bestiary/logo.png";
    private static BufferedImage source;

    private PanelIcon() {}

    private static synchronized BufferedImage source() {
        if (source == null) {
            try (InputStream in = PanelIcon.class.getResourceAsStream(RESOURCE)) {
                if (in != null) {
                    source = ImageIO.read(in);
                }
            } catch (Exception e) {
                // Silent: render() falls back to a drawn placeholder if the resource can't be loaded.
                source = null;
            }
        }
        return source;
    }

    /** Renders the logo at {@code s}×{@code s} pixels (ARGB), smooth-scaled from the bundled art. */
    public static BufferedImage render(int s) {
        BufferedImage icon = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        BufferedImage src = source();
        if (src != null) {
            g.drawImage(src, 0, 0, s, s, null);
        } else {
            // Fallback if the resource is missing: a dark tile with a gold "B" so the button isn't blank.
            g.setColor(new Color(13, 22, 38));
            g.fillRect(0, 0, s, s);
            g.setColor(new Color(240, 190, 40));
            g.setFont(new java.awt.Font("SansSerif", java.awt.Font.BOLD, Math.round(s * 0.7f)));
            java.awt.FontMetrics fm = g.getFontMetrics();
            g.drawString("B", (s - fm.stringWidth("B")) / 2f,
                    (s - fm.getHeight()) / 2f + fm.getAscent());
        }

        g.dispose();
        return icon;
    }

    /**
     * Writes the icon to a PNG so the repo-root {@code icon.png} (the Plugin Hub listing image)
     * always matches the in-client sidebar icon. Run after replacing the bundled logo:
     * {@code java -cp build/classes/java/main;build/resources/main com.bestiary.util.PanelIcon icon.png}
     */
    public static void main(String[] args) throws Exception {
        System.setProperty("java.awt.headless", "true");
        String out = args.length > 0 ? args[0] : "icon.png";
        // The Plugin Hub caps the listing icon at 48x72px, so render at 48. The in-client sidebar
        // button doesn't use this file — it calls render(s) at the nav-button size directly.
        ImageIO.write(render(48), "png", new File(out));
    }
}

package com.bestiary.util;

import com.bestiary.model.CombatClass;
import com.bestiary.model.CreatureQuality;
import com.bestiary.model.CreatureRarity;

import java.util.Random;

public final class RarityRoller {

    private RarityRoller() {}

    public static CreatureRarity roll(Random rng) {
        return roll(rng, 1);
    }

    /**
     * Rolls a rarity with weights shifted toward rarer outcomes at higher capture levels.
     * At level 1, weights match the base probabilities exactly.
     * At level 99, COMMON weight halves while MYTHIC weight is 12x the base.
     */
    /** Level-scaled rarity weight multipliers (index matches CreatureRarity.ordinal()). */
    private static final double[] LEVEL_TARGET_MULT = {0.50, 1.30, 2.00, 4.00, 8.00, 12.0};

    public static CreatureRarity roll(Random rng, int captureLevel) {
        double[] weights = rarityWeights(captureLevel);
        double total = 0.0;
        for (double w : weights) total += w;

        double roll = rng.nextDouble() * total;
        double cumulative = 0.0;
        CreatureRarity[] rarities = CreatureRarity.values();
        for (int i = 0; i < rarities.length; i++) {
            cumulative += weights[i];
            if (roll < cumulative) return rarities[i];
        }
        return CreatureRarity.COMMON;
    }

    private static double[] rarityWeights(int captureLevel) {
        double t = Math.max(0, Math.min(98, captureLevel - 1)) / 98.0;
        CreatureRarity[] rarities = CreatureRarity.values();
        double[] weights = new double[rarities.length];
        for (int i = 0; i < rarities.length; i++) {
            weights[i] = rarities[i].probability * (1.0 + t * (LEVEL_TARGET_MULT[i] - 1.0));
        }
        return weights;
    }

    /** Probability (0..1) that a rarity roll at the given capture level yields {@code r}. */
    public static double rarityChance(int captureLevel, CreatureRarity r) {
        double[] weights = rarityWeights(captureLevel);
        double total = 0.0;
        for (double w : weights) total += w;
        return weights[r.ordinal()] / total;
    }

    /** Legacy uniform-floor variant — treats {@code floor} as every stat's base (incl. Prayer). */
    public static CreatureQuality generateQuality(CombatClass cls, CreatureRarity rarity,
                                                  int floor, Random rng) {
        int[] bases = {floor, floor, floor, floor, floor, floor};
        return generateQuality(cls, rarity, bases, floor, rng, false);
    }

    /**
     * Rarity-multiplier stat model.
     *
     * The reviewed per-stat bases (MonsterRoster.STAT_BASES) represent an "average"
     * (Epic) card, so each rarity simply scales them:
     *   centre[i] = base[i] × rarity.statMultiplier   (Common ×0.70 … Epic ×1.0 … Mythic ×1.20)
     * then a small uniform wiggle in [-WIGGLE, +WIGGLE] is added and the result is clamped 1..99.
     *
     * Shiny adds {@link #SHINY_MULT_BONUS} to the multiplier and takes the top of the wiggle
     * band (deterministic best roll). The combat class is no longer used to spike stats — the
     * per-stat bases already encode each monster's offensive profile (it remains a display label).
     */
    public static CreatureQuality generateQuality(CombatClass cls, CreatureRarity rarity,
                                                  int[] bases, int prayerBase, Random rng, boolean shiny) {
        // Bases for all 7 stats: the 6 combat/agility bases + Prayer (index 6).
        int[] allBases = {bases[0], bases[1], bases[2], bases[3], bases[4], bases[5], prayerBase};
        int[] stats = new int[7];
        for (int i = 0; i < 7; i++) {
            // Agility (index 5) and Prayer (index 6) are utility stats rolled at HALF scale.
            boolean utility = (i == AGILITY_INDEX || i == PRAYER_INDEX);
            int[] band = utility ? utilityBand(allBases[i], rarity) : statBand(allBases[i], rarity);
            if (shiny) {
                // Anchor to the TOP of the band + bonus, so a shiny always beats a
                // same-rarity non-shiny (which can only reach band top). Utility stats
                // get half the bonus, matching their half-scale bands.
                int fullBonus = SHINY_MIN_BONUS + rng.nextInt(SHINY_MAX_BONUS - SHINY_MIN_BONUS + 1); // +6..+20
                stats[i] = clampStat(band[1] + (utility ? fullBonus / 2 : fullBonus));
            } else {
                stats[i] = band[0] + (band[1] > band[0] ? rng.nextInt(band[1] - band[0] + 1) : 0);
            }
        }
        return new CreatureQuality(stats[0], stats[1], stats[2], stats[3], stats[4], stats[5], stats[6]);
    }

    // Unified stat model. Every rarity rolls a band expressed as a LIFT FRACTION of the
    // headroom (cap − base): stat = base + L × (99 − base), with L uniform in [lo, hi].
    // Because the fraction bands OVERLAP in lift-space (each row's lo < the row above's… i.e.
    // next.lo < cur.hi), the resulting stat bands overlap at EVERY base — a lucky Rare can
    // beat an unlucky Epic, a lucky Legendary an unlucky Mythic, etc. Epic ≈ base (centred on
    // 0). Rare/Uncommon/Common can dip below base (negative lift) but are floored at 1; low
    // rarities still get real upward spread for weak monsters (base 1 Rare ≈ 1–10).
    // Index = CreatureRarity.ordinal(): Common, Uncommon, Rare, Epic, Legendary, Mythic.
    private static final double[] LIFT_LO = {-0.26, -0.18, -0.11, 0.00, 0.12, 0.40};
    private static final double[] LIFT_HI = { 0.01,  0.04,  0.07, 0.22, 0.50, 0.82};
    private static final int STAT_CAP = 99;

    /** The inclusive [lo, hi] range a non-shiny stat rolls in at this rarity (floored at 1). */
    public static int[] statBand(int base, CreatureRarity rarity) {
        int i  = rarity.ordinal();
        int hr = STAT_CAP - base;
        int lo = clampStat(base + LIFT_LO[i] * hr);
        int hi = clampStat(base + LIFT_HI[i] * hr);
        if (hi < lo) hi = lo;
        return new int[]{lo, hi};
    }

    /** The "expected" value for a stat at a rarity (band midpoint). */
    public static int statCentre(int base, CreatureRarity rarity) {
        int i = rarity.ordinal();
        double midLift = (LIFT_LO[i] + LIFT_HI[i]) / 2.0;
        return clampStat(base + midLift * (STAT_CAP - base));
    }

    /** Stats never drop below 1 or exceed 99. */
    private static int clampStat(double v) {
        return Math.max(1, Math.min(99, (int) Math.round(v)));
    }

    /** A shiny stat rolls its expected value plus a uniform bonus in [MIN, MAX]. */
    public static final int SHINY_MIN_BONUS = 6;
    public static final int SHINY_MAX_BONUS = 20;

    /** The [lo, hi] range a SHINY stat rolls in: band top + [MIN, MAX] bonus (clamped). */
    public static int[] shinyBand(int base, CreatureRarity rarity) {
        int hi = statBand(base, rarity)[1];
        return new int[]{clampStat(hi + SHINY_MIN_BONUS), clampStat(hi + SHINY_MAX_BONUS)};
    }

    // Prayer AND Agility are "utility" stats rolled at HALF scale (the other five are full-scale
    // combat stats). They stay ~1 for low-base monsters at low rarity and only climb at high
    // rarity / shiny (base 1 → ~40 at Mythic). Same banded, overlapping model — just halved lift.
    public static final int    AGILITY_INDEX = 5;
    public static final int    PRAYER_INDEX  = 6;
    public static final double UTILITY_SCALE = 0.5;

    /** The inclusive [lo, hi] range a non-shiny utility stat (Prayer/Agility) rolls in. */
    public static int[] utilityBand(int base, CreatureRarity rarity) {
        int i = rarity.ordinal();
        int hr = STAT_CAP - base;
        int lo = clampStat(base + UTILITY_SCALE * LIFT_LO[i] * hr);
        int hi = clampStat(base + UTILITY_SCALE * LIFT_HI[i] * hr);
        if (hi < lo) hi = lo;
        return new int[]{lo, hi};
    }

    /** A utility stat's expected value at a rarity (band midpoint). */
    public static int utilityCentre(int base, CreatureRarity rarity) {
        int i = rarity.ordinal();
        double midLift = (LIFT_LO[i] + LIFT_HI[i]) / 2.0;
        return clampStat(base + UTILITY_SCALE * midLift * (STAT_CAP - base));
    }

    /** The [lo, hi] range a SHINY utility stat rolls in: band top + half bonus (clamped). */
    public static int[] shinyUtilityBand(int base, CreatureRarity rarity) {
        int hi = utilityBand(base, rarity)[1];
        return new int[]{clampStat(hi + SHINY_MIN_BONUS / 2), clampStat(hi + SHINY_MAX_BONUS / 2)};
    }
}

package com.bestiary.util;

import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;

/**
 * Computes Bestiary Credits awarded for a capture.
 *
 * Credits = difficultyBase × rarityMultiplier, doubled for a shiny.
 * The two curves are intentionally separate from the XP curve so the economy
 * can be retuned independently as the Shop (#39) is designed.
 *
 * Sample awards:
 *   Beginner Common          = 2
 *   Medium   Rare            = 20
 *   Boss     Legendary       = 280
 *   Boss     Mythic          = 480   (shiny: 960)
 */
public final class CreditCalculator {

    private CreditCalculator() {}

    private static int difficultyBase(DifficultyTier tier) {
        switch (tier) {
            case BEGINNER: return 2;
            case EASY:     return 4;
            case MEDIUM:   return 8;
            case HARD:     return 15;
            case ELITE:    return 25;
            case BOSS:     return 40;
            default:       return 8;
        }
    }

    private static double rarityMultiplier(CreatureRarity rarity) {
        switch (rarity) {
            case COMMON:    return 1.0;
            case UNCOMMON:  return 1.6;
            case RARE:      return 2.5;
            case EPIC:      return 4.0;
            case LEGENDARY: return 7.0;
            case MYTHIC:    return 12.0;
            default:        return 1.0;
        }
    }

    /** Credits awarded for a single capture. Shiny doubles the reward. Minimum 1. */
    public static long forCapture(DifficultyTier tier, CreatureRarity rarity, boolean shiny) {
        double credits = difficultyBase(tier) * rarityMultiplier(rarity);
        if (shiny) credits *= 2.0;
        return Math.max(1L, Math.round(credits));
    }

    /** Flat credit bonus a shiny adds when discarded. */
    public static final long SHINY_DISCARD_BONUS = 500L;

    /**
     * Credits refunded for discarding a card = its base (non-shiny) capture value,
     * plus a flat {@link #SHINY_DISCARD_BONUS} for shinies. Minimum 1.
     */
    public static long forDiscard(DifficultyTier tier, CreatureRarity rarity, boolean shiny) {
        return forCapture(tier, rarity, false) + (shiny ? SHINY_DISCARD_BONUS : 0L);
    }
}

package com.bestiary.util;

import com.bestiary.model.CapturedCreature;
import com.bestiary.model.CreatureRarity;
import com.bestiary.model.DifficultyTier;
import com.bestiary.model.MonsterRoster;
import com.bestiary.service.CaptureService;

import java.util.ArrayList;
import java.util.List;

/**
 * Reconstructs the probability of a specific capture from its stored data
 * (capture level, rarity, shiny, per-stat values) using the live formulas:
 *   catch  = {@link CaptureService#calculateCatchRate}
 *   rarity = {@link RarityRoller#rarityChance}
 *   shiny  = {@link CaptureService#shinyChance}
 *   stats  = base × rarity multiplier ± uniform wiggle ({@link RarityRoller#WIGGLE})
 */
public final class OddsCalculator {

    private static final String[] STAT_NAMES = {"Attack", "Strength", "Defence", "Magic", "Ranged", "Agility"};

    private OddsCalculator() {}

    public static final class StatOdds {
        public final String name;
        public final int base;       // the monster's base value for this stat
        public final int value;      // the rolled value on the card
        public final int centre;     // the rarity's expected value for this stat
        public final int lo, hi;     // the rarity's roll band for this stat (overlaps neighbours)
        StatOdds(String name, int base, int value, int centre, int lo, int hi) {
            this.name = name; this.base = base; this.value = value;
            this.centre = centre; this.lo = lo; this.hi = hi;
        }
    }

    public static final class Result {
        public int level;
        public DifficultyTier difficulty;
        public CreatureRarity rarity;
        public boolean shiny;
        public double shinyBonus;     // passive Shiny Charm bonus that applied to this card (0 = none)
        public double catchChance;    // 0..1 — chance a kill yields a capture
        public double rarityChance;   // 0..1 — chance a capture is this rarity
        public double shinyChance;    // 0..1 — chance of the shiny outcome (shiny or not)
        public List<StatOdds> stats = new ArrayList<>();
        // Power Level inputs
        public int statSum;   // sum of all 7 rolled stats (incl. Prayer)
        public int hp;
        public int combatLevel;
        public int powerLevel;
        public int avgPowerLevel;      // Power Level if every stat (prayer included) rolled its band centre
        public int avgShinyPowerLevel; // ...if every stat rolled the centre of its SHINY band
        // Combined odds (stat wiggle is NOT a factor)
        public double perCapture;     // rarity × shiny  — "of your captures, how often this card"
        public double perKill;        // catch × rarity × shiny — "how rare was the whole event"
    }

    public static Result compute(CapturedCreature c) {
        Result r = new Result();
        r.level      = Math.max(1, c.captureLevel);
        r.difficulty = MonsterRoster.getDifficulty(c.npcName, c.npcCombatLevel);
        r.rarity     = c.rarity;
        r.shiny      = c.isShiny();

        r.catchChance  = CaptureService.calculateCatchRate(r.level, r.difficulty);
        r.rarityChance = RarityRoller.rarityChance(r.level, r.rarity);
        // Use the shiny bonus that applied to THIS card (at its capture/reroll), not the current one,
        // so a card caught before the Shiny Charm was unlocked still shows its true odds.
        r.shinyBonus   = Math.max(0.0, c.shinyBonus);
        double sc      = Math.min(1.0, CaptureService.shinyChance(r.level) + r.shinyBonus);
        r.shinyChance  = r.shiny ? sc : (1.0 - sc);

        int[] bases = MonsterRoster.getStatBases(c.npcName, c.npcCombatLevel);
        int[] vals  = {c.quality.attack, c.quality.strength, c.quality.defence,
                       c.quality.magic, c.quality.ranged, c.quality.agility};
        // Combat stats ATK..RNG (0-4), then Prayer, then Agility (5) — prayer sits before agility.
        // When shiny, the shown band is the shiny roll range so the quality tag reflects it.
        for (int i = 0; i < 5; i++) {
            int centre = RarityRoller.statCentre(bases[i], r.rarity);
            int[] band = r.shiny ? RarityRoller.shinyBand(bases[i], r.rarity)
                                 : RarityRoller.statBand(bases[i], r.rarity);
            r.stats.add(new StatOdds(STAT_NAMES[i], bases[i], vals[i], centre, band[0], band[1]));
        }
        // Prayer is a utility stat (half scale).
        int prayerBase = MonsterRoster.getPrayer(c.npcName);
        int[] pBand = r.shiny ? RarityRoller.shinyUtilityBand(prayerBase, r.rarity)
                             : RarityRoller.utilityBand(prayerBase, r.rarity);
        r.stats.add(new StatOdds("Prayer", prayerBase, c.quality.prayer,
                RarityRoller.utilityCentre(prayerBase, r.rarity), pBand[0], pBand[1]));
        // Agility is a utility stat too — half scale, same as Prayer.
        int centreAgi = RarityRoller.utilityCentre(bases[5], r.rarity);
        int[] bandAgi = r.shiny ? RarityRoller.shinyUtilityBand(bases[5], r.rarity)
                               : RarityRoller.utilityBand(bases[5], r.rarity);
        r.stats.add(new StatOdds(STAT_NAMES[5], bases[5], vals[5], centreAgi, bandAgi[0], bandAgi[1]));

        // Power Level inputs
        r.statSum    = c.quality.statSum();
        r.hp         = c.hitpoints();
        r.powerLevel = c.powerLevel();
        // Combat level is a second factual difficulty term (1/6 weight, same as HP); mirror powerLevel().
        int cmb = Math.max(0, c.npcCombatLevel);
        r.combatLevel = cmb;

        // Average-roll Power Level for this rarity: every stat at its band centre. Agility (5)
        // and Prayer are utility stats (half scale); the other five are full-scale combat stats.
        int avgStatSum = 0;
        for (int i = 0; i < 6; i++) {
            avgStatSum += (i == RarityRoller.AGILITY_INDEX)
                    ? RarityRoller.utilityCentre(bases[i], r.rarity)
                    : RarityRoller.statCentre(bases[i], r.rarity);
        }
        r.avgPowerLevel = Math.round(
                (avgStatSum + RarityRoller.utilityCentre(prayerBase, r.rarity)) / 7f + r.hp / 6f + cmb / 6f);

        // Average SHINY roll for this rarity: every stat at the centre of its shiny band.
        int avgShinyStatSum = 0;
        for (int i = 0; i < 6; i++) {
            int[] sb = (i == RarityRoller.AGILITY_INDEX)
                    ? RarityRoller.shinyUtilityBand(bases[i], r.rarity)
                    : RarityRoller.shinyBand(bases[i], r.rarity);
            avgShinyStatSum += (sb[0] + sb[1]) / 2;
        }
        int[] pShiny = RarityRoller.shinyUtilityBand(prayerBase, r.rarity);
        r.avgShinyPowerLevel = Math.round(
                (avgShinyStatSum + (pShiny[0] + pShiny[1]) / 2) / 7f + r.hp / 6f + cmb / 6f);

        // Stat wiggle is flavour, not part of "how rare is this card" — only rarity (and shiny) count.
        r.perCapture = r.rarityChance * (r.shiny ? r.shinyChance : 1.0);
        r.perKill    = r.catchChance * r.perCapture;
        return r;
    }

    /** Formats a 0..1 probability as "1 in N" (N comma-grouped). */
    public static String oneIn(double p) {
        if (p <= 0) return "≈ impossible";
        if (p >= 1) return "certain";
        long n = Math.round(1.0 / p);
        return "1 in " + String.format("%,d", n);
    }

    /** Formats a 0..1 probability as a percentage with sensible precision. */
    public static String pct(double p) {
        double v = p * 100.0;
        if (v >= 10)   return String.format("%.0f%%", v);
        if (v >= 1)    return String.format("%.1f%%", v);
        if (v >= 0.01) return String.format("%.2f%%", v);
        return String.format("%.4f%%", v);
    }
}

package com.bestiary.util;

/**
 * Maps between Capture Level and cumulative XP.
 *
 * Uses the official OSRS XP formula: Points(L) = floor((L + 300 * 2^(L/7)) / 4).
 * XP required for level L = sum of Points(1) to Points(L-1).
 *
 * Level 99 (13,034,431 XP) is the "true" skill cap used for milestones such as
 * the Capture Master achievement. Past 99 the curve continues into RuneScape-style
 * virtual levels up to level 126, which is reached at the 200M XP cap. XP keeps
 * counting (and the level keeps advancing) until 200M.
 *
 * Spot-check:
 *   Level  10 =        1,154 XP
 *   Level  50 =      101,333 XP
 *   Level  99 =   13,034,431 XP
 *   Level 126 =  188,884,740 XP
 */
public final class XpTable {

    /** The "true" skill cap (used for the Capture Master milestone). */
    public static final int MAX_LEVEL = 99;

    /** Highest virtual level, reached at the 200M XP cap. */
    public static final int MAX_VIRTUAL_LEVEL = 126;

    /** OSRS-style experience cap. */
    public static final long MAX_XP = 200_000_000L;

    /** XP_FOR_LEVEL[L] = XP needed to reach level L (index 0 and 1 are both 0). */
    private static final long[] XP_FOR_LEVEL = new long[MAX_VIRTUAL_LEVEL + 1];

    static {
        double accumulator = 0;
        for (int level = 1; level <= MAX_VIRTUAL_LEVEL; level++) {
            XP_FOR_LEVEL[level] = (long) accumulator;
            double points = Math.floor((level + 300.0 * Math.pow(2.0, level / 7.0)) / 4.0);
            accumulator += points;
        }
    }

    private XpTable() {}

    /** Returns the level (1-126) for a given total XP amount. */
    public static int levelForXp(long xp) {
        for (int level = MAX_VIRTUAL_LEVEL; level >= 1; level--) {
            if (xp >= XP_FOR_LEVEL[level]) {
                return level;
            }
        }
        return 1;
    }

    /** Returns the total XP required to reach the given level. */
    public static long xpForLevel(int level) {
        if (level < 1)                  return 0;
        if (level > MAX_VIRTUAL_LEVEL)  return XP_FOR_LEVEL[MAX_VIRTUAL_LEVEL];
        return XP_FOR_LEVEL[level];
    }

    /** Returns the XP still needed to advance from the current total to the next level (0 at level 126). */
    public static long xpToNextLevel(long currentXp) {
        int currentLevel = levelForXp(currentXp);
        if (currentLevel >= MAX_VIRTUAL_LEVEL) return 0;
        return XP_FOR_LEVEL[currentLevel + 1] - currentXp;
    }

    /** The 200M XP cap. */
    public static long maxXp() {
        return MAX_XP;
    }
}
